    /** 概述类别顺序（固定）；与 frontend OVERVIEW_CATEGORY_ORDER / COMPONENT_CATEGORY_ORDER 同序，修改须同步。 */
    private static final List<String> CATEGORY_ORDER = java.util.Arrays.asList(
            "汽机", "锅炉本体", "四大管道", "机炉外管道", "钢结构", "其他");

    /**
     * 与前端 aggregateDetectionLogOrder.sortCategoriesForOverview 一致：标准类按 CATEGORY_ORDER，自定义类在其后按中文拼音。
     */
    private static List<String> sortCategoriesForOverview(Set<String> categories) {
        if (categories == null || categories.isEmpty()) {
            return Collections.emptyList();
        }
        List<String> ordered = new ArrayList<>();
        for (String c : CATEGORY_ORDER) {
            if (categories.contains(c)) {
                ordered.add(c);
            }
        }
        Collator collator = Collator.getInstance(Locale.CHINA);
        List<String> rest = categories.stream()
                .filter(c -> !CATEGORY_ORDER.contains(c))
                .sorted(collator)
                .collect(Collectors.toList());
        ordered.addAll(rest);
        return ordered;
    }

