    /**
     * 项目人员信息数据类
     */
    private static class ProjectPersonnelInfo {
        String approverNdt = "";
        String approverChem = "";
        String reviewerNdt = "";
        String reviewerChem = "";
        String writerNdt = "";
        String writerChem = "";
        LocalDate approvalDate;
        LocalDate reviewDate;
        LocalDate writerDate;
    }

    /**
     * 获取项目的审批/审核/编写人员信息和日期
     * @param project 项目对象
     * @return 项目人员信息对象
     */
    private ProjectPersonnelInfo getProjectPersonnelInfo(Project project) {
        ProjectPersonnelInfo info = new ProjectPersonnelInfo();
        
        // 获取无损检测和理化检测的人员信息
        info.approverNdt = project.getApproverNdt() != null ? project.getApproverNdt() : "";
        info.reviewerNdt = project.getReviewerNdt() != null ? project.getReviewerNdt() : "";
        info.writerNdt = project.getWriterNdt() != null ? project.getWriterNdt() : "";
        
        info.approverChem = project.getApproverChem() != null ? project.getApproverChem() : "";
        info.reviewerChem = project.getReviewerChem() != null ? project.getReviewerChem() : "";
        info.writerChem = project.getWriterChem() != null ? project.getWriterChem() : "";
        
        // 获取日期信息（优先使用无损检测的日期，如果为空则使用理化检测的日期）
        info.approvalDate = project.getApprovalDateNdt() != null ? project.getApprovalDateNdt() : 
                           (project.getApprovalDateChem() != null ? project.getApprovalDateChem() : null);
        info.reviewDate = project.getReviewDateNdt() != null ? project.getReviewDateNdt() : 
                         (project.getReviewDateChem() != null ? project.getReviewDateChem() : null);
        info.writerDate = project.getWriterDateNdt() != null ? project.getWriterDateNdt() : 
                         (project.getWriterDateChem() != null ? project.getWriterDateChem() : null);
        
        return info;
    }

    /**
     * 格式化日期为签名格式
     */
    private String formatDateForSignature(LocalDate date) {
        if (date == null) {
            return "";
        }
        return date.format(DateTimeFormatter.ofPattern("yyyy.MM.dd"));
    }

    /**
     * 格式化日期为摘要格式
     */
    private String formatDateForSummary(LocalDate date) {
        if (date == null) {
            return "";
        }
        return date.format(DateTimeFormatter.ofPattern("yyyy年MM月dd日"));
    }

   
    private Path getSignaturesDirectory() {
        Path sigPath = Paths.get(signaturesDir);
        // 如果是相对路径，转换为绝对路径
        if (!sigPath.isAbsolute()) {
            // 获取应用运行目录
            String userDir = System.getProperty("user.dir");
            sigPath = Paths.get(userDir).resolve(signaturesDir).normalize();
        }
        return sigPath;
    }

