    /** 编号类列相对原均等列宽的倍数（检测结果表） */
    private static final double NUMBER_COLUMN_WIDTH_MULTIPLIER = 1.5;

    /**
     * 检测结果表：指定列为「编号」类列，宽度为均等列宽的 multiplier 倍，其余列平分剩余宽度；总和严格等于 totalWidth（twips）。
     */
    private static int[] distributeWidthsWithWiderNumberColumns(
            int totalWidth, int columnCount, double numberWidthMultiplier, int... numberColumnIndices) {
        if (columnCount <= 0) {
            return new int[0];
        }
        Set<Integer> numCols = new HashSet<>();
        for (int idx : numberColumnIndices) {
            if (idx >= 0 && idx < columnCount) {
                numCols.add(idx);
            }
        }
        int k = numCols.size();
        int restCols = columnCount - k;
        if (k == 0 || restCols <= 0) {
            int[] w = new int[columnCount];
            int base = totalWidth / columnCount;
            int rem = totalWidth % columnCount;
            for (int i = 0; i < columnCount; i++) {
                w[i] = base + (i < rem ? 1 : 0);
            }
            return w;
        }
        int equalBase = totalWidth / columnCount;
        int numW = (int) Math.round(equalBase * numberWidthMultiplier);
        numW = Math.max(1, numW);
        int remaining = totalWidth - k * numW;
        while (remaining < restCols && numW > 1) {
            numW--;
            remaining = totalWidth - k * numW;
        }
        int baseOther = remaining / restCols;
        int extra = remaining % restCols;
        int[] widths = new int[columnCount];
        int nonNumOrdinal = 0;
        for (int i = 0; i < columnCount; i++) {
            if (numCols.contains(i)) {
                widths[i] = numW;
            } else {
                widths[i] = baseOther + (nonNumOrdinal < extra ? 1 : 0);
                nonNumOrdinal++;
            }
        }
        return widths;
    }

