    /**
     * 正文带内容页眉/页脚的锚点：项目详情页<strong>首段</strong>上「连续分节」的 {@code CTSectPr}。
     * 勿把带内容的页眉绑在声明页末的 {@code NEXT_PAGE} 段上——Word 常仍把该节页眉画在声明页，而详情及后续无页眉。
     */
    private static final ThreadLocal<CTSectPr> MAIN_BODY_HDR_SECT_PR = new ThreadLocal<>();

    /**
     * 超声/相控阵检测内容多行拆分：当前段对应 rows 下标、总行数。
     * 每段按当前 perContentRow 分块输出缺陷溢出附页；附图与「详见附图」每段均可带。
     */
    private static final ThreadLocal<Integer> UT_MULTI_ROW_ROW_INDEX = new ThreadLocal<>();
    private static final ThreadLocal<Integer> UT_MULTI_ROW_TOTAL = new ThreadLocal<>();

    private void beginUtMultiRowPass(int rowIndex, int totalRows) {
        UT_MULTI_ROW_ROW_INDEX.set(rowIndex);
        UT_MULTI_ROW_TOTAL.set(totalRows);
    }

    private void endUtMultiRowPass() {
        UT_MULTI_ROW_ROW_INDEX.remove();
        UT_MULTI_ROW_TOTAL.remove();
    }

    private boolean isUtMultiRowActive() {
        Integer t = UT_MULTI_ROW_TOTAL.get();
        return t != null && t > 1;
    }

    private int currentUtDetectionContentRowIndex() {
        Integer idx = UT_MULTI_ROW_ROW_INDEX.get();
        return idx != null ? idx : 0;
    }

    /** 多行检测内容拆分为 Word/概述/文本预览的段数：仅 UT/PAUT 按检测内容行数；其余类型多部件仍为单段。 */
    private int reportWordSegmentCount(Report report, ExperimentType experimentType) {
        int contentRows = detectionContentNarrativeService.countDetectionContentTableRows(report);
        if (contentRows <= 1) {
            return 1;
        }
        if (experimentType != null && experimentType.getCode() != null) {
            String code = experimentType.getCode();
            if ("UT".equals(code) || "PAUT".equals(code)) {
                return contentRows;
            }
        }
        return 1;
    }

    /** 库内 report_number 在 UT 多段拆分时按段递增（末尾序号 + rowIndex）。 */
    private String storedReportNumberWithUtRowOffset(Report report) {
        String stored = report.getReportNumber();
        if (!isUtMultiRowActive() || stored == null || stored.isEmpty()) {
            return stored;
        }
        int offset = currentUtDetectionContentRowIndex();
        if (offset <= 0) {
            return stored;
        }
        return ThirdPartyReportNumbering.withTrailingSequenceOffset(stored, offset);
    }

    private String utDetectionContentNarrativeBody(Report report, ExperimentType expType) {
        if (isUtMultiRowActive()) {
            return detectionContentNarrativeService.buildDetectionContentNarrativeSingleRow(
                    report, expType, currentUtDetectionContentRowIndex());
        }
        return detectionContentNarrativeService.getEffectiveNarrativeBody(report, expType);
    }

    private void beginBrandingPass(Project project, boolean thirdPartyAppendix) {
        BRANDING_PROJECT.set(project);
        BRANDING_THIRD_PARTY_APPENDIX.set(thirdPartyAppendix);
    }

    private void clearBrandingContext() {
        BRANDING_THIRD_PARTY_APPENDIX.remove();
        BRANDING_PROJECT.remove();
        CURRENT_REPORT_INDEX_1_BASED.remove();
        SUMMARY_DECLARATION_BREAK_SECT_PR.remove();
        MAIN_BODY_HDR_SECT_PR.remove();
    }

    private static boolean isAntiWearExplosionProject(Project project) {
        if (project == null || project.getProjectType() == null) {
            return false;
        }
        return PROJECT_TYPE_ANTI_WEAR_EXPLOSION.equals(project.getProjectType().trim());
    }

    private static boolean usesThirdPartyBranding(Project project, Report report) {
        if (isAntiWearExplosionProject(project)) {
            // 防磨防爆项目统一走润电模板，不再拆分第三方子集
            return false;
        }
        return InternalInspectorWhitelist.reportUsesThirdPartyBranding(report);
    }

    /**
     * 标题/页眉/页脚等处公司名：第三方附录段用第三方名称（未填写则为占位「未输入」）；润电段或未设置 BRANDING 时为润电全称。
     */
    private String brandingCompanyName() {
        Boolean tp = BRANDING_THIRD_PARTY_APPENDIX.get();
        if (tp == null || Boolean.FALSE.equals(tp)) {
            return RUNDIAN_COMPANY_NAME;
        }
        Project p = BRANDING_PROJECT.get();
        if (p == null) {
            return "";
        }
        String n = p.getThirdPartyName();
        if (n != null && !n.isBlank()) {
            return n.trim();
        }
        return ThirdPartyPlaceholders.NOT_ENTERED;
    }

    /**
     * 单项报告编号展示：
     * 总报告润电段：子集内 projectNumber-001 递增（与概述全局编号可不同）；
     * 总报告第三方段：思维奇/自定义 thirdPartyProjectNumber-001 递增；华图 thirdPartyProjectNumber-{TYPE}{001} 按类型递增；
     * 未设置 ThreadLocal 时（如单独导出单项）：用库内 report_number。
     */
    private String brandingReportNumberForDisplay(Report report) {
        Boolean tp = BRANDING_THIRD_PARTY_APPENDIX.get();
        Project p = BRANDING_PROJECT.get();
        Integer idx = CURRENT_REPORT_INDEX_1_BASED.get();
        Integer displayIdx = idx;
        if (displayIdx != null && isUtMultiRowActive()) {
            displayIdx = displayIdx + currentUtDetectionContentRowIndex();
        }

        if (Boolean.TRUE.equals(tp)) {
            if (p == null || displayIdx == null) {
                return storedReportNumberWithUtRowOffset(report);
            }
            String base = ThirdPartyPlaceholders.effectiveThirdPartyProjectNumberBase(p.getThirdPartyProjectNumber());
            if (ThirdPartyReportNumbering.usesPerTypeNumbering(p.getThirdPartyName())) {
                return ThirdPartyReportNumbering.formatHuatuNumber(
                        base, resolveExperimentTypeCodeForReport(report), displayIdx);
            }
            return ThirdPartyReportNumbering.formatLegacyNumber(base, displayIdx);
        }

        // 润电段：总报告上下文中用子集序号 + 内部项目编号
        if (p != null && displayIdx != null && p.getProjectNumber() != null && !p.getProjectNumber().trim().isEmpty()) {
            return p.getProjectNumber().trim() + "-" + String.format("%03d", displayIdx);
        }
        return storedReportNumberWithUtRowOffset(report);
    }

    @Override
    public byte[] generateReportAsync(Report report) {
        Objects.requireNonNull(report, "报告不能为null");
        Project project = report.getProject();
        if (project == null) {
            throw new IllegalArgumentException("报告未关联项目，无法生成单项Word");
        }
        if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
            throw new IllegalArgumentException("报告没有检测数据，无法生成单项Word");
        }

        try (XWPFDocument document = new XWPFDocument();
             ByteArrayOutputStream out = new ByteArrayOutputStream()) {

            ensureProjectReportsLoadedForWord(project);

            setPageSizeA4(document, false);
            setDocumentMarginsCm(document, 2.6, 2.6, 2.5, 2.6);
            enableUpdateFieldsOnOpen(document);

            List<Report> ordered = getReportsInOverviewOrder(project);
            syncReportNumbersToOverviewOrder(project, ordered);

            boolean thirdPartyBranding = usesThirdPartyBranding(project, report);
            int subsetIndex = resolveBrandingDisplayIndex1Based(project, report, ordered, thirdPartyBranding);

            beginBrandingPass(project, thirdPartyBranding);
            CURRENT_REPORT_INDEX_1_BASED.set(subsetIndex);
            try {
                dispatchReportGeneration(report, project, subsetIndex, document);
            } finally {
                clearBrandingContext();
            }

            document.write(out);
            return out.toByteArray();
        } catch (IllegalArgumentException e) {
            throw e;
        } catch (Exception e) {
            log.error("Error generating report word document", e);
            throw new RuntimeException("生成Word文档失败", e);
        }
    }

    /** 与总报告生成前一致：拉全项目报告及关联，供概述顺序与编号同步 */
    private void ensureProjectReportsLoadedForWord(Project project) {
        if (project.getReports() == null) {
            return;
        }
        project.getReports().size();
        for (Report r : project.getReports()) {
            if (r.getReportItems() != null) {
                r.getReportItems().size();
                r.getReportItems().forEach(ri -> {
                    if (ri.getExperimentType() != null) {
                        ri.getExperimentType().getName();
                    }
                });
            }
            if (r.getImageAttachments() != null) {
                r.getImageAttachments().size();
            }
        }
        if (project.getProjectImageAttachments() != null) {
            project.getProjectImageAttachments().size();
        }
    }

    /**
     * 当前报告在「润电子集 / 第三方子集」内按概述顺序的 1-based 序号（与总报告正文循环一致）。
     */
    private static int computeBrandingSubsetIndex1Based(
            Project project, Report target, List<Report> orderedOverview, boolean thirdPartyBranding) {
        int idx = 1;
        for (Report r : orderedOverview) {
            if (usesThirdPartyBranding(project, r) != thirdPartyBranding) {
                continue;
            }
            if (Objects.equals(r.getId(), target.getId())) {
                return idx;
            }
            idx++;
        }
        return 1;
    }

    /**
     * 华图第三方：当前报告在概述顺序第三方子集中、同检测类型内的 1-based 序号。
     */
    private int computeBrandingTypeIndex1Based(
            Project project, Report target, List<Report> orderedOverview) {
        String targetCode = resolveExperimentTypeCodeForReport(target);
        int idx = 1;
        for (Report r : orderedOverview) {
            if (!usesThirdPartyBranding(project, r)) {
                continue;
            }
            if (!targetCode.equals(resolveExperimentTypeCodeForReport(r))) {
                continue;
            }
            if (Objects.equals(r.getId(), target.getId())) {
                return idx;
            }
            idx++;
        }
        return 1;
    }

    /** 展示用序号：华图第三方按检测类型子集，其余按润电/第三方全局子集。 */
    private int resolveBrandingDisplayIndex1Based(
            Project project, Report target, List<Report> orderedOverview, boolean thirdPartyBranding) {
        if (thirdPartyBranding && ThirdPartyReportNumbering.usesPerTypeNumbering(project.getThirdPartyName())) {
            return computeBrandingTypeIndex1Based(project, target, orderedOverview);
        }
        return computeBrandingSubsetIndex1Based(project, target, orderedOverview, thirdPartyBranding);
    }

    private String resolveExperimentTypeCodeForReport(Report report) {
        ExperimentType et = resolveExperimentTypeForReport(report);
        if (et != null && et.getCode() != null && !et.getCode().isBlank()) {
            return et.getCode().trim();
        }
        return "UNK";
    }

    @Override
    public byte[] generateProjectSummaryAsync(Project project) {
        // ✅ 参数校验 - 防止空指针异常
        Objects.requireNonNull(project, "项目对象不能为null");
        Objects.requireNonNull(project.getProjectName(), "项目名称不能为null");
        Objects.requireNonNull(project.getProjectNumber(), "项目编号不能为null");
        
        if (project.getReports() == null || project.getReports().isEmpty()) {
            throw new IllegalArgumentException("项目没有可生成的报告");
        }
        
        ensureProjectReportsLoadedForWord(project);
        // 概述顺序：类别/部件不变；编号为润电/第三方各自子集（见 syncReportNumbersToOverviewOrder）
        List<Report> orderedReports = getReportsInOverviewOrder(project);
        syncReportNumbersToOverviewOrder(project, orderedReports);

        List<Report> runDianReports = new ArrayList<>();
        for (Report r : orderedReports) {
            if (!usesThirdPartyBranding(project, r)) {
                runDianReports.add(r);
            }
        }

        try (XWPFDocument document = new XWPFDocument();
             ByteArrayOutputStream out = new ByteArrayOutputStream()) {

            MAIN_BODY_HDR_SECT_PR.remove();

            // 设置页面大小（A4）- 只在Body级别设置一次，新节会继承这个设置
            setPageSizeA4(document, false);

            // 设置Body级别的SectPr为0边距（第一个节，封皮页）
            setDocumentMarginsCm(document, 2.6, 2.6, 2.5, 2.6);

            /* 打开文档时自动更新域，使目录 PAGEREF 与页脚页码首次打开即可显示 */
            enableUpdateFieldsOnOpen(document);

            generateCoverPage(document, project);
           

            // 添加页面
            generateProjectSummaryPage(document, project);


            // 生成项目信息页面
            generateProjectInfoPage(document, project);

            // 生成第一个单项报告摘要界面（概述与库内 report_number 一致，双轨编号）
            generateReportSummary(document, project, orderedReports);
            
            // 添加换页符，确保第一个单项报告在新页开始
            document.createParagraph().createRun().addBreak(BreakType.PAGE);

            ensureMainBodyHeaderFooter(document, project);

            // 总报告正文仅保留润电单项，第三方完整版改为用户上传附件拼到文末。
            try {
                appendRunDianSingleReportsOnly(document, project, runDianReports);
                appendProjectReportFigures(document, project);
                appendUploadedThirdPartyFullAtEnd(document, project);
                mirrorMainBodyHeaderFooterRefsToBodySectPrIfNeeded(document, project);
            } finally {
                clearBrandingContext();
            }

            document.write(out);
            return out.toByteArray();
        } catch (Exception e) {
            log.error("Error generating project summary word document", e);
            throw new RuntimeException("生成项目总报告失败", e);
        }
    }

    @Override
    public byte[] generateThirdPartyOnlyProjectWordAsync(Project project) {
        Objects.requireNonNull(project, "项目对象不能为null");
        Objects.requireNonNull(project.getProjectName(), "项目名称不能为null");
        Objects.requireNonNull(project.getProjectNumber(), "项目编号不能为null");

        if (project.getReports() == null || project.getReports().isEmpty()) {
            throw new IllegalArgumentException("项目没有可生成的报告");
        }

        List<Report> orderedReports = getReportsInOverviewOrder(project);
        syncReportNumbersToOverviewOrder(project, orderedReports);

        boolean antiWearExplosion = isAntiWearExplosionProject(project);
        List<Report> thirdPartyReports = new ArrayList<>();
        List<Report> runDianReports = new ArrayList<>();
        for (Report r : orderedReports) {
            if (usesThirdPartyBranding(project, r)) {
                thirdPartyReports.add(r);
            } else {
                runDianReports.add(r);
            }
        }
        if (!antiWearExplosion && thirdPartyReports.isEmpty()) {
            throw new IllegalArgumentException("当前项目没有需要第三方样式的单项报告");
        }

        try (XWPFDocument document = new XWPFDocument();
             ByteArrayOutputStream out = new ByteArrayOutputStream()) {

            setPageSizeA4(document, false);
            setDocumentMarginsCm(document, 2.6, 2.6, 2.5, 2.6);

            try {
                // 第三方专用导出：只含第三方样式单项；防磨防爆项目无第三方子集，仍输出润电模板单项
                if (antiWearExplosion) {
                    appendRunDianThenThirdPartySingleReports(document, project, runDianReports, thirdPartyReports);
                } else {
                    appendRunDianThenThirdPartySingleReports(
                            document, project, Collections.emptyList(), thirdPartyReports);
                }
                appendProjectReportFigures(document, project);
            } finally {
                clearBrandingContext();
            }

            document.write(out);
            return out.toByteArray();
        } catch (Exception e) {
            log.error("Error generating third-party-only project word document", e);
            throw new RuntimeException("生成第三方报告失败", e);
        }
    }

    @Override
    public byte[] generateTechnicalSupervisionNotifications(Project project, List<Integer> reportIds) {
        Objects.requireNonNull(project, "项目对象不能为null");
        if (reportIds == null || reportIds.isEmpty()) {
            throw new IllegalArgumentException("请至少选择一条报告");
        }
        if (project.getProjectNumber() == null || project.getProjectNumber().trim().isEmpty()) {
            throw new IllegalArgumentException("项目编号不能为空");
        }
        HashSet<Integer> unique = new HashSet<>(reportIds);
        if (unique.size() != reportIds.size()) {
            throw new IllegalArgumentException("报告不能重复选择");
        }

        List<Report> ordered = getReportsInOverviewOrder(project);
        List<Report> toGenerate = new ArrayList<>();
        for (Report r : ordered) {
            if (!unique.contains(r.getId())) {
                continue;
            }
            validateReportForDetectionNotification(project, r);
            toGenerate.add(r);
        }
        if (toGenerate.size() != reportIds.size()) {
            throw new IllegalArgumentException("所选报告无效、不属于当前项目或不符合缺陷/日期条件");
        }

        String tzBase = project.getProjectNumber().trim().replaceFirst("BG", "TZ");

        try (XWPFDocument document = new XWPFDocument();
             ByteArrayOutputStream out = new ByteArrayOutputStream()) {
            setPageSizeA4(document, false);
            setDocumentMarginsCm(document, 2.2, 2.2, 2.0, 2.0);

            int seq = 1;
            for (Report report : toGenerate) {
                String formNumber = tzBase + "-" + String.format("%03d", seq);
                ExperimentType expType = resolveExperimentTypeForReport(report);
                ProjectComponent component = resolveComponentForReport(report);
                String equipmentName = resolveComponentDisplayNameForNotification(report, component);
                List<ProjectComponent> notifyComps = resolveComponentsForReport(report);
                String workDesc = " " + buildWorkDescriptionForDetectionNotification(report, expType);
                int segments = reportWordSegmentCount(report, expType);
                String conclusion;
                if (segments <= 1) {
                    conclusion = normalizeNotificationConclusionForCell(
                            buildDetectionNotificationConclusion(report, expType, 0));
                } else {
                    List<String> blockParts = new ArrayList<>();
                    for (int row = 0; row < segments; row++) {
                        if (isRowBasedNdtNotification(expType) && !hasDefectInTableDataBlock(report, row)) {
                            continue;
                        }
                        String blockText = buildDetectionNotificationConclusion(report, expType, row);
                        if (blockText == null || blockText.isBlank()) {
                            continue;
                        }
                        String compName = resolveComponentDisplayNameForOverviewRow(report, notifyComps, row);
                        blockParts.add("对" + compName + "："
                                + normalizeNotificationConclusionForCell(blockText));
                    }
                    conclusion = blockParts.isEmpty() ? " " : String.join("；", blockParts);
                }
                String problemBody = workDesc + "其中，发现缺陷如下：" + conclusion;

                appendTechnicalSupervisionNotificationPage(document, project, report, formNumber, problemBody, equipmentName);

                List<ImageInfo> notificationImages = collectImageInfosForReport(report);
                if (!notificationImages.isEmpty()) {
                    document.createParagraph().createRun().addBreak(BreakType.PAGE);
                    int imagesPerPage = 2;
                    int contPages = (notificationImages.size() + imagesPerPage - 1) / imagesPerPage;
                    AtomicInteger imageNumber = new AtomicInteger(1);
                    for (int pageIndex = 0; pageIndex < contPages; pageIndex++) {
                        int start = pageIndex * imagesPerPage;
                        int end = Math.min(start + imagesPerPage, notificationImages.size());
                        appendTechnicalSupervisionNotificationContinuationPage(document, project, report,
                                formNumber, equipmentName, notificationImages.subList(start, end), imageNumber);
                        if (pageIndex < contPages - 1) {
                            document.createParagraph().createRun().addBreak(BreakType.PAGE);
                        }
                    }
                }

                if (seq < toGenerate.size()) {
                    document.createParagraph().createRun().addBreak(BreakType.PAGE);
                }
                seq++;
            }

            document.write(out);
            return out.toByteArray();
        } catch (IllegalArgumentException e) {
            throw e;
        } catch (Exception e) {
            log.error("Error generating technical supervision notifications", e);
            throw new RuntimeException("生成检测通知单失败", e);
        }
    }

    @Override
    public byte[] generateMergedFormalReportsWord(List<Report> reportsInOrder) {
        Objects.requireNonNull(reportsInOrder, "reportsInOrder");
        if (reportsInOrder.isEmpty()) {
            throw new IllegalArgumentException("请至少选择一条报告");
        }
        for (Report r : reportsInOrder) {
            if (r.getProject() == null) {
                throw new IllegalArgumentException("报告缺少所属项目: id=" + r.getId());
            }
        }

        try (XWPFDocument document = new XWPFDocument();
             ByteArrayOutputStream out = new ByteArrayOutputStream()) {

            setPageSizeA4(document, false);
            setDocumentMarginsCm(document, 2.6, 2.6, 2.5, 2.6);

            for (int i = 0; i < reportsInOrder.size(); i++) {
                Report report = reportsInOrder.get(i);
                Project p = report.getProject();
                if (i > 0) {
                    //document.createParagraph().createRun().addBreak(BreakType.PAGE);
                }
                beginBrandingPass(p, usesThirdPartyBranding(p, report));
                try {
                    dispatchReportGeneration(report, p, 1, document);
                } finally {
                    clearBrandingContext();
                }
            }

            document.write(out);
            return out.toByteArray();
        } catch (IllegalArgumentException e) {
            throw e;
        } catch (Exception e) {
            log.error("Error generating merged formal reports word", e);
            throw new RuntimeException("合并生成Word失败", e);
        }
    }

    private void validateReportForDetectionNotification(Project project, Report report) {
        if (!Objects.equals(report.getProjectId(), project.getId())) {
            throw new IllegalArgumentException("报告不属于当前项目");
        }
        if (report.getTestDate() == null) {
            throw new IllegalArgumentException("报告缺少检测日期");
        }
        ExperimentType et = resolveExperimentTypeForReport(report);
        ProjectComponent comp = resolveComponentForReport(report);
        String hd = defectDetectionService.hasDefect(report, et, comp);
        if (!"是".equals(hd)) {
            throw new IllegalArgumentException("所选报告存在未判定为缺陷的项");
        }
    }

    private ExperimentType resolveExperimentTypeForReport(Report report) {
        if (report.getExperimentTypeId() != null) {
            return experimentTypeRepository.findById(report.getExperimentTypeId()).orElse(null);
        }
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            return report.getReportItems().get(0).getExperimentType();
        }
        return null;
    }

    private List<ProjectComponent> resolveComponentsForReport(Report report) {
        return reportComponentMergeHelper.loadOrdered(projectComponentRepository,
                reportComponentMergeHelper.resolveComponentIds(report));
    }

    private ProjectComponent resolveComponentForReport(Report report) {
        List<ProjectComponent> list = resolveComponentsForReport(report);
        return list.isEmpty() ? null : list.get(0);
    }

    /**
     * 概述与导出文本预览：自动判定为 null 时（VIS/SOD/MET/VT 等）以 report.hasDefect 为准。
     */
    private boolean hasDefectForOverview(Report report, ExperimentType experimentType, List<ProjectComponent> comps) {
        String auto = defectDetectionService.hasDefectForComponents(report, experimentType, comps);
        if (auto != null) {
            return "是".equals(auto);
        }
        return "是".equals(report.getHasDefect());
    }

    /** 概述/通知单按 detectionContent 行（perContentRow 块）判定是否有缺陷数据。 */
    private boolean hasDefectForOverviewSegment(Report report, ExperimentType experimentType,
            List<ProjectComponent> comps, int contentRowIndex) {
        if (experimentType != null && experimentType.getCode() != null
                && "RT".equals(experimentType.getCode().trim().toUpperCase())) {
            return defectDetectionService.hasRadiographicDefectInBlock(report, contentRowIndex);
        }
        if (experimentType != null && isRowBasedNdtNotification(experimentType)) {
            return hasDefectInTableDataBlock(report, contentRowIndex);
        }
        ProjectComponent rowComp = componentForProjectDetailRow(report, comps, contentRowIndex);
        String auto = defectDetectionService.hasDefect(report, experimentType, rowComp);
        if (auto != null) {
            return "是".equals(auto);
        }
        return hasDefectForOverview(report, experimentType, comps);
    }

    private String mergedSpecPhiOrReportField(Report report, List<ProjectComponent> comps) {
        if (isUtMultiRowActive() && comps != null && !comps.isEmpty()) {
            ProjectComponent rowComponent = componentForProjectDetailRow(report, comps, currentUtDetectionContentRowIndex());
            String one = reportComponentMergeHelper.formatSpecUnified(rowComponent);
            if (one != null && !one.isEmpty()) {
                return one;
            }
        }
        String merged = reportComponentMergeHelper.mergeSpecsUnified(comps);
        if (merged != null && !merged.isEmpty()) {
            return merged;
        }
        return getFieldValue(report, "componentSpec", "/");
    }

