    // Same conclusion text as Word report cell; dispatch by first ReportItem experimentType code; null if unknown.
    private String getConclusionTextForReport(Report report) {
        int rowIdx = isUtMultiRowActive() ? currentUtDetectionContentRowIndex() : 0;
        String conclusionOverride = ExportTextOverrides.conclusionParagraph(report, rowIdx);
        if (!conclusionOverride.isEmpty()) {
            return conclusionOverride;
        }
        ExperimentType experimentType = null;
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            experimentType = report.getReportItems().get(0).getExperimentType();
        }
        if (experimentType == null || experimentType.getCode() == null) {
            return null;
        }
        String code = experimentType.getCode().trim();
        try {
            if ("MT".equals(code)) {
                return wordConclusionMt(report);
            }
            if ("UTM".equals(code) || "UTT".equals(code)) {
                return wordConclusionUtm(report);
            }
            if ("RDM".equals(code)) {
                return wordConclusionRdm(report);
            }
            if ("PDM".equals(code)) {
                return wordConclusionPdm(report);
            }
            if ("UT".equals(code)) {
                return wordConclusionUtDefault(report);
            }
            if ("PAUT".equals(code)) {
                return wordConclusionPautForCurrentRow(report, experimentType);
            }
            if ("PT".equalsIgnoreCase(code) || "LP".equalsIgnoreCase(code)) {
                return wordConclusionPt(report);
            }
            if ("RT".equals(code)) {
                return wordConclusionRt(report);
            }
            if ("MET".equals(code)) {
                return wordConclusionMet(report);
            }
            if ("VIS".equals(code)) {
                return wordConclusionVis(report);
            }
            if ("VT".equals(code)) {
                return wordConclusionVt(report);
            }
            if ("ET".equals(code)) {
                List<String> etResultParts = new ArrayList<>();
                try {
                    JsonNode etRoot = objectMapper.valueToTree(report.getDetectionContent());
                    JsonNode etRows = etRoot != null ? etRoot.get("rows") : null;
                    if (etRows != null && etRows.isArray()) {
                        for (JsonNode etRow : etRows) {
                            String r = getJsonNodeValue(etRow, "result", "");
                            if (r != null && !r.trim().isEmpty()) {
                                etResultParts.add(r.trim());
                            }
                        }
                    }
                } catch (Exception e) {
                    log.warn("ET conclusion parse detectionContent failed, report {}: {}", report.getId(), e.getMessage());
                }
                if (!etResultParts.isEmpty()) {
                    if (etResultParts.size() == 1) {
                        return "检测结果：\n  " + etResultParts.get(0);
                    }
                    StringBuilder sbEt = new StringBuilder("检测结果：\n");
                    for (int i = 0; i < etResultParts.size(); i++) {
                        sbEt.append("  ").append(i + 1).append("、").append(etResultParts.get(i));
                        if (i < etResultParts.size() - 1) {
                            sbEt.append("\n");
                        }
                    }
                    return sbEt.toString();
                }
                JsonNode etData = getDetectionDataFromReport(report);
                boolean etHasTableData = etData != null && etData.has("rows") && etData.get("rows").isArray()
                        && etData.get("rows").size() > 0;
                String hasDefectEt = report.getHasDefect();
                if ("是".equals(hasDefectEt)) {
                    return etHasTableData
                            ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                            : "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示。";
                }
                if ("否".equals(hasDefectEt)) {
                    return "检测结果：\n  在上述检测条件下，被检部位未见缺陷显示，评定为Ⅰ级。";
                }
                return "检测结果：\n  /";
            }
            if ("RTN".equals(code) || "HTN".equals(code) || "HTC".equals(code)) {
                return wordConclusionTensileGb5310(report);
            }
            if ("IMP".equals(code)) {
                return wordConclusionImpact(report);
            }
            if ("PMI".equals(code) || "AAT".equals(code)) {
                return wordConclusionAlloy(report);
            }
            if ("BHT".equals(code) || "BHD".equals(code)) {
                return wordConclusionBrinell(report);
            }
            if ("VHT".equals(code) || "VHN".equals(code)) {
                return wordConclusionVickers(report);
            }
            if ("RHT".equals(code) || "RHN".equals(code)) {
                return wordConclusionRockwell(report);
            }
            if ("LHT".equals(code) || "LHD".equals(code)) {
                DetectionContentDetail leebDetail = detectionContentNarrativeService.parseDetectionContentDetail(report, experimentType);
                String leebType = leebDetail.type != null ? leebDetail.type.trim() : "";
                if (leebType.contains("螺栓") ||leebType.contains("螺帽")) {
                    return wordConclusionBoltLeeb(report);
                }
                return wordConclusionLeeb(report);
            }
        } catch (Exception e) {
            log.warn("getConclusionTextForReport failed for report {}: {}", report.getId(), e.getMessage());
        }
        return null;
    }

    @Override
    public String getConclusionTextAutoGenerated(Report report) {
        Map<String, Object> origCf = report.getCustomFields();
        report.setCustomFields(ExportTextOverrides.copyCustomFieldsWithoutExportOverrides(origCf));
        try {
            String s = getConclusionTextForReport(report);
            return s != null ? s : "";
        } finally {
            report.setCustomFields(origCf);
        }
    }

    /** 概述「3 工作内容」行不再输出「详见附图」；去掉用户旧数据中残留的该短语。 */
    private static String stripOverviewWorkFigurePhrases(String line) {
        return DetectionContentNarrativeService.stripFigureReferencePhrases(line);
    }

    /**
     * 自定义概述「3 工作内容」：保留用户正文，编号始终为当前库内值。
     * 含标准「详见后附单项报告编号…。」则替换编号；仅有不完整片段则重写该片段；若用户删掉该句式则在正文后补上。
     */
    private static String applyCurrentReportNumberToOverviewWorkLine(
            String savedLine, String currentReportNumber) {
        String num = currentReportNumber != null ? currentReportNumber : "";
        String trimmed = savedLine == null ? "" : savedLine.trim();

        if (trimmed.isEmpty()) {
            return stripOverviewWorkFigurePhrases(OVERVIEW_WORK_REPORT_REF_MARKER + num + "。");
        }

        Matcher strict = OVERVIEW_WORK_LINE_REPORT_NUMBER_SEGMENT.matcher(trimmed);
        if (strict.find()) {
            String replaced = strict.replaceFirst(
                    Matcher.quoteReplacement(OVERVIEW_WORK_REPORT_REF_MARKER + num + "。"));
            return stripOverviewWorkFigurePhrases(replaced);
        }

        int idx = trimmed.indexOf(OVERVIEW_WORK_REPORT_REF_MARKER);
        if (idx >= 0) {
            int afterMarker = idx + OVERVIEW_WORK_REPORT_REF_MARKER.length();
            int periodAfter = trimmed.indexOf('。', afterMarker);
            String replaced = periodAfter >= 0
                    ? trimmed.substring(0, idx) + OVERVIEW_WORK_REPORT_REF_MARKER + num + "。"
                            + trimmed.substring(periodAfter + 1)
                    : trimmed.substring(0, idx) + OVERVIEW_WORK_REPORT_REF_MARKER + num + "。";
            return stripOverviewWorkFigurePhrases(replaced);
        }

        int figIdx = trimmed.indexOf(OVERVIEW_WORK_FIGURE_PHRASE);
        if (figIdx >= 0) {
            String head = trimmed.substring(0, figIdx).trim();
            StringBuilder sb = new StringBuilder();
            if (!head.isEmpty()) {
                sb.append(head);
                if (!head.endsWith("。") && !head.endsWith(".")) {
                    sb.append("。");
                }
            }
            sb.append(OVERVIEW_WORK_REPORT_REF_MARKER).append(num).append("。");
            return stripOverviewWorkFigurePhrases(sb.toString());
        }

        String base = trimmed;
        if (!base.endsWith("。") && !base.endsWith(".")) {
            base = base + "。";
        }
        base = base + OVERVIEW_WORK_REPORT_REF_MARKER + num + "。";
        return stripOverviewWorkFigurePhrases(base);
    }

    private List<JsonNode> mergedTableDataRowsFromFirstReportItem(Report report) {
        List<JsonNode> rows = new ArrayList<>();
        if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
            return rows;
        }
        ReportItem firstItem = report.getReportItems().get(0);
        if (firstItem.getTableData() == null || firstItem.getTableData().isEmpty()) {
            return rows;
        }
        try {
            JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
            if (mergedRows != null && mergedRows.isArray()) {
                for (JsonNode row : mergedRows) {
                    rows.add(row);
                }
            }
        } catch (Exception e) {
            log.warn("mergedTableDataRowsFromFirstReportItem failed for report {}: {}", report.getId(), e.getMessage());
        }
        return rows;
    }

