    /**
     * DL/T438-2023 里氏硬度结论标准表述前缀：钢管 → 管件 → 焊缝（仅输出材质库中非空的里氏-钢管/管件/焊缝）。
     * 三项均无则退回「里氏」单行；前缀末尾不加句号，由 {@link #buildLeebDl438NonComplianceTail} 衔接。
     */
    /**
     * @param appendDl869LeebRule 为 true 时在 DL/T438 分句后追加 DL/T869-2021 焊缝硬度规程句（与布氏推算焊缝判定一致）
     */
    private String buildLeebDl438StandardPrefix(String componentMaterial, Map<String, String> materialProperty,
                                                boolean appendDl869LeebRule) {
        String mat = componentMaterial != null && !componentMaterial.trim().isEmpty()
                ? componentMaterial.trim() : "/";
        if (materialProperty == null || materialProperty.isEmpty()) {
            return String.format("    DL/T438-2023规程要求，%s硬度应控制在/（后台暂无数据，请先自行填写结论，或联系管理员添加硬度范围）", mat);
        }
        String steel = materialProperty.get("里氏-钢管");
        String pipe = materialProperty.get("里氏-管件");
        String weld = materialProperty.get("里氏-焊缝");
        String defaultLeeb = materialProperty.get("里氏");

        List<String> clauses = new ArrayList<>();
        if (steel != null && !steel.trim().isEmpty()) {
            clauses.add(String.format("%s钢管硬度应控制在%sHBW", mat, steel.trim()));
        }
        if (pipe != null && !pipe.trim().isEmpty()) {
            clauses.add(String.format("%s管件硬度应控制在%sHBW", mat, pipe.trim()));
        }
        if (weld != null && !weld.trim().isEmpty()) {
            clauses.add(String.format("%s焊缝硬度应控制在%sHBW", mat, weld.trim()));
        }
        if (clauses.isEmpty()) {
            String leebText = defaultLeeb != null && !defaultLeeb.trim().isEmpty() ? defaultLeeb.trim() : "/";
            return String.format("    DL/T438-2023规程要求，%s硬度应控制在/（后台暂无数据，请先自行填写结论，或联系管理员添加硬度范围）", mat);
        }
        String prefix = "    DL/T438-2023规程要求，" + String.join("，", clauses);
        if (appendDl869LeebRule) {
            prefix = prefix + "，" + MaterialPropertyService.DL_T869_LEEB_WELD_CONCLUSION_APPEND;
        }
        return prefix;
    }

    /**
     * DL/T438 里氏硬度结论后缀：无不符则「所检测部件…符合」；有不符则分号连接低于下限/高于上限编号，再以「其余…符合」收尾。
     */
    private String buildLeebDl438NonComplianceTail(List<DataComparisonService.NonComplianceRecord> records) {
        if (records == null || records.isEmpty()) {
            return "，所检测部件硬度符合标准要求。";
        }
        LinkedHashSet<String> lowerNumbers = new LinkedHashSet<>();
        LinkedHashSet<String> upperNumbers = new LinkedHashSet<>();
        for (DataComparisonService.NonComplianceRecord record : records) {
            int direction = resolveNonComplianceDirection(record);
            String number = record.getNumber();
            if (number == null || number.trim().isEmpty() || "/".equals(number.trim())) {
                continue;
            }
            if (direction < 0) {
                lowerNumbers.add(number.trim());
            } else if (direction > 0) {
                upperNumbers.add(number.trim());
            }
        }
        if (lowerNumbers.isEmpty() && upperNumbers.isEmpty()) {
            return "，所检测部件硬度符合标准要求。";
        }
        StringBuilder sb = new StringBuilder();
        sb.append("；");
        if (!lowerNumbers.isEmpty()) {
            sb.append(sortAndJoinNumbers(new ArrayList<>(lowerNumbers))).append("低于标准下限");
        }
        if (!upperNumbers.isEmpty()) {
            if (!lowerNumbers.isEmpty()) {
                sb.append("；");
            }
            sb.append(sortAndJoinNumbers(new ArrayList<>(upperNumbers))).append("高于标准上限");
        }
        sb.append("，其余所检测部件硬度符合标准要求。");
        return sb.toString();
    }

    /**
     * 里氏硬度—钢管/管件焊缝模式（实验类型 {@code LHD}，非螺栓螺帽专用表）。
     * 结论句式：DL/T438-2023规程要求 + 钢管/管件/焊缝控制范围 + 符合或分号引出低于下限/高于上限编号。
     */
    private String wordConclusionLeeb(Report report) {
        String componentMaterial = resolveComponentMaterialForConclusion(report);
        Map<String, String> materialProperty = materialPropertyService.getMaterialProperty(componentMaterial);
        boolean appendDl869 = materialProperty != null
                && materialPropertyService.resolveBrinellDerivedLeebWeldRange(materialProperty).isPresent();
        String standardPrefix = buildLeebDl438StandardPrefix(componentMaterial, materialProperty, appendDl869);
        List<DataComparisonService.NonComplianceRecord> nonComplianceRecords = getNonComplianceRecords(report, materialProperty);
        String tail = buildLeebDl438NonComplianceTail(nonComplianceRecords);
        return "检测结论:\n" + standardPrefix + tail;
    }

    /**
     * 里氏硬度—螺栓/螺帽或管件焊缝模式（实验类型 {@code LHD}，由检测内容「类型」或表格「类型」判定）。
     * 与螺栓里氏硬度报告 {@code generateBoltLeebHardnessReport} 结论段一致。
     */
    private String wordConclusionBoltLeeb(Report report) {
        ProjectComponent compBolt = resolveComponentForReport(report);
        String componentMaterial = (compBolt != null && compBolt.getMaterial() != null && !compBolt.getMaterial().isEmpty())
                ? compBolt.getMaterial() : getCustomField(report, "部件材质", "/");
        Map<String, String> materialProperty = null;
        try {
            materialProperty = materialPropertyService.getMaterialProperty(componentMaterial);
        } catch (Exception e) {
            log.warn("Failed to get material property for bolt Leeb conclusion: {}", e.getMessage());
        }
        String pipeRangeLeebBolt = materialProperty != null ? materialProperty.get("里氏-管件") : null;
        String weldRangeLeebBolt = materialProperty != null ? materialProperty.get("里氏-焊缝") : null;
        String defaultLeebBolt = materialProperty != null ? materialProperty.get("里氏") : null;

        boolean isBoltOrNutReport = false;
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItemForType = report.getReportItems().get(0);
            if (firstItemForType.getTableData() != null && !firstItemForType.getTableData().isEmpty()) {
                try {
                    JsonNode rows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItemForType.getTableData(), objectMapper);
                    if (rows != null && rows.isArray()) {
                        for (JsonNode row : rows) {
                            String type = getJsonNodeValue(row, "类型", null);
                            if (type != null && (type.contains("螺栓") || type.contains("螺帽"))) {
                                isBoltOrNutReport = true;
                                break;
                            }
                        }
                    }
                } catch (Exception e) {
                    log.warn("解析螺栓里氏硬度表格数据时出错: {}", e.getMessage());
                }
            }
        }

        String standardText;
        if (true) {
            String boltRange = materialProperty != null ? materialProperty.get("里氏-螺栓") : null;
            if (boltRange == null || boltRange.isEmpty()) {
                boltRange = pipeRangeLeebBolt != null && !pipeRangeLeebBolt.isEmpty()
                        ? pipeRangeLeebBolt
                        : (materialProperty != null ? materialProperty.get("里氏-钢管") : null);
            }
            if (boltRange == null || boltRange.isEmpty()) {
                boltRange = defaultLeebBolt;
            }
            String nutRange = boltRange != null ? scaleRangeForDisplay(boltRange, 0.9) : null;

            if (boltRange != null && nutRange != null) {
                standardText = String.format(
                        "    依据DL/T439-2023规程,%s材质螺栓里氏硬度为%s，螺帽里氏硬度为螺栓硬度的0.9倍，即%s。",
                        componentMaterial, boltRange, nutRange);
            } else if (boltRange != null) {
                standardText = String.format(
                        "    依据DL/T439-2023规程,%s材质螺栓里氏硬度为%s。",
                        componentMaterial, boltRange);
            } else {
                String leebText = defaultLeebBolt != null ? defaultLeebBolt : "/";
                standardText = String.format(
                        "    依据DL/T439-2023规程,%s材质里氏硬度为%s。",
                        componentMaterial, leebText);
            }
        } else {
            if (pipeRangeLeebBolt != null && !pipeRangeLeebBolt.isEmpty()
                    && weldRangeLeebBolt != null && !weldRangeLeebBolt.isEmpty()) {
                standardText = String.format(
                        "    依据DL/T439-2023规程,%s材质里氏硬度为：管件%s，焊缝%s。",
                        componentMaterial, pipeRangeLeebBolt, weldRangeLeebBolt);
            } else {
                String leebText = defaultLeebBolt != null ? defaultLeebBolt : "/";
                standardText = String.format(
                        "    依据DL/T439-2023规程,%s材质里氏硬度为%s。",
                        componentMaterial, leebText);
            }
        }
        List<DataComparisonService.NonComplianceRecord> nonComplianceRecords = getNonComplianceRecords(report, materialProperty);
        String conclusionText = "检测结论:\n" + standardText + "\n    检测结果符合标准要求。";
        if (nonComplianceRecords != null && !nonComplianceRecords.isEmpty()) {
            String nonComplianceStr = buildNonComplianceSummaryByRange(nonComplianceRecords, false);
            conclusionText = "检测结论:\n" + standardText + "\n    " + nonComplianceStr;
        }
        return conclusionText;
    }

    /**
     * 合金成分分析（实验类型 {@code AAT}）Word「检测结论」段落；依据材质评定标准前缀与自定义/比对结论。
     */
    private String wordConclusionAlloy(Report report) {
        List<ProjectComponent> comps = resolveComponentsForReport(report);
        ProjectComponent component = reportComponentMergeHelper.firstOrNull(comps);
        String componentMaterial = (component != null && component.getMaterial() != null && !component.getMaterial().isEmpty())
                ? component.getMaterial()
                : getCustomField(report, "部件材质", "/");
        List<String> distinctMaterials = aatDataComparisonService.distinctMaterialsForReport(report, comps);
        if (!distinctMaterials.isEmpty()) {
            componentMaterial = distinctMaterials.get(0);
        }
        Map<String, String> materialProperty = null;
        String evaluationStandard = "/";
        if (componentMaterial != null && !componentMaterial.equals("/")) {
            try {
                materialProperty = materialPropertyService.getMaterialProperty(componentMaterial);
                if (materialProperty != null && materialProperty.containsKey("评定标准")) {
                    evaluationStandard = materialProperty.get("评定标准");
                }
            } catch (Exception e) {
                log.warn("Failed to get material standard for {}: {}", componentMaterial, e.getMessage());
            }
        }
        List<DataComparisonService.NonComplianceRecord> nonComplianceRecords =
                aatDataComparisonService.computeNonComplianceRecords(report);
        String conclusion = getCustomField(report, "检测结论", "/");
        if (conclusion.equals("/")) {
            if (nonComplianceRecords == null || nonComplianceRecords.isEmpty()) {
                conclusion = "检测结果符合标准要求。";
            } else {
                conclusion = buildNonComplianceSummaryByRange(nonComplianceRecords, true);
            }
        }
        switch (evaluationStandard) {
            case "DL/T 439-2018":
                conclusion = "依据" + evaluationStandard + "《火力发电厂高温紧固件技术导则》，" + conclusion;
                break;
            case "GB/T 5310-2023":
                conclusion = "依据" + evaluationStandard + "《高压锅炉用无缝钢管》，" + conclusion;
                break;
            case "DL/T 869-2021":
                conclusion = "依据" + evaluationStandard + "《火力发电厂焊接技术规程》，" + conclusion;
                break;
            default:
                break;
        }
        return "检测结论: \n" + "    " + conclusion;
    }

    /** Word/附页门控：优先按 tableData 自动判定，与 {@link DefectDetectionService#hasDefect} 一致。 */
    private boolean effectiveHasDefectForReport(Report report) {
        ExperimentType et = resolveExperimentTypeForReport(report);
        if (et != null) {
            String hd = defectDetectionService.hasDefect(report, et, null);
            if (hd != null) {
                return "是".equals(hd);
            }
        }
        return "是".equals(report.getHasDefect());
    }

    /**
     * 磁粉检测（实验类型 {@code MT}）Word「检测结果」用语；与磁粉单项报告缺陷/无缺陷分支一致。
     */
    private String wordConclusionMt(Report report) {
        return effectiveHasDefectForReport(report)
                ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷磁痕显示，详见缺陷信息。"
                : "检测结果：\n  在上述检测条件下，被检部位未见缺陷磁痕显示，评定为Ⅰ级。";
    }

    /**
     * 渗透检测（实验类型 {@code PT} 或 {@code LP}）Word「检测结果」用语；与渗透单项报告一致。
     */
    private String wordConclusionPt(Report report) {
        return effectiveHasDefectForReport(report)
                ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                : "检测结果：\n  在上述检测条件下，被检部位未见缺陷显示，评定为Ⅰ级。";
    }

    /**
     * 射线检测（实验类型 RT）Word「检测结果」用语；套话与渗透一致，判定与 {@link DefectDetectionService#hasDefect} 中 RT 规则一致。
     */
    private String wordConclusionRt(Report report) {
        return effectiveHasDefectForReport(report)
                ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                : "检测结果：\n  在上述检测条件下，被检部位未见缺陷显示，评定为Ⅰ级。";
    }

    /**
     * 超声检测（实验类型 {@code UT}）默认「检测结果」用语。
     * 与 {@code addUTDefectAndResultAndSign} 中无缺陷表分支及通用 UT 结论一致（子模板可另有专用文案）。
     */
    private String wordConclusionUtDefault(Report report) {
        return segmentHasDefectForNdt(report)
                ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                : "检测结果：\n  在上述检测条件下，被检部位未见缺陷显示，评定合格。";
    }

    /**
     * PAUT 对接焊缝模板「检测结果」默认句；与 {@code addPautButtWeldDefectAndResultAndSign} / {@code addUTButtWeldDefectAndResultAndSign} 一致。
     */
    private String wordConclusionPautButtWeld(Report report) {
        return segmentHasDefectForNdt(report)
                ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                : "检测结果：\n  上述检测条件下，未见可记录缺陷，评定为Ⅰ级。";
    }

    /**
     * PAUT 按当前检测内容行 type 选默认结论句（与 {@link #dispatchPautTemplateForCurrentContentRow} 映射一致）；不含导出覆盖（由调用方 {@link #getConclusionTextForReport} 先处理）。
     */
    private String wordConclusionPautForCurrentRow(Report report, ExperimentType experimentType) {
        int rowIdx = isUtMultiRowActive() ? currentUtDetectionContentRowIndex() : 0;
        DetectionContentDetail d = detectionContentNarrativeService.parseDetectionContentDetailAtRow(
                report, experimentType, rowIdx);
        String type = d.type != null ? d.type.trim() : "";
        switch (type) {
            case "叶片":
            case "叶根（叉形、菌形）":
            case "叶根（T形、枞树形）":
            case "叶根":
            case "叶根-叉形":
            case "叶根-菌形":
            case "叶根-T形":
            case "叶根-枞树形":
            case "角焊缝（联箱）":
            case "角焊缝（插管）":
                return wordConclusionUtDefault(report);
            case "对接焊缝（受热面管）":
            case "对接焊缝（插管）":
                return wordConclusionPautButtWeld(report);
            default:
                return wordConclusionPautButtWeld(report);
        }
    }

    /**
     * 超声波测厚（实验类型 {@code UTM} 或 {@code UTT}）「检测结果」段落。
     * 行内实测厚度低于「最小需要厚度」为不合格，见 {@link UltrasonicThicknessMinRequiredRules}。
     */
    private String wordConclusionUtm(Report report) {
        int contentRowIndex = currentUtDetectionContentRowIndex();
        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    List<JsonNode> blocks = TableDataMergeUtil.perContentRowBlocks(
                            firstItem.getTableData(), objectMapper);
                    JsonNode blockRows = null;
                    if (!blocks.isEmpty()) {
                        int bi = Math.min(Math.max(0, contentRowIndex), blocks.size() - 1);
                        JsonNode block = blocks.get(bi);
                        if (block != null && block.has("rows") && block.get("rows").isArray()) {
                            blockRows = block.get("rows");
                        }
                    }
                    if (blockRows == null) {
                        blockRows = TableDataMergeUtil.mergedRowsFromTableDataJson(
                                firstItem.getTableData(), objectMapper);
                    }
                    if (blockRows != null && blockRows.isArray()) {
                        for (JsonNode row : blockRows) {
                            measurementRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("wordConclusionUtm: tableData {}", e.getMessage());
                }
            }
        }
        String resultText = "检测结果:\n";
        String conclusion = null;
        Double minRequired = UltrasonicThicknessMinRequiredRules.parseMinRequiredFromDetectionContent(
                report.getDetectionContent(), objectMapper, contentRowIndex);
        conclusion = UltrasonicThicknessMinRequiredRules.resolveConclusionSentence(measurementRows, minRequired);
        if (conclusion == null) {
            conclusion = getDetectionConclusion(report);
            if (conclusion.equals("/")) {
                conclusion = getCustomField(report, "检测结论", "/");
            }
        }
        if (!conclusion.equals("/")) {
            resultText += "    " + conclusion;
        }
        return resultText;
    }

    private String utmPointAndThicknessFromRow(JsonNode rowData) {
        if (rowData == null) {
            return "/|/";
        }
        String point = UltrasonicThicknessMinRequiredRules.parsePointNumber(rowData);
        if (point.isEmpty()) {
            point = "/";
        }
        String measuredStr = "/";
        String[] thicknessKeys = {"实测厚度 (mm)", "实测厚度（mm）", "实测厚度", "厚度"};
        for (String key : thicknessKeys) {
            if (!rowData.has(key)) {
                continue;
            }
            JsonNode n = rowData.get(key);
            if (n == null || n.isNull()) {
                continue;
            }
            String s = n.asText().trim();
            if (!s.isEmpty() && !"/".equals(s)) {
                measuredStr = s;
                break;
            }
        }
        return point + "|" + measuredStr;
    }

    private static final int UTM_GROUPS_PER_ROW = 4;
    private static final int UTM_COLS_PER_GROUP = 2;

    private void writeUtmMeasurementHeaderRow(XWPFTableRow headerRow, int[] colWidths) {
        setRowHeight(headerRow, 510);
        for (int g = 0; g < UTM_GROUPS_PER_ROW; g++) {
            int base = g * UTM_COLS_PER_GROUP;
            createTableCell(headerRow.getCell(base), "测点编号", colWidths[base],
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(headerRow.getCell(base + 1), "实测厚度 (mm)", colWidths[base + 1],
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }
    }

    private void writeUtmMeasurementDataRow(XWPFTableRow dataRow, int rowIndexInPage, int pageStartIndex,
                                            int rowsPerPage, List<JsonNode> measurementRows, int totalMeasurements,
                                            int[] colWidths) {
        for (int group = 0; group < UTM_GROUPS_PER_ROW; group++) {
            int measurementIndex = pageStartIndex + group * rowsPerPage + rowIndexInPage;
            JsonNode rowData = measurementIndex < totalMeasurements ? measurementRows.get(measurementIndex) : null;
            String[] cells = utmPointAndThicknessFromRow(rowData).split("\\|", -1);
            int base = group * UTM_COLS_PER_GROUP;
            createTableCell(dataRow.getCell(base), cells[0], colWidths[base],
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(base + 1), cells[1], colWidths[base + 1],
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }
    }

    /**
     * 管径测量（实验类型 {@code PDM}）外径蠕变应变判定；规则与 {@link com.reportweb.service.DefectDetectionService} 中 PDM 一致。
     */
    private String wordConclusionPdm(Report report) {
        ProjectComponent component = resolveComponentForReport(report);
        ExperimentType expType = null;
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            expType = report.getReportItems().get(0).getExperimentType();
        }
        DetectionContentDetail detail = detectionContentNarrativeService.parseDetectionContentDetail(report, expType);
        String pipeType = detail.type != null ? detail.type.trim() : "";
        Double thresholdRatio = PdmPipeCreepRules.ratioForPipeType(pipeType);

        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            measurementRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("wordConclusionPdm: tableData {}", e.getMessage());
                }
            }
        }
        String resultText = "检测结果:\n";
        String conclusion = null;
        if (thresholdRatio != null && component != null && component.getPipeDiameter() != null && !component.getPipeDiameter().isEmpty()) {
            Double componentDiameter = parsePipeDiameter(component.getPipeDiameter());
            if (componentDiameter != null && componentDiameter > 0) {
                List<String> failedPointNumbers = new ArrayList<>();
                boolean hasValidMeasurement = false;
                for (JsonNode rowData : measurementRows) {
                    String pointNumber = null;
                    Double measuredDiameter = null;
                    if (rowData.has("测点编号")) {
                        pointNumber = rowData.get("测点编号").asText();
                    } else if (rowData.has("编号")) {
                        pointNumber = rowData.get("编号").asText();
                    }
                    if (rowData.has("实测管径（mm）")) {
                        JsonNode d = rowData.get("实测管径（mm）");
                        if (d.isNumber()) {
                            measuredDiameter = d.asDouble();
                        } else {
                            try {
                                measuredDiameter = Double.parseDouble(d.asText().trim());
                            } catch (NumberFormatException ignored) {
                            }
                        }
                    } else if (rowData.has("实测管径")) {
                        JsonNode d = rowData.get("实测管径");
                        if (d.isNumber()) {
                            measuredDiameter = d.asDouble();
                        } else {
                            try {
                                measuredDiameter = Double.parseDouble(d.asText().trim());
                            } catch (NumberFormatException ignored) {
                            }
                        }
                    }
                    if (pointNumber != null && !pointNumber.trim().isEmpty() && !pointNumber.equals("/")
                            && measuredDiameter != null && measuredDiameter > 0) {
                        hasValidMeasurement = true;
                        double strain = (measuredDiameter - componentDiameter) / componentDiameter;
                        if (strain > thresholdRatio) {
                            failedPointNumbers.add(pointNumber);
                        }
                    }
                }
                if (hasValidMeasurement) {
                    if (failedPointNumbers.isEmpty()) {
                        conclusion = PdmPipeCreepRules.normalConclusionSentence(pipeType);
                    } else {
                        String pct = PdmPipeCreepRules.formatPercentLabel(thresholdRatio);
                        String failedPointsStr = String.join("、", failedPointNumbers);
                        conclusion = "在上述检测条件下，" + failedPointsStr + " 测点外径蠕变应变超过允许值（" + pipeType + "允许不大于"
                                + pct + "%），应处理。";
                    }
                }
            }
        }
        if (conclusion == null) {
            conclusion = getDetectionConclusion(report);
            if (conclusion.equals("/")) {
                conclusion = getCustomField(report, "检测结论", "/");
            }
        }
        if (!conclusion.equals("/")) {
            resultText += "    " + conclusion;
        }
        return resultText;
    }

    /**
     * 圆度测量（实验类型 {@code RDM}）「检测结果」段落；弯头圆度符合/不符合列表。
     * 与 {@code generateRoundnessMeasurementReport} 结论段一致。
     */
    private String wordConclusionRdm(Report report) {
        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            measurementRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("wordConclusionRdm: {}", e.getMessage());
                }
            }
        }
        int totalMeasurements = measurementRows.size();
        int mainPageRows = 8;
        List<String> nonCompliantElbows = new ArrayList<>();
        for (int i = 0; i < mainPageRows; i++) {
            JsonNode rowData = i < totalMeasurements ? measurementRows.get(i) : null;
            String elbowNumber = "/";
            Double measuredValue = null;
            Double allowedValue = null;
            if (rowData != null) {
                if (rowData.has("弯头编号")) {
                    elbowNumber = rowData.get("弯头编号").asText();
                }
                if (rowData.has("测量圆度值")) {
                    JsonNode r = rowData.get("测量圆度值");
                    if (r.isNumber()) {
                        measuredValue = r.asDouble();
                    }
                }
                if (rowData.has("允许圆度值")) {
                    JsonNode r = rowData.get("允许圆度值");
                    if (r.isNumber()) {
                        allowedValue = r.asDouble();
                    }
                }
                if (measuredValue != null && allowedValue != null && measuredValue > allowedValue) {
                    if (!elbowNumber.equals("/") && !elbowNumber.isEmpty()) {
                        nonCompliantElbows.add(elbowNumber);
                    }
                }
            }
        }
        for (int i = 0; i < totalMeasurements; i++) {
            JsonNode rowData = measurementRows.get(i);
            String elbowNumber = "/";
            Double measuredValue = null;
            Double allowedValue = null;
            if (rowData.has("弯头编号")) {
                elbowNumber = rowData.get("弯头编号").asText();
            }
            if (rowData.has("测量圆度值")) {
                JsonNode r = rowData.get("测量圆度值");
                if (r.isNumber()) {
                    measuredValue = r.asDouble();
                }
            }
            if (rowData.has("允许圆度值")) {
                JsonNode r = rowData.get("允许圆度值");
                if (r.isNumber()) {
                    allowedValue = r.asDouble();
                }
            }
            if (measuredValue != null && allowedValue != null && measuredValue > allowedValue) {
                if (!elbowNumber.equals("/") && !elbowNumber.isEmpty() && !nonCompliantElbows.contains(elbowNumber)) {
                    nonCompliantElbows.add(elbowNumber);
                }
            }
        }
        String resultText = "检测结果:\n";
        if (!nonCompliantElbows.isEmpty()) {
            StringBuilder conclusionBuilder = new StringBuilder("所测");
            for (int i = 0; i < nonCompliantElbows.size(); i++) {
                if (i > 0) {
                    conclusionBuilder.append("、");
                }
                conclusionBuilder.append(nonCompliantElbows.get(i));
            }
            conclusionBuilder.append("弯头圆度不符合标准要求");
            resultText += "    " + conclusionBuilder.toString();
        } else {
            resultText += "    所测弯头圆度均符合标准要求";
        }
        return resultText;
    }

    // Notification for UT/MT/PT/LP/RT: join detection rows; do not use getConclusionTextForReport boilerplate.
    private static boolean isRowBasedNdtNotification(ExperimentType experimentType) {
        if (experimentType == null || experimentType.getCode() == null) {
            return false;
        }
        String code = experimentType.getCode().trim().toUpperCase();
        return "UT".equals(code) || "PAUT".equals(code) || "MT".equals(code) || "PT".equals(code) || "LP".equals(code)
                || "RT".equals(code);
    }

    private static boolean supportsRecordOnlyFlagForCode(String code) {
        if (code == null) {
            return false;
        }
        String normalized = code.trim().toUpperCase(Locale.ROOT);
        return "MT".equals(normalized)
                || "PT".equals(normalized)
                || "LP".equals(normalized)
                || "UT".equals(normalized)
                || "RT".equals(normalized);
    }

    private boolean supportsRecordOnlyFlagForReport(Report report) {
        ExperimentType expType = resolveExperimentTypeForReport(report);
        return expType != null && supportsRecordOnlyFlagForCode(expType.getCode());
    }

    /** 与检测内容行 / perContentRow 块对齐；与 {@link DefectDetectionService} 中 ndtRowsForBlock 同义。 */
    private JsonNode getDetectionRowsForNotification(Report report, int contentRowIndex) {
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            String tableData = report.getReportItems().get(0).getTableData();
            if (tableData != null && !tableData.isEmpty()) {
                List<JsonNode> blocks = TableDataMergeUtil.perContentRowBlocks(tableData, objectMapper);
                if (!blocks.isEmpty()) {
                    if (contentRowIndex >= 0 && contentRowIndex < blocks.size()) {
                        JsonNode block = blocks.get(contentRowIndex);
                        if (block != null && block.has("rows") && block.get("rows").isArray()) {
                            return block.get("rows");
                        }
                    }
                    return objectMapper.createArrayNode();
                }
            }
        }
        return getDetectionRowsForNotificationMerged(report);
    }

    private JsonNode getDetectionRowsForNotification(Report report) {
        return getDetectionRowsForNotification(report, 0);
    }

    /** 无 perContentRow 多块时：tableData 合并 rows，否则 detectionContent.rows。 */
    private JsonNode getDetectionRowsForNotificationMerged(Report report) {
        JsonNode data = getDetectionDataFromReport(report);
        if (data != null && data.has("rows") && data.get("rows").isArray() && data.get("rows").size() > 0) {
            return data.get("rows");
        }
        if (report.getDetectionContent() != null) {
            try {
                String json = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode node = objectMapper.readTree(json);
                if (node.has("rows") && node.get("rows").isArray() && node.get("rows").size() > 0) {
                    return node.get("rows");
                }
            } catch (Exception e) {
                log.warn("Failed to parse detectionContent rows for notification (report {}): {}", report.getId(), e.getMessage());
            }
        }
        return null;
    }

    /** 当前 UT/PAUT 分段（或单行）是否存在有效缺陷数据。 */
    private boolean segmentHasDefectForNdt(Report report) {
        return hasDefectInTableDataBlock(report, currentUtDetectionContentRowIndex());
    }

    /** 当前 contentRow 对应 tableData 块是否存在有效缺陷行（NDT/PAUT）。 */
    private boolean hasDefectInTableDataBlock(Report report, int contentRowIndex) {
        ExperimentType expType = resolveExperimentTypeForReport(report);
        String expCode = expType != null ? expType.getCode() : null;
        boolean supportsRecordOnlyFlag = supportsRecordOnlyFlagForCode(expCode);
        if (expType != null && expType.getCode() != null
                && "RT".equals(expType.getCode().trim().toUpperCase())) {
            return defectDetectionService.hasRadiographicDefectInBlock(report, contentRowIndex);
        }
        JsonNode rows = getDetectionRowsForNotification(report, contentRowIndex);
        if (rows == null || !rows.isArray()) {
            return false;
        }
        for (JsonNode row : rows) {
            if (row == null || !row.isObject() || TableDataMergeUtil.isTrailingSlashPlaceholderRow(row)) {
                continue;
            }
            if (NdtDefectRowUtil.isEffectiveDefectRow(row, supportsRecordOnlyFlag)) {
                return true;
            }
        }
        return false;
    }

    private String normalizeNotificationConclusionForCell(String conclusion) {
        if (conclusion == null) {
            return " ";
        }
        String c = conclusion.replaceAll("\n", "  ").replace("检测结论:", "").replaceAll(" ", "");
        return c.isEmpty() ? " " : c;
    }

    /** 概述第 2 章用：与通知单同源；结论类文本去标签，块内多缺陷行用全角分号连接。 */
    private String defectDetailTextForOverviewSegment(Report report, ExperimentType expType, int contentRowIndex) {
        String raw = buildDetectionNotificationConclusion(report, expType, contentRowIndex);
        return sanitizeOverviewDefectDetailText(raw);
    }

    /**
     * 概述缺陷「详细描述」：去掉检测结果/检测结论标签，归一空白，去掉尾部句号以免与「，详情请见」叠成「。，」。
     */
    private static String sanitizeOverviewDefectDetailText(String raw) {
        if (raw == null || raw.isBlank()) {
            return "";
        }
        String[] lines = raw.split("\\r?\\n");
        List<String> parts = new ArrayList<>();
        for (String line : lines) {
            String one = sanitizeOverviewDefectDetailLine(line);
            if (!one.isEmpty() && !"/".equals(one)) {
                parts.add(one);
            }
        }
        if (parts.isEmpty()) {
            return "";
        }
        String joined = parts.size() == 1 ? parts.get(0) : String.join("；", parts);
        return trimTrailingOverviewDefectPunctuation(joined);
    }

    private static String sanitizeOverviewDefectDetailLine(String line) {
        if (line == null) {
            return "";
        }
        String s = line.trim();
        while (true) {
            String stripped = OVERVIEW_DEFECT_LEADING_RESULT_LABEL.matcher(s).replaceFirst("");
            if (stripped.equals(s)) {
                break;
            }
            s = stripped.trim();
        }
        s = s.replaceAll("\\s+", " ").trim();
        return trimTrailingOverviewDefectPunctuation(s);
    }

    private static String trimTrailingOverviewDefectPunctuation(String text) {
        if (text == null) {
            return "";
        }
        String t = text.trim();
        while (!t.isEmpty()) {
            char last = t.charAt(t.length() - 1);
            if (last == '。' || last == '．' || last == '；' || last == ';') {
                t = t.substring(0, t.length() - 1).trim();
            } else {
                break;
            }
        }
        return t;
    }

    // Spare fallback (unused); keep in sync with buildDetectionNotificationConclusion if reused.
    private String fallbackNotificationConclusion(Report report) {
        String word = getConclusionTextForReport(report);
        if (word != null && !word.isBlank()) {
            return word;
        }
        return fallbackNotificationConclusionLegacy(report);
    }

    // Legacy notification conclusion: first item summary, then getDetectionConclusion.
    private String fallbackNotificationConclusionLegacy(Report report) {
        String s = getFirstReportItemSummary(report);
        if (s != null && !s.isEmpty()) {
            return s;
        }
        String c = getDetectionConclusion(report);
        if (c != null && !c.isEmpty() && !"/".equals(c.trim())) {
            return c.trim();
        }
        return "";
    }

    private void appendNotificationLabeledPart(List<String> parts, String label, String raw) {
        if (raw == null) {
            return;
        }
        String t = raw.trim();
        if (t.isEmpty() || "/".equals(t)) {
            return;
        }
        String phrase = TableSchemaUtil.formatLabeledPhrase(label, t);
        if (!phrase.isEmpty()) {
            parts.add(phrase);
        }
    }

    /**
     * 检测内容表格行（type/total/locationDesc/locationNumber）与 parseDetectionContentDetail 报告级字段拼接，用于缺陷列拼不出时的回退。
     */
    private String formatGenericDetectionNotificationRow(JsonNode row, Report report, ExperimentType expType,
            int contentRowIndex) {
        if (row == null || !row.isObject()) {
            return "";
        }
        String type = row.has("type") && !row.get("type").isNull() ? row.get("type").asText("") : "";
        String total = row.has("total") && !row.get("total").isNull() ? row.get("total").asText("") : "";
        String locationDesc = row.has("locationDesc") && !row.get("locationDesc").isNull()
                ? row.get("locationDesc").asText("") : "";
        String locationNumber = row.has("locationNumber") && !row.get("locationNumber").isNull()
                ? row.get("locationNumber").asText("") : "";
        DetectionContentDetail d = detectionContentNarrativeService.parseDetectionContentDetailAtRow(
                report, expType, contentRowIndex);
        String t = detectionContentNarrativeService.buildDetectionDetailText(
                d.methodName, d.componentName, type, total, locationDesc, locationNumber, true, true, expType, null, null);
        return t != null ? t.trim() : "";
    }

    /** 超声检测数据行：与单项报告缺陷表列一致；若无缺陷列则回退检测内容字段。 */
    private String formatUtNotificationRow(JsonNode row, Report report, ExperimentType expType, int contentRowIndex) {
        if (row == null || !row.isObject()) {
            return "";
        }
        List<String> parts = new ArrayList<>();
        String pos = getJsonValue(row, "位置", getJsonValue(row, "起点位置", ""));
        appendNotificationLabeledPart(parts, "位置", pos);
        String amp = getJsonValue(row, "波幅(dB)", getJsonValue(row, "波幅", ""));
        appendNotificationLabeledPart(parts, "波幅(dB)", amp);
        String depth = getJsonValue(row, "深度(mm)", getJsonValue(row, "深度", ""));
        appendNotificationLabeledPart(parts, "深度(mm)", depth);
        String len = getJsonValue(row, "长度(mm)", getJsonValue(row, "长度", ""));
        appendNotificationLabeledPart(parts, "长度(mm)", len);
        String height = getJsonValue(row, "高度(mm)", getJsonValue(row, "高度", ""));
        appendNotificationLabeledPart(parts, "高度(mm)", height);
        String lvl = getJsonValue(row, "级别", "");
        appendNotificationLabeledPart(parts, "级别", lvl);
        String remark = getJsonValue(row, "备注", "");
        appendNotificationLabeledPart(parts, "备注", remark);
        appendNotificationLabeledPart(parts, "编号", getDefectNumberValue(row));
        String line = String.join("，", parts);
       
        if (!line.isEmpty()) {
            return line;
        }
        return formatGenericDetectionNotificationRow(row, report, expType, contentRowIndex);
    }

