    // UT/MT/PT/LP/RT/PAUT: join rows; others: getConclusionTextForReport then legacy fallback.
    private String buildDetectionNotificationConclusion(Report report, ExperimentType expType) {
        return buildDetectionNotificationConclusion(report, expType, 0);
    }

    private String buildDetectionNotificationConclusion(Report report, ExperimentType expType, int contentRowIndex) {
        if (isRowBasedNdtNotification(expType)) {
            String code = expType.getCode().trim().toUpperCase();
            JsonNode rows = getDetectionRowsForNotification(report, contentRowIndex);
            if (rows == null || rows.size() == 0) {
                return fallbackNotificationConclusionLegacy(report);
            }
            List<SchemaColumn> schemaColumns = TableSchemaUtil.parseColumns(
                    expType != null ? expType.getTableSchema() : null, objectMapper);
            List<JsonNode> rowList = new ArrayList<>();
            for (int i = 0; i < rows.size(); i++) {
                JsonNode row = rows.get(i);
                if (row == null || !row.isObject()) {
                    continue;
                }
                if (TableDataMergeUtil.isTrailingSlashPlaceholderRow(row)) {
                    continue;
                }
                if ("RT".equals(code) && !RtDefectRowUtil.hasEffectiveDefectColumn(row, true)) {
                    continue;
                }
                if (!"RT".equals(code) && !NdtDefectRowUtil.isEffectiveDefectRow(row, supportsRecordOnlyFlagForCode(code))) {
                    continue;
                }
                rowList.add(row);
            }
            rowList.sort(Comparator.comparing(TableSchemaUtil::rowSortKey, this::compareNumberText));
            List<String> lines = new ArrayList<>();
            for (JsonNode row : rowList) {
                String line = "";
                if (!schemaColumns.isEmpty()) {
                    line = TableSchemaUtil.formatNotificationLine(row, schemaColumns);
                }
                if (line.isEmpty()) {
                    if ("UT".equals(code) || "PAUT".equals(code)) {
                        line = formatUtNotificationRow(row, report, expType, contentRowIndex);
                    } else if ("MT".equals(code) || "PT".equals(code) || "LP".equals(code)) {
                        line = formatMtPtNotificationRow(row, report, expType, contentRowIndex);
                    } else if ("RT".equals(code)) {
                        line = formatRtNotificationRow(row, report, expType, contentRowIndex);
                    }
                }
                if (line != null && !line.isEmpty()) {
                    lines.add(line);
                }
            }
            if (lines.isEmpty()) {
                return fallbackNotificationConclusionLegacy(report);
            }
            return String.join("\n", lines);
        }
        String word = getConclusionTextForReport(report);
        if (word != null && !word.isBlank()) {
            return word;
        }
        return fallbackNotificationConclusionLegacy(report);
    }

    /**
     * 检测通知单签行：左侧「检测人员/项目负责人」整体左缩进约 2 字；「检测时间」靠右对齐制表位，距单元格右缘约 2 字宽。
     */
    private void fillDetectionNotificationSignatureLinesCell(
            XWPFTableCell cell,
            int cellWidthTwips,
            String inspector,
            String leader,
            String testDateStr) {
        while (!cell.getParagraphs().isEmpty()) {
            cell.removeParagraph(0);
        }
        long rightTabPos = Math.max(3000L, (long) cellWidthTwips - NOTIFICATION_SIGNATURE_TWO_CHAR_TWIPS);
        appendDetectionNotificationSignatureLine(cell, rightTabPos, "检测人员：", inspector, testDateStr, 120);
        appendDetectionNotificationSignatureLine(cell, rightTabPos, "项目负责人：", leader, testDateStr, 0);
    }

    private void appendDetectionNotificationSignatureLine(
            XWPFTableCell cell,
            long rightTabStopTwips,
            String roleLabel,
            String roleValue,
            String testDateStr,
            int spacingBeforeTwips) {
        XWPFParagraph p = cell.addParagraph();
        p.setAlignment(ParagraphAlignment.LEFT);
        if (spacingBeforeTwips > 0) {
            p.setSpacingBefore(spacingBeforeTwips);
        }
        p.setIndentationLeft(NOTIFICATION_SIGNATURE_TWO_CHAR_TWIPS);

        CTP ctp = p.getCTP();
        CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
        CTTabs tabs = pPr.isSetTabs() ? pPr.getTabs() : pPr.addNewTabs();
        CTTabStop tabStop = tabs.addNewTab();
        tabStop.setVal(STTabJc.RIGHT);
        tabStop.setPos(BigInteger.valueOf(rightTabStopTwips));

        XWPFRun leftRun = p.createRun();
        leftRun.setFontFamily("宋体");
        leftRun.setFontSize(10.5);
        leftRun.setText(roleLabel + (roleValue != null ? roleValue : ""));
        leftRun.addTab();

        XWPFRun rightRun = p.createRun();
        rightRun.setFontFamily("宋体");
        rightRun.setFontSize(10.5);
        rightRun.setText("检测时间：" + (testDateStr != null ? testDateStr : ""));
    }

