    /**
     * 先输出全部润电样式单项（概述顺序中的润电子集，编号在子集内 001 递增），再分页输出全部第三方样式单项（第三方子集内 001 递增）。
     */
    private void appendRunDianThenThirdPartySingleReports(
            XWPFDocument document,
            Project project,
            List<Report> runDianReports,
            List<Report> thirdPartyReports) throws Exception {

        if (!runDianReports.isEmpty()) {
            beginBrandingPass(project, false);
            int subsetIndex = 1;
            for (Report report : runDianReports) {
                CURRENT_REPORT_INDEX_1_BASED.set(subsetIndex);
                try {
                    dispatchReportGeneration(report, project, subsetIndex, document);
                } finally {
                    CURRENT_REPORT_INDEX_1_BASED.remove();
                }
                subsetIndex += reportWordSegmentCount(report, resolveExperimentTypeForReport(report));
            }
        }

        if (!runDianReports.isEmpty() && !thirdPartyReports.isEmpty()) {
            document.createParagraph().createRun().addBreak(BreakType.PAGE);
        }

        if (!thirdPartyReports.isEmpty()) {
            beginBrandingPass(project, true);
            int subsetIndex = 1;
            for (Report report : thirdPartyReports) {
                CURRENT_REPORT_INDEX_1_BASED.set(subsetIndex);
                try {
                    dispatchReportGeneration(report, project, subsetIndex, document);
                } finally {
                    CURRENT_REPORT_INDEX_1_BASED.remove();
                }
                subsetIndex += reportWordSegmentCount(report, resolveExperimentTypeForReport(report));
            }
        }
    }

    private void appendRunDianSingleReportsOnly(
            XWPFDocument document,
            Project project,
            List<Report> runDianReports) throws Exception {
        if (runDianReports.isEmpty()) {
            return;
        }
        beginBrandingPass(project, false);
        int subsetIndex = 1;
        for (Report report : runDianReports) {
            CURRENT_REPORT_INDEX_1_BASED.set(subsetIndex);
            try {
                dispatchReportGeneration(report, project, subsetIndex, document);
            } finally {
                CURRENT_REPORT_INDEX_1_BASED.remove();
            }
            subsetIndex += reportWordSegmentCount(report, resolveExperimentTypeForReport(report));
        }
    }

    /**
     * 根据检测类型生成对应单项（与项目总报告原逻辑一致）。
     */
    private void dispatchReportGeneration(Report report, Project project, int reportIndex, XWPFDocument document)
            throws Exception {
        int tableCountBeforeGeneration = document.getTables().size();
        ExperimentType experimentType = null;
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            experimentType = report.getReportItems().get(0).getExperimentType();
        }

        log.debug("Processing report {}: experimentType={}, code={}",
                report.getId(),
                experimentType != null ? experimentType.getName() : "null",
                experimentType != null && experimentType.getCode() != null ? experimentType.getCode() : "null");

        if (experimentType != null && experimentType.getCode() != null && "MT".equals(experimentType.getCode())) {
            try {
                generateMPIReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating MPI report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("UTM".equals(experimentType.getCode()) || "UTT".equals(experimentType.getCode()))) {
            try {
                generateUltrasonicThicknessReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Ultrasonic Thickness report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "RDM".equals(experimentType.getCode())) {
            try {
                generateRoundnessMeasurementReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Roundness Measurement report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "PDM".equals(experimentType.getCode())) {
            try {
                generatePipeDiameterMeasurementReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Pipe Diameter Measurement report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "UT".equals(experimentType.getCode())) {
            try {
                generateUTReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating UT report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "PAUT".equals(experimentType.getCode())) {
            try {
                generatePAUTReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating PAUT report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("PT".equalsIgnoreCase(experimentType.getCode()) || "LP".equalsIgnoreCase(experimentType.getCode()))) {
            try {
                generatePenetrationReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating PT report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "RT".equals(experimentType.getCode())) {
            try {
                generateRadiographicReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Radiographic report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "MET".equals(experimentType.getCode())) {
            try {
                generateMetallographicReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Metallographic report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "VIS".equals(experimentType.getCode())) {
            try {
                generateVisualInspectionReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Visual Inspection report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "VT".equals(experimentType.getCode())) {
            try {
                generateBorescopeReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Borescope report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "ET".equals(experimentType.getCode())) {
            try {
                generateEddyCurrentReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Eddy Current report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "RTN".equals(experimentType.getCode())) {
            try {
                generateRoomTemperatureTensileReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Room Temperature Tensile report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "HTN".equals(experimentType.getCode())) {
            try {
                generateHighTemperatureTensileReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating High Temperature Tensile report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "HTC".equals(experimentType.getCode())) {
            try {
                generateHighTemperatureCreepReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating High Temperature Creep report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "IMP".equals(experimentType.getCode())) {
            try {
                generateImpactAbsorptionEnergyReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Impact Absorption Energy report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("PMI".equals(experimentType.getCode()) || "AAT".equals(experimentType.getCode()))) {
            try {
                generateAlloyAnalysisReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Alloy Analysis report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("BHT".equals(experimentType.getCode()) || "BHD".equals(experimentType.getCode()))) {
            try {
                generateBrinellHardnessReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Brinell Hardness report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("VHT".equals(experimentType.getCode()) || "VHN".equals(experimentType.getCode()))) {
            try {
                generateVickersHardnessReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Vickers Hardness report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("RHT".equals(experimentType.getCode()) || "RHN".equals(experimentType.getCode()))) {
            try {
                generateRockwellHardnessReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating Rockwell Hardness report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null
                && ("LHT".equals(experimentType.getCode()) || "LHD".equals(experimentType.getCode()))) {
            try {
                DetectionContentDetail leebDetail = detectionContentNarrativeService.parseDetectionContentDetail(report, experimentType);
                String leebType = leebDetail.type != null ? leebDetail.type.trim() : "";
                if (leebType.contains("螺栓") || leebType.contains("螺帽")) {
                    generateBoltLeebHardnessReport(report, project, reportIndex, document);
                } else {
                    generateLeebHardnessReport(report, project, reportIndex, document);
                }
            } catch (Exception e) {
                log.error("Error generating Leeb Hardness report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else if (experimentType != null && experimentType.getCode() != null && "SOD".equals(experimentType.getCode())) {
            try {
                generateOxideScaleAccumulationReport(report, project, reportIndex, document);
            } catch (Exception e) {
                log.error("Error generating SOD report for report {}: {}", report.getId(), e.getMessage(), e);
                generateGenericReport(report, reportIndex, document);
            }
        } else {
            generateGenericReport(report, reportIndex, document);
        }
        normalizeNewMainTablesToTargetHeight(document, tableCountBeforeGeneration, UNIFIED_MAIN_TABLE_HEIGHT_TWIPS);
    }

    // 以 twips 设置页边距
    private void setDocumentMargins(XWPFDocument doc, int top, int right, int bottom, int left) {
        CTSectPr sectPr = doc.getDocument().getBody().isSetSectPr()
            ? doc.getDocument().getBody().getSectPr()
            : doc.getDocument().getBody().addNewSectPr();

        CTPageMar pageMar = sectPr.isSetPgMar() ? sectPr.getPgMar() : sectPr.addNewPgMar();
        pageMar.setTop(BigInteger.valueOf(top));
        pageMar.setRight(BigInteger.valueOf(right));
        pageMar.setBottom(BigInteger.valueOf(bottom));
        pageMar.setLeft(BigInteger.valueOf(left));
    }

    // 厘米到 twips 的精确转换常量
    // 1 inch = 1440 twips, 1 inch = 2.54 cm
    //  1 cm = 1440 / 2.54 ≈ 566.9291338582677 twips
    private static final double CM_TO_TWIPS = 1440.0 / 2.54;
    private static final int UNIFIED_MAIN_TABLE_HEIGHT_TWIPS = 12315;
    private static final int MIN_RESULT_OR_CONCLUSION_ROW_HEIGHT_TWIPS = 454;

    // 以厘米设置页边距
    private void setDocumentMarginsCm(XWPFDocument doc, double topCm, double rightCm, double bottomCm, double leftCm) {
        long toTwips = Math.round(topCm * CM_TO_TWIPS);
        long riTwips = Math.round(rightCm * CM_TO_TWIPS);
        long boTwips = Math.round(bottomCm * CM_TO_TWIPS);
        long leTwips = Math.round(leftCm * CM_TO_TWIPS);
        setDocumentMargins(doc, (int)toTwips, (int)riTwips, (int)boTwips, (int)leTwips);
    }

    // 以厘米设置段落属性中的 SectPr 页边距（用于新节）
    private void setSectPrMarginsCm(CTSectPr sectPr, double topCm, double rightCm, double bottomCm, double leftCm) {
        long toTwips = Math.round(topCm * CM_TO_TWIPS);
        long riTwips = Math.round(rightCm * CM_TO_TWIPS);
        long boTwips = Math.round(bottomCm * CM_TO_TWIPS);
        long leTwips = Math.round(leftCm * CM_TO_TWIPS);
        
        CTPageMar pageMar = sectPr.isSetPgMar() ? sectPr.getPgMar() : sectPr.addNewPgMar();
        pageMar.setTop(BigInteger.valueOf(toTwips));
        pageMar.setRight(BigInteger.valueOf(riTwips));
        pageMar.setBottom(BigInteger.valueOf(boTwips));
        pageMar.setLeft(BigInteger.valueOf(leTwips));
    }

    /**
     * 写入 word/settings.xml：打开时自动更新域（与 Word「文件 → 选项 → 显示 → 打印前更新域」等效，由文档携带）。
     * 目录 PAGEREF、页脚 PAGE 等需在排版后计算，首次打开即可刷新。
     */
    private void enableUpdateFieldsOnOpen(XWPFDocument document) {
        try {
            XWPFSettings settings = document.getSettings();
            if (settings != null) {
                settings.setUpdateFields();
            }
        } catch (Exception e) {
            log.warn("enableUpdateFieldsOnOpen failed: {}", e.getMessage());
        }
    }

    private void setPageSizeA4(XWPFDocument doc, boolean landscape) {
        CTSectPr sectPr = doc.getDocument().getBody().isSetSectPr()
            ? doc.getDocument().getBody().getSectPr()
            : doc.getDocument().getBody().addNewSectPr();
        setSectPrPageSizeA4(sectPr, landscape);
    }
    
    // 设置 SectPr 的页面大小为 A4（用于新节）
    private void setSectPrPageSizeA4(CTSectPr sectPr, boolean landscape) {
        CTPageSz pageSz = sectPr.isSetPgSz() ? sectPr.getPgSz() : sectPr.addNewPgSz();
    
        // A4 portrait: 11906 x 16838 twips
        BigInteger w = BigInteger.valueOf(11906);
        BigInteger h = BigInteger.valueOf(16838);
    
        if (landscape) {
            pageSz.setW(h);
            pageSz.setH(w);
            pageSz.setOrient(STPageOrientation.LANDSCAPE);
        } else {
            pageSz.setW(w);
            pageSz.setH(h);
            pageSz.setOrient(STPageOrientation.PORTRAIT);
        }
    }
    
    /**
     * 概述与分页之后、单项报告拼接之前再绑一次正文节页眉页脚（防止中间生成改写节引用）。
     */
    private void ensureMainBodyHeaderFooter(XWPFDocument document, Project project) {
        CTSectPr sectPr = MAIN_BODY_HDR_SECT_PR.get();
        if (sectPr == null) {
            log.warn("MAIN_BODY_HDR_SECT_PR unset; skip ensure main body header/footer.");
            return;
        }
        if (log.isDebugEnabled()) {
            log.debug(
                    "ensureMainBodyHeaderFooter: headerRefs={}, footerRefs={}",
                    sectPr.sizeOfHeaderReferenceArray(),
                    sectPr.sizeOfFooterReferenceArray());
        }
        createHeaderFooterForSection(document, sectPr, project.getProjectNumber());
    }

    /**
     * 写入总报告正文节页眉（报告编码）与页脚（公司名 + 第几页 共几节页）。
     */
    private void populateMainBodyHeaderFooterParts(XWPFHeader xwpfHeader, XWPFFooter xwpfFooter, String projectNumber) {
        while (!xwpfHeader.getParagraphs().isEmpty()) {
            xwpfHeader.removeParagraph(xwpfHeader.getParagraphs().get(0));
        }
        XWPFParagraph xwpfHeaderPara = xwpfHeader.createParagraph();
        xwpfHeaderPara.setAlignment(ParagraphAlignment.RIGHT);
        XWPFRun xwpfHeaderRun = xwpfHeaderPara.createRun();
        xwpfHeaderRun.setFontFamily("宋体");
        xwpfHeaderRun.setFontSize(10.5);
        xwpfHeaderRun.setText("报告编码:" + (projectNumber != null ? projectNumber : ""));

        while (!xwpfFooter.getParagraphs().isEmpty()) {
            xwpfFooter.removeParagraph(xwpfFooter.getParagraphs().get(0));
        }
        XWPFParagraph footerPara = xwpfFooter.createParagraph();
        footerPara.setAlignment(ParagraphAlignment.LEFT);
        footerPara.setSpacingBefore(0);
        footerPara.setSpacingAfter(0);

        XWPFRun footerLeftRun = footerPara.createRun();
        footerLeftRun.setFontFamily("宋体");
        footerLeftRun.setFontSize(10.5);
        footerLeftRun.setText(brandingCompanyName());

        CTP ctp = footerPara.getCTP();
        CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
        CTTabs tabs = pPr.isSetTabs() ? pPr.getTabs() : pPr.addNewTabs();
        CTTabStop tabStop = tabs.addNewTab();
        tabStop.setVal(STTabJc.RIGHT);
        tabStop.setPos(BigInteger.valueOf(9000));

        XWPFRun footerRightRun = footerPara.createRun();
        footerRightRun.setFontFamily("宋体");
        footerRightRun.setFontSize(10.5);
        footerRightRun.addTab();

        CTR ctr = footerRightRun.getCTR();
        CTText text1 = ctr.addNewT();
        text1.setStringValue("第");
        CTFldChar fldCharBegin1 = ctr.addNewFldChar();
        fldCharBegin1.setFldCharType(STFldCharType.BEGIN);
        CTText instrText1 = ctr.addNewInstrText();
        instrText1.setStringValue("PAGE \\* MERGEFORMAT");
        CTFldChar fldCharEnd1 = ctr.addNewFldChar();
        fldCharEnd1.setFldCharType(STFldCharType.END);
        CTText text2 = ctr.addNewT();
        text2.setStringValue("页 共");
        CTFldChar fldCharBegin2 = ctr.addNewFldChar();
        fldCharBegin2.setFldCharType(STFldCharType.BEGIN);
        CTText instrText2 = ctr.addNewInstrText();
        instrText2.setStringValue("SECTIONPAGES \\* MERGEFORMAT");
        CTFldChar fldCharEnd2 = ctr.addNewFldChar();
        fldCharEnd2.setFldCharType(STFldCharType.END);
        CTText text3 = ctr.addNewT();
        text3.setStringValue("页");
    }

    /**
     * 为指定节创建页眉和页脚
     * @param document Word文档对象
     * @param sectPr 节属性对象
     * @param projectNumber 报告编码
     */
    private void createHeaderFooterForSection(XWPFDocument document, CTSectPr sectPr, String projectNumber) {
        try {
            // 仅有在本 sectPr 已挂 hdr/ftr 引用时才允许「复用部件」：否则 POI 仍可能从文档别处解析出非 null 的
            // default header/footer，误走分支并直接 return，导致当前节从未写入 headerReference/footerReference → 全文无页眉。
            boolean sectHasHdrFtrRefs =
                    sectPr.sizeOfHeaderReferenceArray() > 0 && sectPr.sizeOfFooterReferenceArray() > 0;
            if (sectHasHdrFtrRefs) {
                XWPFHeaderFooterPolicy policy = new XWPFHeaderFooterPolicy(document, sectPr);
                XWPFHeader existingHeader = policy.getDefaultHeader();
                XWPFFooter existingFooter = policy.getDefaultFooter();
                if (existingHeader != null && existingFooter != null) {
                    populateMainBodyHeaderFooterParts(existingHeader, existingFooter, projectNumber);
                    if (log.isDebugEnabled()) {
                        log.debug(
                                "createHeaderFooterForSection: reused DEFAULT header/footer on sectPr (hdrRefs={}, ftrRefs={})",
                                sectPr.sizeOfHeaderReferenceArray(),
                                sectPr.sizeOfFooterReferenceArray());
                    }
                    return;
                }
            }

            clearSectionHeaderFooterReferences(sectPr);
            XWPFHeaderFooterPolicy policy = new XWPFHeaderFooterPolicy(document, sectPr);

            XWPFHeader xwpfHeader = policy.createHeader(XWPFHeaderFooterPolicy.DEFAULT);
            XWPFFooter xwpfFooter = policy.createFooter(XWPFHeaderFooterPolicy.DEFAULT);
            if (xwpfHeader != null && xwpfFooter != null) {
                populateMainBodyHeaderFooterParts(xwpfHeader, xwpfFooter, projectNumber);
            }

        } catch (Exception e) {
            log.error("Error creating header and footer for section", e);
        }
    }

    /**
     * 清理节上已有的页眉/页脚引用，避免同一节叠加多份引用。
     */
    private void clearSectionHeaderFooterReferences(CTSectPr sectPr) {
        if (sectPr == null) {
            return;
        }
        while (sectPr.sizeOfHeaderReferenceArray() > 0) {
            sectPr.removeHeaderReference(0);
        }
        while (sectPr.sizeOfFooterReferenceArray() > 0) {
            sectPr.removeFooterReference(0);
        }
    }

    private void copySectionHeaderFooterReferences(CTSectPr sourceSectPr, CTSectPr targetSectPr) {
        if (sourceSectPr == null || targetSectPr == null) {
            return;
        }
        clearSectionHeaderFooterReferences(targetSectPr);
        for (int i = 0; i < sourceSectPr.sizeOfHeaderReferenceArray(); i++) {
            CTHdrFtrRef src = sourceSectPr.getHeaderReferenceArray(i);
            CTHdrFtrRef dst = targetSectPr.addNewHeaderReference();
            dst.setType(src.getType());
            dst.setId(src.getId());
        }
        for (int i = 0; i < sourceSectPr.sizeOfFooterReferenceArray(); i++) {
            CTHdrFtrRef src = sourceSectPr.getFooterReferenceArray(i);
            CTHdrFtrRef dst = targetSectPr.addNewFooterReference();
            dst.setType(src.getType());
            dst.setId(src.getId());
        }
    }

    /**
     * 无第三方 PDF 附录时，文档最后一节主要由 {@code w:body/w:sectPr} 描述；若页眉仅挂在段落级 sectPr 上，
     * Word 合并末节属性时可能得不到 hdr/ftr，表现为「全程无页眉页脚」。将正文锚点节的引用镜像到 body 末尾 sectPr（同一 r:id 指向同一部件）。
     * 有附录时由 {@link #syncBodySectPrForAppendixWithoutHeaderFooter} 单独处理 body，此处跳过。
     */
    private void mirrorMainBodyHeaderFooterRefsToBodySectPrIfNeeded(XWPFDocument document, Project project) {
        String relPath = project.getSummaryThirdPartyFullRelPath();
        if (relPath != null && !relPath.trim().isEmpty()) {
            Path attachmentPath = resolveSummaryAttachmentPath(relPath.trim());
            if (Files.exists(attachmentPath)) {
                String lower = attachmentPath.getFileName().toString().toLowerCase(Locale.ROOT);
                if (lower.endsWith(".pdf")) {
                    return;
                }
            }
        }
        CTSectPr main = MAIN_BODY_HDR_SECT_PR.get();
        if (main == null) {
            return;
        }
        if (main.sizeOfHeaderReferenceArray() == 0 || main.sizeOfFooterReferenceArray() == 0) {
            log.warn("mirrorMainBodyHeaderFooterRefsToBodySectPrIfNeeded: main sectPr has no hdr/ftr refs; skip mirror.");
            return;
        }
        try {
            CTBody ctBody = document.getDocument().getBody();
            CTSectPr dest = ctBody.isSetSectPr() ? ctBody.getSectPr() : ctBody.addNewSectPr();
            clearSectionHeaderFooterReferences(dest);
            for (int i = 0; i < main.sizeOfHeaderReferenceArray(); i++) {
                CTHdrFtrRef src = main.getHeaderReferenceArray(i);
                CTHdrFtrRef dr = dest.addNewHeaderReference();
                dr.setType(src.getType());
                dr.setId(src.getId());
            }
            for (int i = 0; i < main.sizeOfFooterReferenceArray(); i++) {
                CTHdrFtrRef src = main.getFooterReferenceArray(i);
                CTHdrFtrRef dr = dest.addNewFooterReference();
                dr.setType(src.getType());
                dr.setId(src.getId());
            }
        } catch (Exception e) {
            log.warn("mirrorMainBodyHeaderFooterRefsToBodySectPrIfNeeded failed: {}", e.getMessage());
        }
    }

    /**
     * 绑定空白页眉/页脚 part，打断与上一节的「同前节」链接。
     * 必须用 {@code new XWPFHeaderFooterPolicy(document, sectPr)}：{@code XWPFDocument#createHeader} 会把引用误写到 body 末尾 sectPr。
     */
    private void bindEmptyHeaderFooterToSectPr(XWPFDocument document, CTSectPr sectPr) {
        if (sectPr == null) {
            return;
        }
        clearSectionHeaderFooterReferences(sectPr);
        if (sectPr.isSetTitlePg()) {
            sectPr.unsetTitlePg();
        }
        try {
            XWPFHeaderFooterPolicy policy = new XWPFHeaderFooterPolicy(document, sectPr);
            XWPFHeader xwpfHeader = policy.createHeader(XWPFHeaderFooterPolicy.DEFAULT);
            if (xwpfHeader != null && xwpfHeader.getParagraphs().isEmpty()) {
                xwpfHeader.createParagraph();
            }
            XWPFFooter xwpfFooter = policy.createFooter(XWPFHeaderFooterPolicy.DEFAULT);
            if (xwpfFooter != null && xwpfFooter.getParagraphs().isEmpty()) {
                xwpfFooter.createParagraph();
            }
            // 勿清空 body 末尾 sectPr 的 hdr/ftr：会破坏 Word 对末节的合并，易导致中段/全程页眉页脚不渲染。
        } catch (Exception e) {
            log.warn("bindEmptyHeaderFooterToSectPr failed: {}", e.getMessage());
        }
    }

    /**
     * 文末第三方 PDF 附录：下一页起新节，空白页眉页脚以打断「同前节」。
     */
    private void beginAppendixSectionWithoutHeaderFooter(XWPFDocument document) {
        XWPFParagraph breakPara = document.createParagraph();
        CTP ctp = breakPara.getCTP();
        CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
        if (pPr.isSetSectPr()) {
            pPr.unsetSectPr();
        }
        CTSectPr sectPr = pPr.addNewSectPr();
        CTSectType sectType = sectPr.addNewType();
        sectType.setVal(STSectionMark.NEXT_PAGE);
        setSectPrPageSizeA4(sectPr, false);
        setSectPrMarginsCm(sectPr, 2.6, 2.6, 2.5, 2.6);
        // 段落级 sectPr 描述的是「附录前一节（正文）」：必须保留正文页眉页脚引用，否则正文会被清空。
        CTSectPr mainBodySectPr = MAIN_BODY_HDR_SECT_PR.get();
        if (mainBodySectPr != null
                && mainBodySectPr.sizeOfHeaderReferenceArray() > 0
                && mainBodySectPr.sizeOfFooterReferenceArray() > 0) {
            copySectionHeaderFooterReferences(mainBodySectPr, sectPr);
        }
    }

    /**
     * 最后一节为附录时，同步 body 末尾 sectPr。
     */
    private void syncBodySectPrForAppendixWithoutHeaderFooter(XWPFDocument document) {
        CTSectPr bodySectPr = document.getDocument().getBody().isSetSectPr()
                ? document.getDocument().getBody().getSectPr()
                : document.getDocument().getBody().addNewSectPr();
        setSectPrPageSizeA4(bodySectPr, false);
        setSectPrMarginsCm(bodySectPr, 2.6, 2.6, 2.5, 2.6);
        bindEmptyHeaderFooterToSectPr(document, bodySectPr);
    }
    
    /**
     * 为段落添加底部边框（用于页眉线）
     * @param paragraph 段落对象
     */
    private void addParagraphBottomBorder(XWPFParagraph paragraph) {
        try {
            CTP ctp = paragraph.getCTP();
            CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
            CTPBdr pBdr = pPr.isSetPBdr() ? pPr.getPBdr() : pPr.addNewPBdr();
            CTBorder bottomBorder = pBdr.isSetBottom() ? pBdr.getBottom() : pBdr.addNewBottom();
            bottomBorder.setVal(STBorder.SINGLE);
            bottomBorder.setSz(BigInteger.valueOf(6)); // 0.5磅，约等于0.75pt
            bottomBorder.setColor("000000"); // 黑色
            bottomBorder.setSpace(BigInteger.valueOf(1)); // 边框与文本的间距
        } catch (Exception e) {
            log.warn("Failed to add bottom border to paragraph: " + e.getMessage());
        }
    }
    
    /**
     * 为段落添加顶部边框（用于页脚线）
     * @param paragraph 段落对象
     */
    private void addParagraphTopBorder(XWPFParagraph paragraph) {
        try {
            CTP ctp = paragraph.getCTP();
            CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
            CTPBdr pBdr = pPr.isSetPBdr() ? pPr.getPBdr() : pPr.addNewPBdr();
            CTBorder topBorder = pBdr.isSetTop() ? pBdr.getTop() : pBdr.addNewTop();
            topBorder.setVal(STBorder.SINGLE);
            topBorder.setSz(BigInteger.valueOf(6)); // 0.5磅，约等于0.75pt
            topBorder.setColor("000000"); // 黑色
            topBorder.setSpace(BigInteger.valueOf(1)); // 边框与文本的间距
        } catch (Exception e) {
            log.warn("Failed to add top border to paragraph: " + e.getMessage());
        }
    }

    

    private void addTitle(XWPFDocument document, String title) {
        XWPFParagraph paragraph = document.createParagraph();
        paragraph.setAlignment(ParagraphAlignment.CENTER);
        XWPFRun run = paragraph.createRun();
        run.setText(title);
        run.setBold(true);
        run.setFontSize(24);
    }

    private void addSectionTitle(XWPFDocument document, String title) {
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText(title);
        run.setBold(true);
        run.setFontSize(18);
    }

    private void addParagraph(XWPFDocument document, String text) {
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText(text);
    }

    /**
     * 添加加粗标题段落（用于概述部分的标题，如1.1、1.1.1等）
     * 字体加粗，段前段后 100 twips，{@link #SUMMARY_SECTION_LINE_SPACING} 倍行距
     */
    private void addBoldTitleParagraph(XWPFDocument document, String text) {
        XWPFParagraph paragraph = document.createParagraph();
        paragraph.setAlignment(ParagraphAlignment.LEFT);
        paragraph.setSpacingBefore(100); // 段前间距100 twips
        paragraph.setSpacingAfter(100);  // 段后间距100 twips
        paragraph.setSpacingLineRule(LineSpacingRule.AUTO);
        paragraph.setSpacingBetween(SUMMARY_SECTION_LINE_SPACING);
        
        XWPFRun run = paragraph.createRun();
        run.setFontFamily("宋体");
        run.setFontSize(14);
        run.setBold(true);
        run.setText(text);
    }

    /**
     * 添加加粗标题段落，并按需设置大纲级别（1～9 对应 Word 的 level 0～8）。
     */
    private void addBoldTitleParagraph(XWPFDocument document, String text, int headingLevel) {
        addBoldTitleParagraph(document, text, headingLevel, null, null);
    }

    /**
     * 添加加粗标题段落；可选书签（与摘要目录 PAGEREF 对应）。
     */
    private void addBoldTitleParagraph(XWPFDocument document, String text, int headingLevel,
                                       String bookmarkName, AtomicInteger bookmarkIdGen) {
        XWPFParagraph paragraph = document.createParagraph();
        paragraph.setAlignment(ParagraphAlignment.LEFT);
        paragraph.setSpacingBefore(100);
        paragraph.setSpacingAfter(100);
        paragraph.setSpacingLineRule(LineSpacingRule.AUTO);
        paragraph.setSpacingBetween(SUMMARY_SECTION_LINE_SPACING);

        if (headingLevel >= 1 && headingLevel <= 9) {
            CTPPr pPr = paragraph.getCTP().isSetPPr() ? paragraph.getCTP().getPPr() : paragraph.getCTP().addNewPPr();
            CTDecimalNumber outlineLvl = pPr.isSetOutlineLvl() ? pPr.getOutlineLvl() : pPr.addNewOutlineLvl();
            outlineLvl.setVal(BigInteger.valueOf(headingLevel - 1L));
        }

        int bmNumericId = -1;
        CTP ctp = paragraph.getCTP();
        if (bookmarkName != null && !bookmarkName.isEmpty() && bookmarkIdGen != null) {
            bmNumericId = bookmarkIdGen.getAndIncrement();
            CTBookmark bmStart = ctp.addNewBookmarkStart();
            bmStart.setName(bookmarkName);
            bmStart.setId(BigInteger.valueOf(bmNumericId));
        }

        XWPFRun run = paragraph.createRun();
        run.setFontFamily("宋体");
        int titleFontSize = headingLevel == 1 ? 15 : 14;
        run.setFontSize(titleFontSize);
        run.setBold(true);
        run.setText(text);

        if (bookmarkName != null && !bookmarkName.isEmpty() && bookmarkIdGen != null) {
            CTMarkupRange bmEnd = ctp.addNewBookmarkEnd();
            bmEnd.setId(BigInteger.valueOf(bmNumericId));
        }
    }

    /**
     * 添加首行缩进的描述段落（概述项目描述、发现问题条目、工作内容条目等）
     * 首行缩进两字符（560 twips），{@link #SUMMARY_SECTION_LINE_SPACING} 倍行距
     */
    private void addIndentedParagraph(XWPFDocument document, String text) {
        XWPFParagraph paragraph = document.createParagraph();
        paragraph.setAlignment(ParagraphAlignment.LEFT);
        paragraph.setSpacingBefore(0);
        paragraph.setSpacingAfter(0);
        paragraph.setSpacingLineRule(LineSpacingRule.AUTO);
        paragraph.setSpacingBetween(SUMMARY_SECTION_LINE_SPACING);
        paragraph.setIndentationFirstLine(560); // 首行缩进两字符（14号字体）
        
        XWPFRun run = paragraph.createRun();
        run.setFontFamily("宋体");
        run.setFontSize(14);
        run.setText(text);
    }

    private XWPFTable createTable(XWPFDocument document, JsonNode columns, JsonNode rows) {
        XWPFTable table = document.createTable();
        
        // 设置表格边框
        table.setInsideHBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");
        table.setInsideVBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");
        table.setTopBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");
        table.setBottomBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");
        table.setLeftBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");
        table.setRightBorder(XWPFTable.XWPFBorderType.SINGLE, 4, 0, "000000");

        // 创建表头行
        XWPFTableRow headerRow = table.getRow(0);
        int colIndex = 0;
        for (JsonNode column : columns) {
            // 兼容新旧字段格式: 优先使用label,然后key,最后name
            String columnName = column.has("label") ? column.get("label").asText() : 
                               (column.has("key") ? column.get("key").asText() : 
                               (column.has("name") ? column.get("name").asText() : "未命名"));
            XWPFTableCell cell = colIndex == 0 ? headerRow.getCell(0) : headerRow.addNewTableCell();
            XWPFParagraph cellParagraph = cell.getParagraphs().get(0);
            XWPFRun cellRun = cellParagraph.createRun();
            cellRun.setText(columnName);
            cellRun.setBold(true);
            colIndex++;
        }

        // 创建数据行
        for (JsonNode row : rows) {
            XWPFTableRow tableRow = table.createRow();
            colIndex = 0;
            for (JsonNode column : columns) {
                // ✅ 兼容新旧字段格式: 优先使用key作为字段名,然后name
                String fieldName = column.has("key") ? column.get("key").asText() : 
                                  (column.has("name") ? column.get("name").asText() : null);
                
                // ✅ 如果字段名无效,跳过此列
                if (fieldName == null) {
                    colIndex++;
                    continue;
                }
                
                XWPFTableCell cell = tableRow.getCell(colIndex);
                XWPFParagraph cellParagraph = cell.getParagraphs().get(0);
                XWPFRun cellRun = cellParagraph.createRun();
                
                // 获取值（处理不同类型）
                String value = "";
                if (row.has(fieldName)) {
                    JsonNode cellValue = row.get(fieldName);
                    if (cellValue.isArray()) {
                        value = ""; // 跳过表格中的图片数组
                    } else {
                        value = cellValue.asText();
                    }
                }
                
                cellRun.setText(value);
                colIndex++;
            }
        }

        return table;
    }

    private void addImagesForReportItem(XWPFDocument document, JsonNode rows) {
        // 收集所有图片ID
        for (JsonNode row : rows) {
            if (row.has("imageIds") && row.get("imageIds").isArray()) {
                for (JsonNode imageId : row.get("imageIds")) {
                    int id = imageId.asInt();
                    Image image = imageRepository.findById(id).orElse(null);
                    if (image != null && java.nio.file.Files.exists(java.nio.file.Paths.get(image.getStoragePath()))) {
                        try {
                            addImageToDocument(document, image.getStoragePath(), image.getFileName());
                        } catch (Exception ex) {
                            log.warn("Error adding image {}: {}", id, ex.getMessage());
                        }
                    }
                }
            }
        }
    }

