        createTableCell(row7.getCell(3), getCustomField(report, "试块类型", "镀铬试块"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row8 = mainTable.createRow();
