        createTableCell(row10.getCell(3), getCustomField(report, "渗透时间", "12min"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        
        XWPFTableRow row101 = mainTable.createRow();
        setRowHeight(row101, 454);
        createTableCell(row101.getCell(0), "渗透温度", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row101.getCell(1), "25℃", 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row101.getCell(2), "干燥方法", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row101.getCell(3), "自然干燥", 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
          
        
        XWPFTableRow row11 = mainTable.createRow();
        setRowHeight(row11, 454);
        createTableCell(row11.getCell(0), "光照度", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row11.getCell(1), getCustomField(report, "光照度", "1300lx"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row11.getCell(2), "显像时间", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row11.getCell(3), getCustomField(report, "显像时间", "10～60min"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row12 = mainTable.createRow();
        setRowHeight(row12, 454);
        createTableCell(row12.getCell(0), "观察方法", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row12.getCell(1), getCustomField(report, "观察方法", "目视"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row12.getCell(2), "验收等级", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row12.getCell(3), getCustomField(report, "验收等级", "Ⅰ级"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row13 = mainTable.createRow();
        setRowHeight(row13, inspectorRowHeight(report));
        createTableCell(row13.getCell(0), "检测人员", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row13.getCell(1), getFieldValue(report, "inspector", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
