        XWPFTableRow row1 = table.getRow(0);
        setRowHeight(row1, 454);
        createTableCell(row1.getCell(0), "扫查方法", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row1.getCell(1), getCustomField(report, "扫查方法", "单面双侧/单面单侧 锯齿型扫查 斜平行扫查"), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
        XWPFTableRow row3 = table.createRow();
        setRowHeight(row3, 554);
        
       
        createTableCell(row3.getCell(0), "参数", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(1), "1号探头(7.5MHz0.5x10mm，16阵元)", 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(2),  "/", 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER,2);
        XWPFTableRow row4 = table.createRow();
        setRowHeight(row4, 454);
        createTableCell(row4.getCell(0), "检测灵敏度", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        List<ProjectComponent> comps = resolveComponentsForReport(report);
        String wallThickness = (comps != null && !comps.isEmpty() && comps.get(0) != null)? comps.get(0).getWallThickness(): null;
        Double wt = parseWallThickness(wallThickness);
        String sensitivity = "";
        if(wt != null){
            if(wt >= 15 && wt <= 30){
                sensitivity = "φ2mm-18dB φ2mm-24dB";
            } else if(wt >= 3.5 && wt < 15){
                sensitivity = "φ2mm-18dB φ2mm-24dB";
            }
        }

        createTableCell(row4.getCell(1), sensitivity, 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(2), "/", 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER,2);
        XWPFTableRow row5 = table.createRow();
        setRowHeight(row5, 454);
        createTableCell(row5.getCell(0), "综合补偿", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(1), getCustomField(report, "1号探头综合补偿", "3dB"), 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(2), getCustomField(report, "2号探头综合补偿", "/"), 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER,2);
