    private void addPautBoltProbeAndSensitivityTable(XWPFDocument document, Report report, Project project, String type) throws Exception {
        XWPFTable table = document.createTable(1, 3);
        setupTableProperties(table, PT_TABLE_WIDTH);
        XWPFTableRow row1 = table.getRow(0);
        setRowHeight(row1, 554);
        createTableCell(row1.getCell(0), "探头参数", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String probe1 = TypeLabelUtil.pautRootShapeFromType(type)
            .flatMap(TypeLabelUtil::pautBoltProbeParamForRootShape)
            .orElse(null);
        if (probe1 == null) {
            switch (type) {
                case "叶片":
                    probe1 = "1号探头（5MHz阵元数32晶片1×10mm)";
                    break;
                case "叶根（叉形、菌形）":
                    probe1 = "1号探头（7.5MHz阵元数16晶片0.5×10mm)";
                    break;
                case "叶根（T形、枞树形）":
                    probe1 = "1号探头（5MHz阵元数10晶片0.5×0.5mm)";
                    break;
                default:
                    break;
            }
        }
        if (probe1 != null) {
            createTableCell(row1.getCell(1), probe1, 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(row1.getCell(2), "1号探头（    /    )", 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }
        XWPFTableRow row2 = table.createRow();
        setRowHeight(row2, 454);
        createTableCell(row2.getCell(0), "检测灵敏度", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(1), "模拟裂纹增益10dB", 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(2), "/", 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        XWPFTableRow row3 = table.createRow();
        setRowHeight(row3, 454);
        createTableCell(row3.getCell(0), "综合补偿", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(1), "0dB", 3590, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(2), "/", 3591, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
    }

