    /**
     * @param contentRowHeightTwips 检测内容合并单元格行高（轴瓦等模板可加高以贴合纸件版式）
     */
    private void addUTDetectionContentTable(XWPFDocument document, Report report, Project project, int contentRowHeightTwips)
            throws Exception {
        ExperimentType expType = report.getExperimentTypeId() != null
            ? experimentTypeRepository.findById(report.getExperimentTypeId()).orElse(null)
            : (report.getReportItems() != null && !report.getReportItems().isEmpty()
                ? report.getReportItems().get(0).getExperimentType() : null);
        String body = utDetectionContentNarrativeBody(report, expType);
        String detectionContent = body.isEmpty() ? "检测内容：" : "检测内容：\n  " + body;
        detectionContent = appendUtStyleFigureSuffix(detectionContent, report);
        XWPFTable table = document.createTable(1, 4);
        setupTableProperties(table, PT_TABLE_WIDTH);
        XWPFTableRow contentRow = table.getRow(0);
        setRowHeight(contentRow, contentRowHeightTwips);
        createTableCell(contentRow.getCell(0), detectionContent, PT_TABLE_WIDTH,
            ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);
    }

    /** 对接焊缝：缺陷表 8 列（序号、位置、波幅(dB)、深度(mm)、长度(mm)、高度(mm)、级别、备注）+ 检测结果 + 签字 + 附页 */
    private void addUTButtWeldDefectAndResultAndSign(Report report, Project project, XWPFDocument document,
            String appendixDocNumber, String reportTitleText) throws Exception {
        JsonNode detectionData = getDetectionDataFromReport(report);
        List<JsonNode> defectRows = collectUTDefectRows(detectionData);
        final int defectCols = 8;
        int colWidth = PT_TABLE_WIDTH / defectCols;

        XWPFTable table = document.createTable(1, defectCols);
        setupTableProperties(table, PT_TABLE_WIDTH);

        XWPFTableRow titleRow = table.getRow(0);
        setRowHeight(titleRow, 454);
        createTableCell(titleRow.getCell(0), "缺 陷 信 息", PT_TABLE_WIDTH,
            ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, defectCols);

        String[] defectHeaders = {"序号", "位置", "波幅(dB)", "深度(mm)", "长度(mm)", "高度(mm)", "级 别", "备 注"};
        XWPFTableRow headerRow = table.createRow();
        setRowHeight(headerRow, 454);
        for (int i = 0; i < defectCols; i++) {
            createTableCell(headerRow.getCell(i), defectHeaders[i], colWidth,
                ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }

        int mainRows = 1;
        for (int i = 0; i < mainRows; i++) {
            XWPFTableRow dataRow = table.createRow();
            setRowHeight(dataRow, 454);
            JsonNode defectRow = i < defectRows.size() ? defectRows.get(i) : null;
            createTableCell(dataRow.getCell(0), getDefectNumberValue(defectRow), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(1), getJsonValue(defectRow, "位置", getJsonValue(defectRow, "起点位置", "/")), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(2), getJsonValue(defectRow, "波幅(dB)", getJsonValue(defectRow, "波幅", "/")), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(3), getJsonValue(defectRow, "深度(mm)", getJsonValue(defectRow, "深度", "/")), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(4), getJsonValue(defectRow, "长度(mm)", getJsonValue(defectRow, "长度", "/")), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(5), getJsonValue(defectRow, "高度(mm)", getJsonValue(defectRow, "高度", "/")), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(6), getJsonValue(defectRow, "级别", "/"), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(7), getJsonValue(defectRow, "备注", "/"), colWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }

        String resultContent = applySavedConclusionOverrideOrDefault(report,
                segmentHasDefectForNdt(report)
                        ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                        : "检测结果：\n  上述检测条件下，未见可记录缺陷，评定为Ⅰ级。");
        XWPFTableRow resultRow = table.createRow();
        setRowHeight(resultRow, 1604);
        createTableCell(resultRow.getCell(0), resultContent, PT_TABLE_WIDTH,
            ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, defectCols);

        String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
        String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
        String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());

        XWPFTableRow signRow = table.createRow();
        setRowHeight(signRow, 454);
        createTableCell(signRow.getCell(0), "编制（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(2), "审核（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER,5);
        

        XWPFTableRow approveRow = table.createRow();
        setRowHeight(approveRow, 454);
        createTableCell(approveRow.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(approveRow.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 7);

        document.createParagraph().createRun().addBreak(BreakType.PAGE);

        boolean hasDefectOverflow = defectRows.size() > mainRows;
        boolean hasImageAppendix = report.getImageAttachments() != null && !report.getImageAttachments().isEmpty();
        List<JsonNode> remaining = hasDefectOverflow
                ? defectRows.subList(mainRows, defectRows.size())
                : new ArrayList<>();
        // if (hasDefectAppendix || hasImageAppendix) {
        //     document.createParagraph().createRun().addBreak(BreakType.PAGE);
        // }
        if (!remaining.isEmpty() || hasImageAppendix) {
            generateUTButtWeldAppendix(remaining, report, project, document, hasImageAppendix, appendixDocNumber, reportTitleText);
        }
    }

