    private void addUTDetectionContentRow(XWPFDocument document, Report report, Project project) throws Exception {
        XWPFTable table = document.getTables().get(document.getTables().size() - 1);
        ExperimentType expType = report.getExperimentTypeId() != null
            ? experimentTypeRepository.findById(report.getExperimentTypeId()).orElse(null)
            : (report.getReportItems() != null && !report.getReportItems().isEmpty()
                ? report.getReportItems().get(0).getExperimentType() : null);
        String body = utDetectionContentNarrativeBody(report, expType);
        String detectionContent = body.isEmpty() ? "检测内容：" : "检测内容：\n  " + body;
        detectionContent = appendUtStyleFigureSuffix(detectionContent, report);
        XWPFTableRow contentRow = table.createRow();
        setRowHeight(contentRow, 4505);
        createTableCell(contentRow.getCell(0), detectionContent, PT_TABLE_WIDTH,
            ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);
    }

    /**
     * 添加缺陷表（可选）、检测结果、备注（仅螺栓）、签字行；并处理附页（数据附页+附图附页）。
     * @param hasDefectTable 是否有缺陷表（对接焊缝、弯头/弯管、角焊缝、自定义）
     * @param hasRemarkArea 是否有备注区（仅螺栓）
     * @param detectionResultParagraphOverride 非空且未设置导出结论覆盖时，作为「检测结果」单元格全文（如轴瓦模板）；优先级为导出结论覆盖、本参数、hasDefect 默认两句
     * @param resultRowHeightTwips 非 null 时用作「检测结果」行行高（twips）；null 时默认 1604（与既有 UT 一致）
     */
    private void addUTDefectAndResultAndSign(XWPFDocument document, Report report, Project project,
            boolean hasDefectTable, boolean hasRemarkArea, String docNumber,
            String detectionResultParagraphOverride, Integer resultRowHeightTwips) throws Exception {
        JsonNode detectionData = getDetectionDataFromReport(report);
        List<JsonNode> defectRows = collectDefectRows(detectionData, supportsRecordOnlyFlagForReport(report));
        int cols = hasDefectTable ? 6 : 4;
        XWPFTable table = document.createTable(1, cols);
        setupTableProperties(table, PT_TABLE_WIDTH);

        if (hasDefectTable) {
            XWPFTableRow titleRow = table.getRow(0);
            setRowHeight(titleRow, 454);
            createTableCell(titleRow.getCell(0), "缺 陷 信 息", PT_TABLE_WIDTH,
                ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 6);

            XWPFTableRow headerRow = table.createRow();
            setRowHeight(headerRow, 454);
            String[] defectHeaders = {"序号", "起点位置", "终点位置", "长 度", "级 别", "备 注"};
            for (int i = 0; i < defectHeaders.length; i++) {
                createTableCell(headerRow.getCell(i), defectHeaders[i], PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            }

            for (int i = 0; i < UT_DEFECT_MAIN_ROWS; i++) {
                XWPFTableRow dataRow = table.createRow();
                setRowHeight(dataRow, 454);
                JsonNode defectRow = i < defectRows.size() ? defectRows.get(i) : null;
                createTableCell(dataRow.getCell(0), getDefectNumberValue(defectRow), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(1), getJsonValue(defectRow, "起点位置", "/"), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(2), getJsonValue(defectRow, "终点位置", "/"), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(3), getJsonValue(defectRow, "长度", "/"), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(4), getJsonValue(defectRow, "级别", "/"), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(5), getJsonValue(defectRow, "备注", "/"), PT_DEFECT_COLUMN_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            }
        }

        String resultContent;
        String savedConclusion = nonBlankSavedConclusionParagraphOrNull(report);
        if (savedConclusion != null) {
            resultContent = savedConclusion;
        } else if (detectionResultParagraphOverride != null && !detectionResultParagraphOverride.trim().isEmpty()) {
            resultContent = detectionResultParagraphOverride.trim();
        } else {
            resultContent = segmentHasDefectForNdt(report)
                    ? "检测结果：\n  在上述检测条件下，被检部位存在缺陷显示，详见缺陷信息。"
                    : "检测结果：\n  在上述检测条件下，被检部位未见缺陷显示，评定合格。";
        }
        XWPFTableRow resultRow = hasDefectTable ? table.createRow() : table.getRow(0);
        int resultHeightTwips = resultRowHeightTwips != null ? resultRowHeightTwips : 1604;
        setRowHeight(resultRow, resultHeightTwips);
        if (hasDefectTable) {
            createTableCell(resultRow.getCell(0), resultContent, PT_TABLE_WIDTH,
                ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, 6);
        } else {
            createTableCell(resultRow.getCell(0), resultContent, PT_TABLE_WIDTH,
                ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, 4);
        }

        if (hasRemarkArea) {
            XWPFTableRow remarkRow = table.createRow();
            setRowHeight(remarkRow, 454);
            createTableCell(remarkRow.getCell(0), "备注", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(remarkRow.getCell(1), getCustomField(report, "备注", "/"), 7181,
                ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.CENTER, 3);
        }

        String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
        String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
        String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());

        XWPFTableRow signRow = table.createRow();
        setRowHeight(signRow, 454);
        createTableCell(signRow.getCell(0), "编制（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(2), "审核（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, hasDefectTable ? 3 : 1);

        XWPFTableRow approveRow = table.createRow();
        setRowHeight(approveRow, 454);
        createTableCell(approveRow.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(approveRow.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, hasDefectTable ? 5 : 3);

        document.createParagraph().createRun().addBreak(BreakType.PAGE);

        boolean hasDefectOverflow = hasDefectTable && defectRows.size() > UT_DEFECT_MAIN_ROWS;
        boolean hasImageAppendix = report.getImageAttachments() != null && !report.getImageAttachments().isEmpty();
        List<JsonNode> remaining = hasDefectOverflow
                ? defectRows.subList(UT_DEFECT_MAIN_ROWS, defectRows.size())
                : new ArrayList<>();

        // if (hasDefectAppendix || hasImageAppendix) {
        //     document.createParagraph().createRun().addBreak(BreakType.PAGE);
        // }
        if (!remaining.isEmpty() || hasImageAppendix) {
            generateUTAppendix(remaining, report, project, document, docNumber, hasImageAppendix);
        }
    }

    private void generateUTAppendix(List<JsonNode> defectRows, Report report, Project project, XWPFDocument document,
            String docNumber, boolean hasImageAppendix) throws Exception {
        if (defectRows != null && !defectRows.isEmpty()) {
            for (int pageStart = 0; pageStart < defectRows.size(); pageStart += 21) {
                addUTReportHeader(document, "超声检测报告（附页）", docNumber);

                XWPFTable table = document.createTable(1, 6);
                setupTableProperties(table, PT_TABLE_WIDTH);

                XWPFTableRow projectRow = table.getRow(0);
                setRowHeight(projectRow, 454);
                createTableCell(projectRow.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(projectRow.getCell(1), projectNameCellText(project), 7181,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 5);

                XWPFTableRow numberRow = table.createRow();
                setRowHeight(numberRow, 454);
                createTableCell(numberRow.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(numberRow.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(numberRow.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(numberRow.getCell(3), generateRecordNumber(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                XWPFTableRow titleRow = table.createRow();
                setRowHeight(titleRow, 454);
                createTableCell(titleRow.getCell(0), "缺 陷 信 息", PT_TABLE_WIDTH,
                    ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 6);

                XWPFTableRow headerRow = table.createRow();
                setRowHeight(headerRow, 454);
                String[] headers = {"序号", "起点位置", "终点位置", "长 度", "级 别", "备 注"};
                for (int i = 0; i < headers.length; i++) {
                    createTableCell(headerRow.getCell(i), headers[i], PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                }

                int rowsInPage = Math.min(21, defectRows.size() - pageStart);
                for (int i = 0; i < rowsInPage; i++) {
                    JsonNode defectRow = defectRows.get(pageStart + i);
                    XWPFTableRow dataRow = table.createRow();
                    setRowHeight(dataRow, 454);
                    createTableCell(dataRow.getCell(0), getDefectNumberValue(defectRow), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(1), getJsonValue(defectRow, "起点位置", "/"), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(2), getJsonValue(defectRow, "终点位置", "/"), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(3), getJsonValue(defectRow, "长度", "/"), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(4), getJsonValue(defectRow, "级别", "/"), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(5), getJsonValue(defectRow, "备注", "/"), PT_DEFECT_COLUMN_WIDTH,
                        ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                }
                for (int i = rowsInPage; i < 21; i++) {
                    XWPFTableRow emptyRow = table.createRow();
                    setRowHeight(emptyRow, 454);
                    for (int c = 0; c < 6; c++) {
                        createTableCell(emptyRow.getCell(c), "/", PT_DEFECT_COLUMN_WIDTH,
                            ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    }
                }

                XWPFTableRow signRow1 = table.createRow();
                setRowHeight(signRow1, 454);
                String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
                String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
                String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());
                createTableCell(signRow1.getCell(0), "编制（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1.getCell(2), "审核（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                XWPFTableRow signRow2 = table.createRow();
                setRowHeight(signRow2, 454);
                createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 5);

                document.createParagraph().createRun().addBreak(BreakType.PAGE);
            }
        }
        if (hasImageAppendix) {
            generateImageAppendix(document, report, project, "超声检测报告（附页）", docNumber, false);
        }
    }

    /**
     * 从报告附图附件解析出本地可读的 {@link ImageInfo} 列表（与附图附页一致）。
     */
    private List<ImageInfo> collectImageInfosForReport(Report report) throws Exception {
        List<ImageInfo> allImages = new ArrayList<>();
        if (report.getImageAttachments() == null || report.getImageAttachments().isEmpty()) {
            return allImages;
        }
        for (ImageAttachment attachment : report.getImageAttachments()) {
            List<String> imageUrls = objectMapper.readValue(
                    attachment.getImageUrls(),
                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class)
            );
            String description = attachment.getDescription();
            for (String imageUrl : imageUrls) {
                Integer imageId = extractImageIdFromUrl(imageUrl);
                if (imageId != null) {
                    Image image = imageRepository.findById(imageId).orElse(null);
                    if (image != null && Files.exists(Paths.get(image.getStoragePath()))) {
                        allImages.add(new ImageInfo(image, description));
                    }
                }
            }
        }
        return allImages;
    }

    private List<ImageInfo> collectImageInfosForProject(Project project) throws Exception {
        List<ImageInfo> allImages = new ArrayList<>();
        if (project.getProjectImageAttachments() == null || project.getProjectImageAttachments().isEmpty()) {
            return allImages;
        }
        for (ProjectImageAttachment attachment : project.getProjectImageAttachments()) {
            List<String> imageUrls = objectMapper.readValue(
                    attachment.getImageUrls(),
                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class)
            );
            String description = attachment.getDescription();
            for (String imageUrl : imageUrls) {
                Integer imageId = extractImageIdFromUrl(imageUrl);
                if (imageId == null) {
                    continue;
                }
                Image image = imageRepository.findById(imageId).orElse(null);
                if (image != null && Files.exists(Paths.get(image.getStoragePath()))) {
                    allImages.add(new ImageInfo(image, description));
                }
            }
        }
        return allImages;
    }

    private void appendProjectReportFigures(XWPFDocument document, Project project) throws Exception {
        List<ImageInfo> allImages = collectImageInfosForProject(project);
        if (allImages.isEmpty()) {
            return;
        }

        int imagesPerPage = 2;
        int totalPages = (allImages.size() + imagesPerPage - 1) / imagesPerPage;
        int imageNumber = 1;

        for (int pageIndex = 0; pageIndex < totalPages; pageIndex++) {
            int startIndex = pageIndex * imagesPerPage;
            int endIndex = Math.min(startIndex + imagesPerPage, allImages.size());
            List<ImageInfo> pageImages = allImages.subList(startIndex, endIndex);

            //document.createParagraph().createRun().addBreak(BreakType.PAGE);

            if (pageIndex == 0) {
                XWPFParagraph labelPara = document.createParagraph();
                labelPara.setAlignment(ParagraphAlignment.LEFT);
                XWPFRun labelRun = labelPara.createRun();
                labelRun.setFontFamily("宋体");
                labelRun.setFontSize(10);
                labelRun.setText("附图：");
                labelRun.addBreak();
            }

            for (ImageInfo imageInfo : pageImages) {
                XWPFParagraph imageParagraph = document.createParagraph();
                imageParagraph.setAlignment(ParagraphAlignment.CENTER);
                XWPFRun imageRunPara = imageParagraph.createRun();
                imageRunPara.setFontFamily("宋体");
                imageRunPara.setFontSize(10.5);
                int n = imageNumber++;
                try {
                    Path imgPath = resolveStoredImagePathForWord(imageInfo.image);
                    if (imgPath == null || !Files.exists(imgPath)) {
                        log.warn("Image path missing for project appendix image {}", imageInfo.image.getId());
                    } else {
                        try (WordEmbedImageUtil.PreparedPicture pic = WordEmbedImageUtil.prepare(imgPath, imageInfo.image.getFileName())) {
                            imageRunPara.addPicture(pic.stream(), pic.poiPictureType(), pic.embedFileName(),
                                    Units.toEMU(300), Units.toEMU(225));
                        }
                    }
                } catch (Exception e) {
                    log.warn("Error adding image {} to project appendix: {}", imageInfo.image.getId(), e.getMessage());
                }
                imageRunPara.addBreak();
                if (imageInfo.description != null && !imageInfo.description.isEmpty()) {
                    imageRunPara.setText("图" + n + " " + imageInfo.description);
                } else {
                    imageRunPara.setText("图" + n);
                }
                imageRunPara.addBreak();
            }
        }
    }

    /**
     * 生成附图附页（通用函数）
     * 每页固定显示2张图片，上下排列，如果图片超过2张则自动分页
     * 
     * @param document Word文档对象
     * @param report 报告对象
     * @param project 项目对象
     * @param reportTitle 报告标题（如："金相检测报告（附页）"）
     * @param docNumber 文档编号（如："CL/JC30/BG01-2024 (B/0)"）
     * @param useChemPersonnel true=使用Chem人员（理化检测），false=使用NDT人员（无损检测）
     */
    private void generateImageAppendix(
            XWPFDocument document,
            Report report,
            Project project,
            String reportTitle,
            String docNumber,
            boolean useChemPersonnel
    ) throws Exception {
        List<ImageInfo> allImages = collectImageInfosForReport(report);
        if (allImages.isEmpty()) {
            if (report.getImageAttachments() == null || report.getImageAttachments().isEmpty()) {
                log.debug("Report {} has no image attachments", report.getId());
            } else {
                log.debug("Report {} has no valid images", report.getId());
            }
            return;
        }

        log.debug("Report {} has {} image attachments, generating image appendix...",
                report.getId(), report.getImageAttachments().size());

        // ========== 2. 按每页2张分组并生成页面 ==========
        int imagesPerPage = 2;
        int totalPages = (allImages.size() + imagesPerPage - 1) / imagesPerPage;
        int imageNumber = 1; // 图片序号，从1开始

        for (int pageIndex = 0; pageIndex < totalPages; pageIndex++) {
            int startIndex = pageIndex * imagesPerPage;
            int endIndex = Math.min(startIndex + imagesPerPage, allImages.size());
            List<ImageInfo> pageImages = allImages.subList(startIndex, endIndex);

            // ========== 2.1 生成页眉 ==========
            // 公司名称
            XWPFParagraph companyTitle = document.createParagraph();
            companyTitle.setAlignment(ParagraphAlignment.CENTER);
            companyTitle.setSpacingBefore(0);
            companyTitle.setSpacingAfter(0);
            setExactLineSpacing(companyTitle, 20);

            XWPFRun companyRun = companyTitle.createRun();
            companyRun.setFontFamily("黑体");
            companyRun.setFontSize(14);
            companyRun.setText(brandingCompanyName());

            // 报告标题
            XWPFParagraph reportTitlePara = document.createParagraph();
            reportTitlePara.setAlignment(ParagraphAlignment.CENTER);
            reportTitlePara.setSpacingBefore(0);
            reportTitlePara.setSpacingAfter(0);
            setExactLineSpacing(reportTitlePara, 20);

            XWPFRun reportRun = reportTitlePara.createRun();
            reportRun.setFontFamily("黑体");
            reportRun.setFontSize(14);
            reportRun.setText(reportTitle);

            // 文档编号
            XWPFParagraph docNumberPara = document.createParagraph();
            docNumberPara.setAlignment(ParagraphAlignment.RIGHT);
            docNumberPara.setSpacingBefore(0);
            docNumberPara.setSpacingAfter(0);
            docNumberPara.setSpacingLineRule(LineSpacingRule.EXACT);
            docNumberPara.setSpacingBetween(1.0);

            XWPFRun docRun = docNumberPara.createRun();
            docRun.setFontFamily("宋体");
            docRun.setFontSize(10.5);
            docRun.setText(docNumber);

            // ========== 2.2 创建附图表格(4列) ==========
            XWPFTable imageTable = document.createTable(1, 4);
            setupTableProperties(imageTable, PT_TABLE_WIDTH);

            // 第一行:项目名称(cell(1)跨3列)
            XWPFTableRow headerRow1 = imageTable.getRow(0);
            setRowHeight(headerRow1, 454);
            createTableCell(headerRow1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(headerRow1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

            // 第二行:单项报告编号 | 记录编号
            XWPFTableRow headerRow2 = imageTable.createRow();
            setRowHeight(headerRow2, 454);
            createTableCell(headerRow2.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(headerRow2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(headerRow2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            String recordNumber = generateRecordNumber(report);
            createTableCell(headerRow2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

            // 第三行:附图内容(cell(0)跨4列,大高度)
            XWPFTableRow imageRow = imageTable.createRow();
            setRowHeight(imageRow, 10432);
            XWPFTableCell imageCell = imageRow.getCell(0);
            createTableCell(imageCell, "", PT_TABLE_WIDTH, ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);

            // 清除现有段落并创建新段落
            imageCell.removeParagraph(0);
            XWPFParagraph imagePara = imageCell.addParagraph();
            imagePara.setAlignment(ParagraphAlignment.LEFT);
            XWPFRun imageRun = imagePara.createRun();
            imageRun.setFontFamily("宋体");
            imageRun.setFontSize(10);
            imageRun.setText("附图：");
            imageRun.addBreak();

            // ========== 2.3 添加当前页的图片（最多2张，上下排列） ==========
            for (ImageInfo imageInfo : pageImages) {
                // 为每张图片创建单独的段落并居中（包含描述文字和图片）
                XWPFParagraph imageParagraph = imageCell.addParagraph();
                imageParagraph.setAlignment(ParagraphAlignment.CENTER);
                XWPFRun imageRunPara = imageParagraph.createRun();
                imageRunPara.setFontFamily("宋体");
                imageRunPara.setFontSize(10.5);

                // // 添加图片序号和描述文字（居中显示）
                // if (imageInfo.description != null && !imageInfo.description.isEmpty()) {
                //     imageRunPara.setText("图" + imageNumber + " " + imageInfo.description);
                // } else {
                //     // 即使没有描述，也显示序号
                //     imageRunPara.setText("图" + imageNumber);
                // }
                // imageRunPara.addBreak();

                // 添加图片（调整大小：宽度400磅，高度300磅）；嵌入前压缩以减小 docx 体积
                try {
                    Path imgPath = resolveStoredImagePathForWord(imageInfo.image);
                    if (imgPath == null || !Files.exists(imgPath)) {
                        log.warn("Image path missing for appendix image {}", imageInfo.image.getId());
                    } else {
                        try (WordEmbedImageUtil.PreparedPicture pic = WordEmbedImageUtil.prepare(imgPath, imageInfo.image.getFileName())) {
                            imageRunPara.addPicture(pic.stream(), pic.poiPictureType(), pic.embedFileName(),
                                    Units.toEMU(300), Units.toEMU(225));
                        }
                    }
                } catch (Exception e) {
                    log.warn("Error adding image {} to appendix: {}", imageInfo.image.getId(), e.getMessage());
                }
                imageRunPara.addBreak();
                // 添加图片序号和描述文字（居中显示）
                if (imageInfo.description != null && !imageInfo.description.isEmpty()) {
                    imageRunPara.setText("图" + imageNumber + " " + imageInfo.description);
                } else {
                    // 即使没有描述，也显示序号
                    imageRunPara.setText("图" + imageNumber);
                }
                
                
                // 图片后添加换行
                imageRunPara.addBreak();
                
                // 序号递增
                imageNumber++;
            }

            // ========== 2.4 签批行 ==========
            XWPFTableRow signRow1 = imageTable.createRow();
            setRowHeight(signRow1, 454);
            String writeName, reviewName, approveName;

            if (useChemPersonnel) {
                // 使用理化检测人员
                createTableCell(signRow1.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                writeName = signatureLineForReport(report, project, "writer", project.getWriterChem(), project.getWriterDateChem());
                createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerChem(), project.getReviewDateChem());
                createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                XWPFTableRow signRow2 = imageTable.createRow();
                setRowHeight(signRow2, 454);
                createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                approveName = signatureLineForReport(report, project, "approver", project.getApproverChem(), project.getApprovalDateChem());
                XWPFTableCell approveCell = signRow2.getCell(1);
                createTableCell(approveCell, approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
            } else {
                // 使用无损检测人员
                createTableCell(signRow1.getCell(0), "编制（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                writeName = signatureLineForNdtWithLevel(report, project, project.getWriterNdt(), project.getWriterDateNdt(), "writer");
                createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1.getCell(2), "审核（级别）/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                reviewName = signatureLineForNdtWithLevel(report, project, project.getReviewerNdt(), project.getReviewDateNdt(), "reviewer");
                createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                XWPFTableRow signRow2 = imageTable.createRow();
                setRowHeight(signRow2, 454);
                createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());
                XWPFTableCell approveCell = signRow2.getCell(1);
                createTableCell(approveCell, approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
            }

            // ========== 2.5 如果不是最后一页，添加分页符 ==========
            // if (pageIndex < totalPages - 1) {
            //     document.createParagraph().createRun().addBreak(BreakType.PAGE);
            // }
            document.createParagraph().createRun().addBreak(BreakType.PAGE);
        }
    }

