    private List<JsonNode> collectDefectRows(JsonNode detectionData, boolean supportsRecordOnlyFlag) {
        List<JsonNode> rows = new ArrayList<>();
        if (detectionData != null && detectionData.has("rows") && detectionData.get("rows").isArray()) {
            JsonNode rowsNode = detectionData.get("rows");
            log.debug("Collecting defect rows, total rows in JSON: {}", rowsNode.size());
            for (JsonNode row : rowsNode) {
                if (TableDataMergeUtil.isTrailingSlashPlaceholderRow(row)) {
                    continue;
                }
                if (!isDefectRowEmpty(row, supportsRecordOnlyFlag)) {
                    // 验证字段名是否正确（仅用于调试）
                    String[] expectedFields = {"序号", "起点位置", "终点位置", "长度", "级别", "备注"};
                    boolean hasAllFields = true;
                    for (String field : expectedFields) {
                        if (!row.has(field)) {
                            hasAllFields = false;
                            break;
                        }
                    }
                    if (!hasAllFields) {
                        StringBuilder availableFields = new StringBuilder();
                        row.fieldNames().forEachRemaining(name -> availableFields.append(name).append(", "));
                        log.debug("Defect row missing some expected fields, available fields: {}", 
                            availableFields.length() > 0 ? availableFields.substring(0, availableFields.length() - 2) : "none");
                    }
                    rows.add(row);
                }
            }
            log.debug("Collected {} valid defect rows", rows.size());
        } else {
            log.warn("Detection data is null or missing 'rows' array");
        }
        return rows;
    }

    private boolean isDefectRowEmpty(JsonNode row, boolean supportsRecordOnlyFlag) {
        return !NdtDefectRowUtil.isEffectiveDefectRow(row, supportsRecordOnlyFlag);
    }

    /**
     * 通用报告渲染方法
     */
    private void generateGenericReport(Report report, int reportIndex, XWPFDocument document) throws JsonProcessingException {
        // 简化版本：只显示基本信息，不渲染复杂表格
        addSectionTitle(document, reportIndex + ". " + report.getTitle() + "（简化版本）");
        addParagraph(document, "");
        addParagraph(document, "报告编号：" + brandingReportNumberForDisplay(report));
        addParagraph(document, "检测日期：" + report.getTestDate().format(DateTimeFormatter.ofPattern("yyyy-MM-dd")));
        addParagraph(document, "注意：此报告生成出错。");
        addParagraph(document, "");
        
        // 添加换页符
        document.createParagraph().createRun().addBreak(BreakType.PAGE);
    }

    private void addImageToDocument(XWPFDocument document, String imagePath, String fileName) throws IOException, org.apache.poi.openxml4j.exceptions.InvalidFormatException {
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();

        Path path = Paths.get(imagePath);
        try (WordEmbedImageUtil.PreparedPicture pic = WordEmbedImageUtil.prepare(path, fileName)) {
            run.addPicture(pic.stream(), pic.poiPictureType(), pic.embedFileName(), 300, 225); // 宽度300，高度225
        }
    }

