    /**
     * 创建表格单元格(支持跨列)
     * @param cell 单元格对象
     * @param text 单元格文本
     * @param width 单元格宽度
     * @param align 水平对齐方式
     * @param vertAlign 垂直对齐方式
     * @param colspan 跨列数(1表示不跨列,2表示跨2列,以此类推)
     */
    private void createTableCell(XWPFTableCell cell, String text, int width, 
                                 ParagraphAlignment align, XWPFTableCell.XWPFVertAlign vertAlign, int colspan) {
        // 设置单元格宽度
        CTTcPr tcPr = cell.getCTTc().isSetTcPr() ? cell.getCTTc().getTcPr() : cell.getCTTc().addNewTcPr();
        CTTblWidth cellWidth = tcPr.isSetTcW() ? tcPr.getTcW() : tcPr.addNewTcW();
        cellWidth.setType(STTblWidth.DXA);
        cellWidth.setW(BigInteger.valueOf(width));
        
        // 设置垂直对齐
        cell.setVerticalAlignment(vertAlign);

        // 两端对齐且含换行：每行独立段落，便于 Word 正确两端对齐（保留行首空格缩进）
        boolean bothMultiline = align == ParagraphAlignment.BOTH && text != null && text.contains("\n");
        if (bothMultiline) {
            while (!cell.getParagraphs().isEmpty()) {
                cell.removeParagraph(0);
            }
            for (String line : text.split("\n", -1)) {
                XWPFParagraph p = cell.addParagraph();
                p.setAlignment(ParagraphAlignment.BOTH);
                XWPFRun run = p.createRun();
                run.setFontFamily("宋体");
                run.setFontSize(10.5);
                run.setText(line);
            }
        } else {
            // 使用现有段落，而不是删除重建
            XWPFParagraph para = cell.getParagraphs().isEmpty() ? cell.addParagraph() : cell.getParagraphs().get(0);
            para.setAlignment(align);

            // 清空现有runs
            while (para.getRuns().size() > 0) {
                para.removeRun(0);
            }

            // 设置文本（支持\n换行）
            XWPFRun run = para.createRun();
            run.setFontFamily("宋体");
            run.setFontSize(10.5);

            // 处理换行符
            if (text != null && text.contains("\n")) {
                String[] lines = text.split("\n", -1);
                for (int i = 0; i < lines.length; i++) {
                    if (i > 0) {
                        run.addBreak();  // 换行
                    }
                    run.setText(lines[i]);  // 添加文本
                }
            } else {
                run.setText(text != null ? text : "");
            }
        }
        
        // 设置跨列(如果colspan > 1) - 使用HMerge方式
        if (colspan > 1) {
            XWPFTableRow row = cell.getTableRow();
            List<XWPFTableCell> cells = row.getTableCells();
            int cellIndex = cells.indexOf(cell);
            
            // 设置当前单元格为合并起点
            tcPr.addNewHMerge().setVal(STMerge.RESTART);
            
            // 设置后续单元格为合并延续
            for (int i = 1; i < colspan && (cellIndex + i) < cells.size(); i++) {
                XWPFTableCell mergeCell = cells.get(cellIndex + i);
                CTTcPr mergeTcPr = mergeCell.getCTTc().isSetTcPr() ? 
                    mergeCell.getCTTc().getTcPr() : mergeCell.getCTTc().addNewTcPr();
                mergeTcPr.addNewHMerge().setVal(STMerge.CONTINUE);
            }
        }
    }
    
    /**
     * 创建表格单元格(不跨列的重载方法,保持向后兼容)
     */
    private void createTableCell(XWPFTableCell cell, String text, int width, 
                                 ParagraphAlignment align, XWPFTableCell.XWPFVertAlign vertAlign) {
        createTableCell(cell, text, width, align, vertAlign, 1);  // 默认不跨列
    }

    private void createTableCell(XWPFTableCell cell, String text, int width, int colspan) 
    {
        createTableCell(cell, text, width, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, colspan);  // 默认不跨列
    }

    private void createTableCell(XWPFTableCell cell, String text, int width) 
    {
        createTableCell(cell, text, width, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 1);  // 默认不跨列
    }

    /**
     * 获取不符合标准的记录数据
     * @param report 报告对象
     * @param materialProperty 材质标准数据
     * @return 不符合标准的记录列表，如果没有或出错则返回空列表
     */
    private List<DataComparisonService.NonComplianceRecord> getNonComplianceRecords(
            Report report, Map<String, String> materialProperty) {
        
        if (materialProperty == null || materialProperty.isEmpty()) {
            return new ArrayList<>();
        }
        
        if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
            return new ArrayList<>();
        }
        
        ReportItem firstItem = report.getReportItems().get(0);
        if (firstItem.getTableData() == null || firstItem.getTableData().isEmpty()) {
            return new ArrayList<>();
        }
        
        try {
            // 获取检测类型代码
            String experimentTypeCode = null;
            if (firstItem.getExperimentType() != null) {
                experimentTypeCode = firstItem.getExperimentType().getCode();
            }

            // 里氏硬度检测（LHT，兼容 LHD）单独处理：管件/钢管/焊缝三段范围 + 行内「里氏分类」（见 DataComparisonService.compareLeebWithPipeAndWeldRanges）
            if ("LHT".equalsIgnoreCase(experimentTypeCode) || "LHD".equalsIgnoreCase(experimentTypeCode)) {
                return getLeebNonComplianceRecords(report, materialProperty);
            }

            if ("PMI".equalsIgnoreCase(experimentTypeCode) || "AAT".equalsIgnoreCase(experimentTypeCode)) {
                return aatDataComparisonService.computeNonComplianceRecords(report);
            }

            // 其他检测类型走通用字段映射逻辑
            DataComparisonService.FieldMapping mapping =
                DataComparisonService.getFieldMapping(experimentTypeCode);

            if (mapping == null) {
                log.debug("未找到检测类型 {} 的字段映射配置", experimentTypeCode);
                return new ArrayList<>();
            }

            String mergedJson = mergedTableDataJsonForWord(report);
            if (mergedJson == null) {
                return new ArrayList<>();
            }
            return dataComparisonService.compareData(
                mergedJson,
                materialProperty,
                mapping
            );
            
        } catch (Exception e) {
            log.warn("获取不符合标准记录时出错: {}", e.getMessage());
            return new ArrayList<>();
        }
    }

    /**
     * 里氏硬度（LHD）不符合标准记录：管件 / 钢管 / 焊缝三段范围，行内「里氏分类」优先。
     */
    private List<DataComparisonService.NonComplianceRecord> getLeebNonComplianceRecords(
            Report report, Map<String, String> materialProperty) {

        if (materialProperty == null || materialProperty.isEmpty()) {
            return new ArrayList<>();
        }

        if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
            return new ArrayList<>();
        }

        ReportItem firstItem = report.getReportItems().get(0);
        if (firstItem.getTableData() == null || firstItem.getTableData().isEmpty()) {
            return new ArrayList<>();
        }

        String tableDataJson = mergedTableDataJsonForWord(report);
        if (tableDataJson == null) {
            return new ArrayList<>();
        }

        // 先判断是否为螺栓/螺帽检测：表格中存在“类型”字段且包含“螺栓”或“螺帽”
        boolean hasBoltOrNutType = false;
        try {
            JsonNode rows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
            if (rows != null && rows.isArray()) {
                for (JsonNode row : rows) {
                    String type = getJsonNodeValue(row, "类型", null);
                    if (type != null && (type.contains("螺栓") || type.contains("螺帽"))) {
                        hasBoltOrNutType = true;
                        break;
                    }
                }
            }
        } catch (Exception e) {
            log.warn("解析里氏硬度表格数据时出错: {}", e.getMessage());
        }

        if (hasBoltOrNutType) {
            // 螺栓/螺帽：螺帽范围为螺栓范围 * 0.9
            String boltRange = materialProperty.get("里氏-螺栓");
            if (boltRange == null || boltRange.isEmpty()) {
                boltRange = materialProperty.get("里氏-管件");
                if (boltRange == null || boltRange.isEmpty()) {
                    boltRange = materialProperty.get("里氏-钢管");
                }
                if (boltRange == null || boltRange.isEmpty()) {
                    boltRange = materialProperty.get("里氏");
                }
            }
            return dataComparisonService.compareLeebBoltAndNutRanges(
                    tableDataJson,
                    boltRange,
                    "编号",
                    "平均",
                    "类型",
                    0.9
            );
        } else {
            // 管件 / 焊缝 / 钢管逻辑（焊缝可为母材布氏推算）
            String pipeRange = materialProperty.getOrDefault("里氏-管件", materialProperty.get("里氏"));
            String weldRange = materialPropertyService.resolveLeebWeldRangeForComparison(materialProperty);
            String steelPipeRange = materialProperty.get("里氏-钢管");

            return dataComparisonService.compareLeebWithPipeAndWeldRanges(
                    tableDataJson,
                    pipeRange,
                    weldRange,
                    steelPipeRange,
                    "编号",
                    "平均"
            );
        }
    }

    private String buildNonComplianceSummaryByRange(
            List<DataComparisonService.NonComplianceRecord> nonComplianceRecords,
            boolean groupByItemName) {
        if (nonComplianceRecords == null || nonComplianceRecords.isEmpty()) {
            return "检测结果符合标准要求。";
        }

        Map<String, List<DataComparisonService.NonComplianceRecord>> groupedRecords = groupByItemName
                ? nonComplianceRecords.stream().collect(Collectors.groupingBy(
                r -> {
                    String itemName = r.getItemName();
                    return itemName == null || itemName.trim().isEmpty() ? "未命名项目" : itemName.trim();
                },
                LinkedHashMap::new,
                Collectors.toList()))
                : Collections.singletonMap("", nonComplianceRecords);

        List<String> summaries = new ArrayList<>();
        for (Map.Entry<String, List<DataComparisonService.NonComplianceRecord>> entry : groupedRecords.entrySet()) {
            String singleSummary = buildSingleRangeSummary(entry.getKey(), entry.getValue(), groupByItemName);
            if (!singleSummary.isEmpty()) {
                summaries.add(singleSummary);
            }
        }

        if (summaries.isEmpty()) {
            return "检测结果符合标准要求。";
        }
        return String.join("\n    ", summaries);
    }

    private String buildSingleRangeSummary(
            String groupName,
            List<DataComparisonService.NonComplianceRecord> records,
            boolean includeGroupName) {
        if (records == null || records.isEmpty()) {
            return "";
        }

        String standardRange = records.stream()
                .map(DataComparisonService.NonComplianceRecord::getStandardValue)
                .filter(Objects::nonNull)
                .map(String::trim)
                .filter(s -> !s.isEmpty() && !"/".equals(s))
                .findFirst()
                .orElse("/");

        Set<String> lowerNumbers = new LinkedHashSet<>();
        Set<String> upperNumbers = new LinkedHashSet<>();
        for (DataComparisonService.NonComplianceRecord record : records) {
            int direction = resolveNonComplianceDirection(record);
            String number = record.getNumber();
            if (number == null || number.trim().isEmpty() || "/".equals(number.trim())) {
                continue;
            }
            if (direction < 0) {
                lowerNumbers.add(number.trim());
            } else if (direction > 0) {
                upperNumbers.add(number.trim());
            }
        }

        if (lowerNumbers.isEmpty() && upperNumbers.isEmpty()) {
            return "";
        }

        StringBuilder builder = new StringBuilder();
        if (includeGroupName) {
            builder.append(groupName).append("：");
        }
        builder.append("").append(standardRange).append("");
        if (!lowerNumbers.isEmpty()) {
            builder.append("低于下限编号：").append(sortAndJoinNumbers(new ArrayList<>(lowerNumbers))).append("。");
        }
        if (!upperNumbers.isEmpty()) {
            builder.append("高于上限编号：").append(sortAndJoinNumbers(new ArrayList<>(upperNumbers))).append("。");
        }
        return builder.toString();
    }

    private int resolveNonComplianceDirection(DataComparisonService.NonComplianceRecord record) {
        if (record == null) {
            return 0;
        }
        String result = record.getResult() == null ? "" : record.getResult().trim();
        if (result.contains("低于") || result.contains("小于")) {
            return -1;
        }
        if (result.contains("高于") || result.contains("大于")) {
            return 1;
        }

        double[] bounds = parseRangeBounds(record.getStandardValue());
        Double actual = parseFirstDecimal(record.getActualValue());
        if (bounds != null && actual != null) {
            if (actual < bounds[0]) {
                return -1;
            }
            if (actual > bounds[1]) {
                return 1;
            }
        }
        return 0;
    }

    private double[] parseRangeBounds(String rangeText) {
        if (rangeText == null || rangeText.trim().isEmpty()) {
            return null;
        }
        Matcher matcher = DECIMAL_PATTERN.matcher(rangeText);
        List<Double> values = new ArrayList<>();
        while (matcher.find()) {
            try {
                values.add(Double.parseDouble(matcher.group()));
            } catch (NumberFormatException ignored) {
            }
        }
        if (values.isEmpty()) {
            return null;
        }
        if (values.size() == 1) {
            return new double[]{values.get(0), values.get(0)};
        }
        double first = values.get(0);
        double second = values.get(1);
        return new double[]{Math.min(first, second), Math.max(first, second)};
    }

    private Double parseFirstDecimal(String text) {
        if (text == null || text.trim().isEmpty()) {
            return null;
        }
        Matcher matcher = DECIMAL_PATTERN.matcher(text);
        if (!matcher.find()) {
            return null;
        }
        try {
            return Double.parseDouble(matcher.group());
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private String sortAndJoinNumbers(List<String> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return "/";
        }
        return numbers.stream()
                .filter(Objects::nonNull)
                .map(String::trim)
                .filter(s -> !s.isEmpty() && !"/".equals(s))
                .distinct()
                .sorted(this::compareNumberText)
                .collect(Collectors.joining("、"));
    }

    private int compareNumberText(String left, String right) {
        Integer leftInt = extractFirstInteger(left);
        Integer rightInt = extractFirstInteger(right);
        if (leftInt != null && rightInt != null) {
            int compare = Integer.compare(leftInt, rightInt);
            if (compare != 0) {
                return compare;
            }
        } else if (leftInt != null) {
            return -1;
        } else if (rightInt != null) {
            return 1;
        }
        return left.compareTo(right);
    }

    private Integer extractFirstInteger(String value) {
        if (value == null) {
            return null;
        }
        Matcher matcher = FIRST_INTEGER_PATTERN.matcher(value);
        if (!matcher.find()) {
            return null;
        }
        try {
            return Integer.parseInt(matcher.group(1));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /**
     * 将形如 \"197～241\" 或 \"197-241\" 的范围整体按系数缩放，用于结论文字显示螺帽范围
     */
    private String scaleRangeForDisplay(String rangeStr, double factor) {
        if (rangeStr == null) {
            return null;
        }
        String trimmed = rangeStr.trim();
        if (trimmed.isEmpty()) {
            return null;
        }

        String separator = trimmed.contains("～") ? "～" : (trimmed.contains("-") ? "-" : null);
        if (separator == null) {
            return null;
        }

        String[] parts = trimmed.split(separator);
        if (parts.length != 2) {
            return null;
        }

        try {
            double min = Double.parseDouble(parts[0].trim());
            double max = Double.parseDouble(parts[1].trim());
            double scaledMin = min * factor;
            double scaledMax = max * factor;
            return formatNumberForDisplay(scaledMin) + "～" + formatNumberForDisplay(scaledMax);
        } catch (NumberFormatException e) {
            log.warn("无法缩放里氏硬度范围用于显示: {}", rangeStr);
            return null;
        }
    }

    /**
     * 将数值格式化为字符串，这里统一保留 1 位小数，末尾为 .0 时去掉小数部分
     */
    private String formatNumberForDisplay(double value) {
        String s = String.format(java.util.Locale.ROOT, "%.1f", value);
        if (s.endsWith(".0")) {
            return s.substring(0, s.length() - 2);
        }
        return s;
    }
    
    
    /**
     * 设置表格行高
     */
    private void setRowHeight(XWPFTableRow row, int height) {
        CTTrPr trPr = row.getCtRow().getTrPr();
        if (trPr == null) {
            trPr = row.getCtRow().addNewTrPr();
        }
        CTHeight rowHeight = trPr.getTrHeightList().isEmpty() ? trPr.addNewTrHeight() : trPr.getTrHeightList().get(0);
        rowHeight.setVal(BigInteger.valueOf(height));
        rowHeight.setHRule(STHeightRule.EXACT);
    }

    private void normalizeNewMainTablesToTargetHeight(XWPFDocument document, int fromTableIndex, int targetHeightTwips) {
        if (document == null || fromTableIndex < 0) {
            return;
        }
        List<XWPFTable> tables = document.getTables();
        for (int i = fromTableIndex; i < tables.size(); i++) {
            normalizeMainTableResultOrConclusionRowHeight(tables.get(i), targetHeightTwips);
        }
    }

    private void normalizeMainTableResultOrConclusionRowHeight(XWPFTable table, int targetHeightTwips) {
        if (table == null || table.getRows() == null || table.getRows().isEmpty()) {
            return;
        }
        if (!isCandidateMainTable(table)) {
            return;
        }

        int adjustableRowIndex = findResultOrConclusionRowIndex(table);
        if (adjustableRowIndex < 0) {
            return;
        }

        int currentTotal = 0;
        for (XWPFTableRow row : table.getRows()) {
            currentTotal += currentRowHeightTwips(row);
        }

        XWPFTableRow adjustableRow = table.getRow(adjustableRowIndex);
        int currentAdjustableHeight = currentRowHeightTwips(adjustableRow);
        if (currentAdjustableHeight <= 0) {
            currentAdjustableHeight = MIN_RESULT_OR_CONCLUSION_ROW_HEIGHT_TWIPS;
        }

        int delta = targetHeightTwips - currentTotal;
        int normalizedHeight = currentAdjustableHeight + delta;
        if (normalizedHeight < MIN_RESULT_OR_CONCLUSION_ROW_HEIGHT_TWIPS) {
            normalizedHeight = MIN_RESULT_OR_CONCLUSION_ROW_HEIGHT_TWIPS;
        }
        setRowHeight(adjustableRow, normalizedHeight);
    }

    private boolean isCandidateMainTable(XWPFTable table) {
        if (table.getRows().size() < 4) {
            return false;
        }
        // 「缺陷信息 + 检测结果 + 签批」在同一张表（UT/PAUT 对接焊缝、弯头等）时，若参与统一高度，
        // findResultOrConclusionRowIndex 会把差额全部加在「检测结果」行，出现半页空白（见 normalizeMainTableResultOrConclusionRowHeight）。
        // 标题在 Word 中为带空格的「缺 陷 信 息」，不包含连续子串「缺陷信息」，须单独判断。
        if (tableContainsText(table, "缺陷信息") || tableContainsText(table, "缺 陷 信 息")) {
            return false;
        }
        // 涡流 ET：检测位置 + 检测结果 + 签批独立 contentTable，行高在 generateEddyCurrentReport 内单独控制，
        // 若参与统一高度会把「检测结果」行撑到上万 twips，setRowHeight 无效且易被 Word 拆到下一页。
        if (tableContainsText(table, "检测位置")) {
            return false;
        }
        boolean hasResultOrConclusion = tableContainsText(table, "检测结果")
                || tableContainsText(table, "检测结论");
        boolean hasSignature = tableContainsText(table, "编制") && tableContainsText(table, "批准");
        return hasResultOrConclusion && hasSignature;
    }

    private int findResultOrConclusionRowIndex(XWPFTable table) {
        for (int i = 0; i < table.getRows().size(); i++) {
            XWPFTableRow row = table.getRow(i);
            if (row == null || row.getTableCells() == null) {
                continue;
            }
            for (XWPFTableCell cell : row.getTableCells()) {
                String text = cell != null ? cell.getText() : null;
                if (text == null) {
                    continue;
                }
                if (text.contains("检测结果") || text.contains("检测结论")) {
                    return i;
                }
            }
        }
        return -1;
    }

    private int currentRowHeightTwips(XWPFTableRow row) {
        if (row == null || row.getCtRow() == null || row.getCtRow().getTrPr() == null) {
            return 0;
        }
        CTTrPr trPr = row.getCtRow().getTrPr();
        if (trPr.getTrHeightList() == null || trPr.getTrHeightList().isEmpty()) {
            return 0;
        }
        CTHeight height = trPr.getTrHeightList().get(0);
        if (height == null || height.getVal() == null) {
            return 0;
        }
        Object rawVal = height.getVal();
        if (rawVal instanceof BigInteger) {
            return ((BigInteger) rawVal).intValue();
        }
        try {
            return Integer.parseInt(rawVal.toString());
        } catch (NumberFormatException ex) {
            return 0;
        }
    }

    private boolean tableContainsText(XWPFTable table, String keyword) {
        if (keyword == null || keyword.isEmpty()) {
            return false;
        }
        for (XWPFTableRow row : table.getRows()) {
            if (row == null || row.getTableCells() == null) {
                continue;
            }
            for (XWPFTableCell cell : row.getTableCells()) {
                String text = cell != null ? cell.getText() : null;
                if (text != null && text.contains(keyword)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * 单项报告主表「项目名称」单元格：客户方 + 项目名称（不用于封面 generateCoverPage、概述 generateProjectInfoPage）。
     */
    private String projectNameCellText(Project project) {
        if (project == null) {
            return "/";
        }
        String customer = project.getCustomer() != null ? project.getCustomer().trim() : "";
        if (customer.isEmpty() && project.getCustomerName() != null) {
            customer = project.getCustomerName().trim();
        }
        String name = project.getProjectName() != null ? project.getProjectName().trim() : "";
        if (!customer.isEmpty() && !name.isEmpty()) {
            return customer + " " + name;
        }
        if (!name.isEmpty()) {
            return name;
        }
        if (!customer.isEmpty()) {
            return customer;
        }
        return "/";
    }

    /**
     * 从Report获取字段值(支持Project和Report)
     * 优先从实体字段获取，如果为空则尝试从customFields获取
     */
    private String getFieldValue(Object entity, String fieldName, String defaultValue) {
        try {
            // 首先尝试从实体字段获取
            java.lang.reflect.Field field = entity.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            Object value = field.get(entity);
            if (value != null && !value.toString().isEmpty()) {
                return value.toString();
            }
            
            // 如果实体字段为空，尝试从customFields获取
            if (entity instanceof Report) {
                Report report = (Report) entity;
                if (report.getCustomFields() != null && report.getCustomFields().containsKey(fieldName)) {
                    Object customValue = report.getCustomFields().get(fieldName);
                    if (customValue != null && !customValue.toString().isEmpty()) {
                        return customValue.toString();
                    }
                }
            }
            
            return defaultValue;
        } catch (NoSuchFieldException e) {
            // 如果字段不存在，尝试从customFields获取
            if (entity instanceof Report) {
                Report report = (Report) entity;
                if (report.getCustomFields() != null && report.getCustomFields().containsKey(fieldName)) {
                    Object customValue = report.getCustomFields().get(fieldName);
                    if (customValue != null && !customValue.toString().isEmpty()) {
                        return customValue.toString();
                    }
                }
            }
            return defaultValue;
        } catch (Exception e) {
            log.warn("Error getting field value for {}: {}", fieldName, e.getMessage());
            return defaultValue;
        }
    }

    private int inspectorRowHeight(Report report) {
        String inspector = getFieldValue(report, "inspector", "/");
        return (inspector != null && inspector.trim().length() > 10) ? 540 : 454;
    }

    /**
     * 获取仪器编号
     * 注意：在创建/更新报告时，ReportsController已经将ProjectInstrument的instrumentNumber复制到Report.instrumentNumber字段
     * 所以这里直接使用Report.instrumentNumber即可，不需要再从ProjectInstrument获取
     */
    private String getInstrumentNumber(Report report, String defaultValue) {
        return getFieldValue(report, "instrumentNumber", defaultValue);
    }

    /**
     * 格式化日期字段，如果为空则返回默认值
     */
    private String formatDateField(LocalDate date, String defaultValue) {
        return date != null ? date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd")) : defaultValue;
    }

    /**
     * 格式化人员/日期字段组合
     */
    private String formatPersonDateField(String person, LocalDate date, String defaultValue) {
        String personStr = (person != null && !person.isEmpty()) ? person : defaultValue;
        String dateStr = formatDateField(date, defaultValue);
        return personStr + "/" + dateStr;
    }

    /**
     * 第三方单项签批：当前报告检测类型在 JSON 中的子对象；无配置时返回 null。
     */
    private Map<String, String> thirdPartyApprovalEntry(Project project, Report report) {
        if (project == null || report == null || report.getExperimentTypeId() == null) {
            return null;
        }
        Map<String, Map<String, String>> full = project.getThirdPartyApprovalByExperimentType();
        if (full == null || full.isEmpty()) {
            return null;
        }
        return full.get(String.valueOf(report.getExperimentTypeId()));
    }

    private static String trimToNull(String s) {
        if (s == null) {
            return null;
        }
        String t = s.trim();
        return t.isEmpty() ? null : t;
    }

    private LocalDate parseFlexibleLocalDate(String raw) {
        if (raw == null) {
            return null;
        }
        String s = raw.trim();
        if (s.isEmpty()) {
            return null;
        }
        try {
            if (s.length() >= 10) {
                return LocalDate.parse(s.substring(0, 10));
            }
            return LocalDate.parse(s);
        } catch (Exception e) {
            return null;
        }
    }

    /** 报告对应检测方法编码（已做 LP→PT）；缺失时返回 null */
    private String resolveMethodCodeForSignature(Report report) {
        if (report == null) {
            return null;
        }
        String methodCode = null;
        if (report.getExperimentTypeId() != null) {
            methodCode = experimentTypeRepository.findById(report.getExperimentTypeId())
                    .map(ExperimentType::getCode)
                    .map(code -> code.trim().toUpperCase(Locale.ROOT))
                    .orElse(null);
        } else if (report.getReportItems() != null && !report.getReportItems().isEmpty()
                && report.getReportItems().get(0).getExperimentType() != null
                && report.getReportItems().get(0).getExperimentType().getCode() != null) {
            methodCode = report.getReportItems().get(0).getExperimentType().getCode().trim().toUpperCase(Locale.ROOT);
        }
        if ("LP".equals(methodCode)) {
            methodCode = "PT";
        }
        return methodCode;
    }

    private static boolean isNdtLevelMethodCode(String methodCode) {
        return "MT".equals(methodCode) || "PT".equals(methodCode) || "UT".equals(methodCode)
                || "RT".equals(methodCode) || "ET".equals(methodCode);
    }

    private boolean isNdtLevelMethodForReport(Report report) {
        String code = resolveMethodCodeForSignature(report);
        return code != null && isNdtLevelMethodCode(code);
    }

    private String getStoredNdtLevelFromProject(Project project, String role, String methodCode) {
        if (project == null || role == null || methodCode == null) {
            return null;
        }
        Map<String, Map<String, String>> levels = project.getNdtSignatureLevels();
        if (levels == null) {
            return null;
        }
        Map<String, String> roleMap = levels.get(role);
        if (roleMap == null) {
            return null;
        }
        return ndtQualificationRegistry.normalizeLevel(roleMap.get(methodCode));
    }

    private String formatThirdPartyNdtSignerLine(
            String mapPerson,
            LocalDate mapDate,
            Map<String, String> entry,
            String role,
            Report report,
            Project project
    ) {
        String personStr = (mapPerson != null && !mapPerson.isEmpty()) ? mapPerson : "/";
        String dateStr = formatDateField(mapDate, "/");
        if ("/".equals(personStr)) {
            return personStr + "/" + dateStr;
        }
        String methodCode = resolveMethodCodeForSignature(report);
        if (methodCode == null || !isNdtLevelMethodCode(methodCode)) {
            return personStr + "/" + dateStr;
        }
        String levelKey = "writer".equals(role) ? "writerLevel" : "reviewerLevel";
        String level = ndtQualificationRegistry.normalizeLevel(trimToNull(entry.get(levelKey)));
        if (level == null || level.isBlank()) {
            level = getStoredNdtLevelFromProject(project, role, methodCode);
        }
        if (level == null || level.isBlank()) {
            level = ndtQualificationRegistry.resolveQualifiedLevel(methodCode, personStr);
        }
        if (level == null || level.isBlank()) {
            return personStr + "/" + dateStr;
        }
        return personStr + "(" + level + "级)/" + dateStr;
    }

    /**
     * 单项报告签名区「编制/审核/批准」：润电用入参人员日期；第三方附录且配置了当前检测类型签批信息时用 JSON（无损编写/审核含级别），否则留空。
     */
    private String signatureLineForReport(String person, LocalDate date) {
        return signatureLineForReport(null, null, null, person, date);
    }

    private String signatureLineForReport(Report report, Project project, String role, String person, LocalDate date) {
        if (!Boolean.TRUE.equals(BRANDING_THIRD_PARTY_APPENDIX.get())) {
            return formatPersonDateField(person, date, "/");
        }
        if (report == null || project == null || role == null) {
            return "";
        }
        Map<String, String> entry = thirdPartyApprovalEntry(project, report);
        if (entry == null) {
            return "";
        }
        String mapPerson;
        String mapDateRaw;
        switch (role) {
            case "writer":
                mapPerson = trimToNull(entry.get("writer"));
                mapDateRaw = entry.get("writerDate");
                break;
            case "reviewer":
                mapPerson = trimToNull(entry.get("reviewer"));
                mapDateRaw = entry.get("reviewDate");
                break;
            case "approver":
                mapPerson = trimToNull(entry.get("approver"));
                mapDateRaw = entry.get("approvalDate");
                break;
            default:
                return "";
        }
        LocalDate mapDate = parseFlexibleLocalDate(mapDateRaw);
        if (("writer".equals(role) || "reviewer".equals(role)) && isNdtLevelMethodForReport(report)) {
            return formatThirdPartyNdtSignerLine(mapPerson, mapDate, entry, role, report, project);
        }
        return formatPersonDateField(mapPerson, mapDate, "/");
    }

    private String signatureLineForNdtWithLevel(Report report, Project project, String person, LocalDate date, String role) {
        if (Boolean.TRUE.equals(BRANDING_THIRD_PARTY_APPENDIX.get())) {
            if (report == null || project == null || role == null) {
                return "";
            }
            Map<String, String> entry = thirdPartyApprovalEntry(project, report);
            if (entry == null) {
                return "";
            }
            String mapPerson;
            String mapDateRaw;
            if ("writer".equals(role)) {
                mapPerson = trimToNull(entry.get("writer"));
                mapDateRaw = entry.get("writerDate");
            } else if ("reviewer".equals(role)) {
                mapPerson = trimToNull(entry.get("reviewer"));
                mapDateRaw = entry.get("reviewDate");
            } else {
                return "";
            }
            LocalDate mapDate = parseFlexibleLocalDate(mapDateRaw);
            return formatThirdPartyNdtSignerLine(mapPerson, mapDate, entry, role, report, project);
        }
        String personStr = (person != null && !person.isEmpty()) ? person : "/";
        String dateStr = formatDateField(date, "/");
        if ("/".equals(personStr)) {
            return personStr + "/" + dateStr;
        }
        String level = getNdtSignatureLevelForReport(report, project, role);
        if (level == null || level.isBlank()) {
            return personStr + "/" + dateStr;
        }
        return personStr + "(" + level + "级)/" + dateStr;
    }

    private String getNdtSignatureLevelForReport(Report report, Project project, String role) {
        if (report == null || project == null || role == null) {
            return null;
        }
        String methodCode = resolveMethodCodeForSignature(report);
        if (methodCode == null || !isNdtLevelMethodCode(methodCode)) {
            return null;
        }
        return ndtQualificationRegistry.resolveQualifiedLevel(methodCode, personForRole(project, role));
    }

    private String personForRole(Project project, String role) {
        if ("writer".equals(role)) {
            return project.getWriterNdt();
        }
        if ("reviewer".equals(role)) {
            return project.getReviewerNdt();
        }
        if ("approver".equals(role)) {
            return project.getApproverNdt();
        }
        return null;
    }

    /**
     * 螺栓里氏硬度报告主表「检测部位」解析：
     * 优先从检测内容首行 type 文案中提取端部/腰部；未命中时回退到自定义字段；最终默认腰部。
     */
    private String resolveBoltLeebDetectionLocation(Report report) {
        if (report.getDetectionContent() != null) {
            try {
                String json = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode node = objectMapper.readTree(json);
                if (node.has("rows") && node.get("rows").isArray() && node.get("rows").size() > 0) {
                    JsonNode first = node.get("rows").get(0);
                    String type = first.has("type") ? first.get("type").asText("") : "";
                    if (type.contains("端部")) {
                        return "端部";
                    }
                    if (type.contains("腰部")) {
                        return "腰部";
                    }
                }
            } catch (Exception e) {
                log.warn("Failed to resolve bolt leeb detection location for report {}: {}", report.getId(), e.getMessage());
            }
        }

        String customLocation = getCustomField(report, "检测部位", "");
        if (customLocation != null) {
            String normalized = customLocation.trim();
            if (!normalized.isEmpty() && !"/".equals(normalized)) {
                return normalized;
            }
        }
        return "腰部";
    }

    /**
     * 获取检测类型在固定顺序中的索引（用于排序）；不在列表中则按名称排在最后。
     */
    private int getExperimentTypeOrderIndexFixed(String experimentTypeName) {
        if (experimentTypeName == null) return EXPERIMENT_TYPE_ORDER.size();
        String name = experimentTypeName.trim();
        for (int i = 0; i < EXPERIMENT_TYPE_ORDER.size(); i++) {
            if (EXPERIMENT_TYPE_ORDER.get(i).equals(name)) return i;
        }
        // 库中名称与展示用语不完全一致时的同义归类（顺序判断由长到短、由具体到一般）
        if (name.contains("相控阵")) return 1;
        if (name.contains("测厚")) return 8;
        if ("超声检测".equals(name) || "超声波检测".equals(name)) return 2;
        if (name.contains("磁粉")) return 3;
        if (name.contains("渗透")) return 4;
        if (name.contains("金相")) return 5;
        if (name.contains("里氏") || name.contains("布氏") || name.contains("布什") || name.contains("洛氏") || name.contains("维氏")) {
            return 6;
        }
        if (name.contains("氧化皮")) return 7;
        if (name.contains("合金分析")) return 9;
        if (name.contains("圆度")) return 10;
        if (name.contains("管径")) return 11;
        if (name.contains("内窥镜")) return 12;
        if (name.contains("射线")) return 13;
        if (name.contains("涡流")) return 14;
        if (name.contains("室温拉伸")) return 15;
        if (name.contains("高温拉伸")) return 16;
        if (name.contains("冲击吸收")) return 17;
        if (name.contains("有效硬化层")) return 18;
        if (name.contains("高温持久")) return 19;
        if (name.contains("目视")) return 0;
        if (name.contains("硬度")) return 6;
        return EXPERIMENT_TYPE_ORDER.size();
    }

    /**
     * 概述/总日志排序用：若项目 JSON 含 {@code experimentTypeOrder}，则先按该列表精确匹配下标，否则排在列表之后再用 {@link #getExperimentTypeOrderIndexFixed}。
     */
    private int getExperimentTypeOrderIndex(String experimentTypeName, List<String> customOrder) {
        if (customOrder != null && !customOrder.isEmpty()) {
            if (experimentTypeName == null) {
                return customOrder.size() + EXPERIMENT_TYPE_ORDER.size();
            }
            String name = experimentTypeName.trim();
            for (int i = 0; i < customOrder.size(); i++) {
                String c = customOrder.get(i);
                if (c != null && name.equals(c.trim())) {
                    return i;
                }
            }
            return customOrder.size() + getExperimentTypeOrderIndexFixed(experimentTypeName);
        }
        return getExperimentTypeOrderIndexFixed(experimentTypeName);
    }

    /**
     * 从 {@link Project#getAggregateDetectionLogOrder()} 解析全局检测类型顺序；无或无效则返回 null。
     */
    private List<String> parseExperimentTypeOrderFromProject(Project project) {
        String json = project.getAggregateDetectionLogOrder();
        if (json == null || json.isBlank()) {
            return null;
        }
        try {
            JsonNode root = objectMapper.readTree(json);
            JsonNode arr = root.get("experimentTypeOrder");
            if (arr == null || !arr.isArray() || arr.isEmpty()) {
                return null;
            }
            List<String> out = new ArrayList<>();
            for (JsonNode n : arr) {
                if (n.isTextual()) {
                    String s = n.asText().trim();
                    if (!s.isEmpty()) {
                        out.add(s);
                    }
                }
            }
            return out.isEmpty() ? null : out;
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * 从壁厚字符串中提取数字值
     * 支持格式：10、10mm、10.5、10.5mm等
     * @param wallThicknessStr 壁厚字符串
     * @return 解析后的数值，如果解析失败返回null
     */
    private Double parseWallThickness(String wallThicknessStr) {
        if (wallThicknessStr == null || wallThicknessStr.trim().isEmpty()) {
            return null;
        }
        try {
            // 移除所有非数字和小数点的字符
            String cleaned = wallThicknessStr.replaceAll("[^0-9.]", "");
            if (cleaned.isEmpty()) {
                return null;
            }
            return Double.parseDouble(cleaned);
        } catch (NumberFormatException e) {
            log.warn("Failed to parse wall thickness: {}", wallThicknessStr);
            return null;
        }
    }

    /**
     * 从管径字符串中提取数字值（支持 60、60mm、Φ60 等格式，判断时不带单位）
     */
    private Double parsePipeDiameter(String pipeDiameterStr) {
        if (pipeDiameterStr == null || pipeDiameterStr.trim().isEmpty()) {
            return null;
        }
        try {
            String cleaned = pipeDiameterStr.replaceAll("[^0-9.]", "");
            if (cleaned.isEmpty()) {
                return null;
            }
            return Double.parseDouble(cleaned);
        } catch (NumberFormatException e) {
            log.warn("Failed to parse pipe diameter: {}", pipeDiameterStr);
            return null;
        }
    }

    /**
     * 对接焊缝试块型号：根据部件管径、壁厚查表（数值判断不带单位）。
     * 管径 PD、壁厚 WT；无部件或解析失败时返回 null，调用方用 "/" 或自定义字段兜底。
     */
    private String getTestBlockModelByPipeDiameterAndWallThickness(Double pd, Double wt) {
        if (pd == null || wt == null) {
            return null;
        }
        if (pd > 500) {
            if (wt >= 6 && wt <= 25) return "CSKⅠA、CSKⅡA-1";
            if (wt > 25 && wt <= 40) return "CSKⅠA、CSKⅡA-1";
            if (wt > 40 && wt <= 100) return "CSKⅠA、CSKⅡA-2";
            if (wt > 100) return "CSKⅠA、CSKⅡA-3";
            return null;
        }
        if (pd >= 160 && pd <= 500) {
            if (wt >= 6 && wt <= 10) return "CSKⅠA、CSKⅡA-1、RB-C-1";
            if (wt > 10 && wt <= 16) return "CSKⅠA、CSKⅡA-1、RB-C-2";
            if (wt > 16 && wt <= 24) return "CSKⅠA、CSKⅡA-1、RB-C-3";
            if (wt > 24 && wt <= 25) return "CSKⅠA、CSKⅡA-1、RB-C-4";
            if (wt > 25 && wt <= 36) return "CSKⅠA、CSKⅡA-1、RB-C-4";
            if (wt > 36 && wt <= 40) return "CSKⅠA、CSKⅡA-1、RB-C-5";
            if (wt > 40 && wt <= 50) return "CSKⅠA、CSKⅡA-2、RB-C-5";
            if (wt > 50 && wt <= 100) return "CSKⅠA、CSKⅡA-2、RB-C";
            if (wt > 100 && wt <= 200) return "CSKⅠA、CSKⅡA-3、RB-C";
            return null;
        }
        if (pd < 160) {
            if (wt >= 4 && wt <= 8) {
                if (pd >= 32 && pd <= 48) return "GS-1";
                if (pd > 48 && pd <= 72) return "GS-2";
                if (pd > 72 && pd <= 110) return "GS-3";
                if (pd > 110 && pd <= 159) return "GS-4";
            }
            if (wt > 8 && wt <= 15) {
                if (pd >= 32 && pd <= 48) return "GS-1";
                if (pd > 48 && pd <= 72) return "GS-2";
                if (pd > 72 && pd <= 110) return "GS-3";
                if (pd > 110 && pd <= 159) return "GS-4";
            }
            if (wt > 15 && wt <= 50) {
                if (pd >= 32 && pd <= 48) return "GS-1";
                if (pd > 48 && pd <= 72) return "GS-2";
                if (pd > 72 && pd <= 110) return "GS-3";
                if (pd > 110 && pd <= 159) return "GS-4";
            }
        }
        return null;
    }

    /** 对接焊缝 UT 双探头查表结果（K、晶片尺寸、前沿、频率）。 */
    private static final class ButtWeldProbeParams {
        final String k1;
        final String crystalSize1;
        final String front1;
        final String freq1;
        final String k2;
        final String crystalSize2;
        final String front2;
        final String freq2;

        ButtWeldProbeParams(String k1, String crystalSize1, String front1, String freq1,
                            String k2, String crystalSize2, String front2, String freq2) {
            this.k1 = k1;
            this.crystalSize1 = crystalSize1;
            this.front1 = front1;
            this.freq1 = freq1;
            this.k2 = k2;
            this.crystalSize2 = crystalSize2;
            this.front2 = front2;
            this.freq2 = freq2;
        }
    }

    private static ButtWeldProbeParams buttWeldProbeParams(
            String k1, String crystalSize1, String front1, String freq1,
            String k2, String crystalSize2, String front2, String freq2) {
        return new ButtWeldProbeParams(k1, crystalSize1, front1, freq1, k2, crystalSize2, front2, freq2);
    }

    /** 对接焊缝 UT：按管径 pd、壁厚 wt 查双探头参数；无法匹配时返回 null。 */
    private ButtWeldProbeParams getButtWeldProbeParams(Double pd, Double wt) {
        if (pd == null || wt == null) {
            return null;
        }
        if (pd > 500) {
            if (wt >= 6 && wt <= 25) {
                return buttWeldProbeParams("1.51", "9mm×9mm", "10mm", "5",
                    "3.01", "9mm×9mm", "11mm", "5");
            }
            if (wt > 25 && wt <= 40) {
                return buttWeldProbeParams("1.51", "13mm×13mm", "12mm", "2.5",
                    "2.51", "13mm×13mm", "13mm", "2.5");
            }
            if (wt > 40 && wt <= 100) {
                return buttWeldProbeParams("1.01", "13mm×13mm", "12mm", "2.5",
                    "2.01", "13mm×13mm", "12mm", "2.5");
            }
            if (wt > 100) {
                return buttWeldProbeParams("1.01", "13mm×13mm", "12mm", "2.5",
                    "2.01", "13mm×13mm", "12mm", "2.5");
            }
            return null;
        }
        if (pd >= 160 && pd <= 500) {
            if (wt >= 6 && wt <= 25) {
                return buttWeldProbeParams("1.51", "9mm×9mm", "10mm", "5",
                    "3.01", "9mm×9mm", "11mm", "5");
            }
            if (wt > 25 && wt <= 36) {
                return buttWeldProbeParams("1.51", "13mm×13mm", "12mm", "2.5",
                    "2.51", "13mm×13mm", "13mm", "2.5");
            }
            if (wt > 36 && wt <= 40) {
                return buttWeldProbeParams("1.51", "13mm×13mm", "12mm", "2.5",
                    "2.51", "13mm×13mm", "13mm", "2.5");
            }
            if (wt > 40 && wt <= 50) {
                return buttWeldProbeParams("1.01", "13mm×13mm", "12mm", "2.5",
                    "2.01", "13mm×13mm", "12mm", "2.5");
            }
            if (wt > 50 && wt <= 100) {
                return buttWeldProbeParams("1.01", "13mm×13mm", "12mm", "2.5",
                    "2.01", "13mm×13mm", "12mm", "2.5");
            }
            if (wt > 100 && wt <= 200) {
                return buttWeldProbeParams("1.01", "13mm×13mm", "12mm", "2.5",
                    "2.01", "13mm×13mm", "12mm", "2.5");
            }
            return null;
        }
        if (pd >= 32 && pd <= 159) {
            if (wt >= 4 && wt <= 8) {
                return buttWeldProbeParams("2.51", "6mm×6mm", "5.1mm", "5",
                    "3.03", "6mm×6mm", "5.2mm", "5");
            }
            if (wt > 8 && wt <= 15) {
                return buttWeldProbeParams("2.02", "6mm×6mm", "5.1mm", "5",
                    "2.51", "6mm×6mm", "5.2mm", "5");
            }
            if (wt > 15 && wt <= 50) {
                return buttWeldProbeParams("1.51", "9mm×9mm", "8.1mm", "2.5",
                    "2.02", "9mm×9mm", "9.0mm", "2.5");
            }
        }
        return null;
    }

    /** 将表内晶片尺寸（如 9mm×9mm）格式化为报告用 9×9mm。 */
    private static String formatButtWeldCrystalSize(String sizeMm) {
        if (sizeMm == null || sizeMm.isEmpty()) {
            return "";
        }
        return sizeMm.replace("mm×", "×");
    }

    private static String formatButtWeldProbeParamLine(int probeIndex, ButtWeldProbeParams params) {
        if (params == null) {
            return "";
        }
        if (probeIndex == 1) {
            return "1号探头(" + params.freq1 + "MHz 晶片 " + formatButtWeldCrystalSize(params.crystalSize1)
                + " 前沿 " + params.front1 + " k值 " + params.k1 + ")";
        }
        return "2号探头(" + params.freq2 + "MHz 晶片 " + formatButtWeldCrystalSize(params.crystalSize2)
            + " 前沿 " + params.front2 + " k值 " + params.k2 + ")";
    }

    /**
     * 对接焊缝探头频率（MHz）：根据部件壁厚，6～40 填 5，＞40 填 2.5，其他默认 5。用于 1 号、2 号探头参数。
     */
    private String getProbeFrequencyMhzForReport(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return "5";
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return "5";
        }
        Double wt = parseWallThickness(component.getWallThickness());
        if (wt != null && wt > 40) {
            return "2.5";
        }
        return "5";
    }

    /**
     * 弯头/弯管试块型号：仅按壁厚判断，20～50mm→SW-I，50～160mm→SW-Ⅱ；其他情况返回 null。
     */
    private String getElbowTestBlockModelForReport(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return null;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return null;
        }
        Double wt = parseWallThickness(component.getWallThickness());
        if (wt == null) {
            return null;
        }
        if (wt >= 20 && wt <= 50) {
            return "SW-I";
        }
        if (wt > 50 && wt <= 160) {
            return "SW-Ⅱ";
        }
        return null;
    }

    /**
     * 角焊缝试块型号：按壁厚映射 CSK-ⅡA-1/2/3（6～40→1，40～100→2，100～200→3），否则返回 null。
     */
    private String getFilletTestBlockModelForReport(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return null;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return null;
        }
        Double wt = parseWallThickness(component.getWallThickness());
        if (wt == null) {
            return null;
        }
        if (wt >= 6 && wt <= 40) {
            return "CSK-ⅡA-1";
        }
        if (wt > 40 && wt <= 100) {
            return "CSK-ⅡA-2";
        }
        if (wt > 100 && wt <= 200) {
            return "CSK-ⅡA-3";
        }
        return null;
    }

    /**
     * 角焊缝检测灵敏度：基于壁厚将 14/20dB 分别映射为 (18/24)、(14/20)、(10/16)，并附“横向缺陷扫查增益6dB”说明。
     */
    private String getSensitivityTextForFilletWeld(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return null;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return null;
        }
        Double wt = parseWallThickness(component.getWallThickness());
        if (wt == null) {
            return null;
        }

        Integer firstDb = null;
        Integer secondDb = null;

        if (wt >= 6 && wt <= 40) {
            firstDb = 18;
            secondDb = 24;
        } else if (wt > 40 && wt <= 100) {
            firstDb = 14;
            secondDb = 20;
        } else if (wt > 100 && wt <= 200) {
            firstDb = 10;
            secondDb = 16;
        }

        if (firstDb == null || secondDb == null) {
            return null;
        }
        return "φ2mm-" + firstDb + "dB φ2mm-" + secondDb + "dB（横向缺陷扫查增益6dB）";
    }

    /**
     * 螺栓：检测内容说明区域，检测内容描述参考对接焊缝超声的生成逻辑。
     */
    private void addUTBoltDescriptionAndResult(XWPFDocument document, Report report, Project project) throws Exception {
        // 复用对接焊缝的检测内容拼接逻辑，生成螺栓检测内容说明
        ExperimentType expType = report.getExperimentTypeId() != null
            ? experimentTypeRepository.findById(report.getExperimentTypeId()).orElse(null)
            : (report.getReportItems() != null && !report.getReportItems().isEmpty()
                ? report.getReportItems().get(0).getExperimentType() : null);
        String body = utDetectionContentNarrativeBody(report, expType);
        String detectionContent = body.isEmpty() ? "检测内容：" : "检查内容 \n  " + body;
        detectionContent = appendUtStyleFigureSuffix(detectionContent, report);

        XWPFTable descTable = document.createTable(1, 1);
        setupTableProperties(descTable, PT_TABLE_WIDTH);
        XWPFTableRow descRow = descTable.getRow(0);
        setRowHeight(descRow, 1605+454*3);
        createTableCell(descRow.getCell(0), detectionContent, PT_TABLE_WIDTH,
            ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 1);
    }

    /**
     * 对接焊缝：根据管径/壁厚自动计算 1、2 号探头默认“检测灵敏度”文案；
     * 返回类似 “φ2mm-18dB φ2mm-24dB”，无法匹配规则时返回 null。
     */
    private String getSensitivityTextForButtWeld(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return null;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return null;
        }
        Double pd = parsePipeDiameter(component.getPipeDiameter());
        Double wt = parseWallThickness(component.getWallThickness());
        if (pd == null || wt == null) {
            return null;
        }

        Integer firstDb = null;
        Integer secondDb = null;

        if (pd >= 160) {
            // 管径 ≥ 160 时的规则
            if (wt >= 6 && wt <= 40) {
                firstDb = 18;
                secondDb = 24;
            } else if (wt > 40 && wt <= 100) {
                firstDb = 14;
                secondDb = 20;
            } else if (wt > 100 && wt <= 200) {
                firstDb = 10;
                secondDb = 16;
            }
        } else {
            // 管径 < 160 时的规则
            if (wt >= 4 && wt < 6) {
                firstDb = 20;
                secondDb = 26;
            } else if (wt >= 6 && wt <= 40) {
                firstDb = 18;
                secondDb = 24;
            } else if (wt > 40 && wt <= 50) {
                firstDb = 14;
                secondDb = 20;
            }
        }

        if (firstDb == null || secondDb == null) {
            return null;
        }
        return "φ2mm-" + firstDb + "dB φ2mm-" + secondDb + "dB";
    }

    /**
     * 根据报告关联的检测部件（管径、壁厚）计算试块型号；无部件或无法解析时返回 null。
     */
    private String getTestBlockModelForReport(Report report) {
        if (report == null || resolveComponentForReport(report) == null) {
            return null;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null) {
            return null;
        }
        Double pd = parsePipeDiameter(component.getPipeDiameter());
        Double wt = parseWallThickness(component.getWallThickness());
        return getTestBlockModelByPipeDiameterAndWallThickness(pd, wt);
    }

    /**
     * 统一设备类别生成逻辑：
     * - 如果关联的检测部件存在，优先根据 ProjectComponent.category 映射：
     *   汽机 -> 汽机；锅炉本体 -> 锅炉；四大管道/机炉外管道 -> 压力管道；钢结构 -> 钢结构；其他 -> 其他；
     *   自定义类别（非上列标准名）原样返回，与概述节标题一致。
     * - 否则回退到原有的 report.equipmentCategory 字段。
     */
    private String getEquipmentCategoryForReport(Report report) {
        String fallback = getFieldValue(report, "equipmentCategory", "/");
        if (report == null || resolveComponentForReport(report) == null) {
            return fallback;
        }
        ProjectComponent component = resolveComponentForReport(report);
        if (component == null || component.getCategory() == null || component.getCategory().trim().isEmpty()) {
            return fallback;
        }
        String category = component.getCategory().trim();
        switch (category) {
            case "汽机":
                return "汽机";
            case "锅炉本体":
                return "锅炉";
            case "四大管道":
            case "机炉外管道":
                return "压力管道";
            case "钢结构":
                return "钢结构";
            case "其他":
                return "其他";
            default:
                return category;
        }
    }

    /**
     * 从customFields获取字段值(支持Project和Report)
     */
    /**
     * 从JsonNode中获取字段值
     */
    private String getJsonNodeValue(JsonNode node, String fieldName, String defaultValue) {
        if (node == null || !node.has(fieldName)) {
            return defaultValue;
        }
        JsonNode fieldNode = node.get(fieldName);
        if (fieldNode.isNull()) {
            return defaultValue;
        }
        return fieldNode.asText();
    }

    private String getCustomField(Object entity, String key, String defaultValue) {
        try {
            java.lang.reflect.Field field = entity.getClass().getDeclaredField("customFields");
            field.setAccessible(true);
            @SuppressWarnings("unchecked")
            java.util.Map<String, Object> customFields = (java.util.Map<String, Object>) field.get(entity);
            if (customFields != null && customFields.containsKey(key)) {
                Object value = customFields.get(key);
                return value != null ? value.toString() : defaultValue;
            }
        } catch (Exception e) {
            // Field might not exist or is null
        }
        return defaultValue;
    }

    /**
     * 检测内容行是否显式包含部件表字段「名称」或「规格」（或英文 name/spec），用于区分
     * “真正的部件明细行”与仅含 type/total/locationDesc 的检测内容行
     */
    private boolean detectionRowHasExplicitNameOrSpec(JsonNode row) {
        if (row == null || !row.isObject()) {
            return false;
        }
        String[] keys = {"名称", "规格", "name", "spec"};
        for (String k : keys) {
            if (row.has(k) && !row.get(k).isNull()) {
                String v = row.get(k).asText("").trim();
                if (!v.isEmpty() && !"/".equals(v)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * 检测内容 table 行是否含可用于螺栓里氏「部件情况表」的字段（与 auto-fill 的 locationNumber/total 等对齐）。
     * 全空模板行不视为有效，避免覆盖下方多部件回退。
     */
    private boolean detectionContentRowHasBoltComponentTableHint(JsonNode row) {
        if (row == null || !row.isObject()) {
            return false;
        }
        String[] keys = {"type", "locationNumber", "total", "locationDesc", "名称", "规格", "name", "spec"};
        for (String k : keys) {
            if (row.has(k) && !row.get(k).isNull()) {
                String v = row.get(k).asText("").trim();
                if (!v.isEmpty() && !"/".equals(v)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean detectionContentHasAnyBoltComponentTableHint(JsonNode rowsArray) {
        if (rowsArray == null || !rowsArray.isArray()) {
            return false;
        }
        for (JsonNode rawRow : rowsArray) {
            if (detectionContentRowHasBoltComponentTableHint(rawRow)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 部件情况表第 rowIndex 行：行内 projectComponentId 优先，否则 projectComponentIds[rowIndex]，再回退首个部件。
     */
    private ProjectComponent componentForProjectDetailRow(Report report, List<ProjectComponent> comps, int rowIndex) {
        return detectionContentRowComponentResolver.resolve(report, comps, rowIndex);
    }

    /**
     * 将检测内容行（可能含 type/locationDesc/locationNumber/total）标准化为部件情况表行（名称、规格、材质、数量、编号）。
     * 名称以部件名为准，不用检测内容里的 type（多为检测类别）；规格/材质优先按行对齐的单个部件，避免多部件合并串。
     */
    private ObjectNode normalizeComponentDetailRow(JsonNode row, Report report, List<ProjectComponent> comps, int rowIndex) {
        ProjectComponent rowComponent = detectionContentRowComponentResolver.resolve(report, comps, rowIndex, row);
        ProjectComponent firstComponent = reportComponentMergeHelper.firstOrNull(comps);
        ObjectNode out = objectMapper.createObjectNode();
        // 名称：显式字段 -> 本行对应部件名 -> 报告部件名 -> 首个部件名（不用 row.type，避免「螺栓」等检测类型盖住部件名）
        String name = getJsonNodeValue(row, "名称", null);
        if (name == null || name.isEmpty() || "/".equals(name)) {
            if (rowComponent != null && rowComponent.getComponentName() != null && !rowComponent.getComponentName().isBlank()) {
                name = rowComponent.getComponentName();
            }
        }
        if (name == null || name.isEmpty() || "/".equals(name)) {
            name = getFieldValue(report, "componentName", null);
        }
        if (name == null || name.isEmpty() || "/".equals(name)) {
            name = (firstComponent != null && firstComponent.getComponentName() != null && !firstComponent.getComponentName().isEmpty())
                ? firstComponent.getComponentName() : null;
        }
        out.put("名称", name != null && !name.isEmpty() ? name : "/");

        // 规格：显式 -> 本行对应部件单件规格 -> 报告字段（不用多部件 merge 合集）
        String spec = getJsonNodeValue(row, "规格", null);
        if (spec == null || spec.isEmpty() || "/".equals(spec)) {
            spec = "/";
            if (rowComponent != null) {
                String one = reportComponentMergeHelper.formatSpecUnified(rowComponent);
                if (one != null && !one.isEmpty()) {
                    spec = one;
                }
            }
            if ("/".equals(spec)) {
                spec = getFieldValue(report, "componentSpec", "/");
            }
        }
        out.put("规格", spec);

        // 材质：显式 -> 本行对应部件材质 -> 多部件合并 -> custom
        String material = getJsonNodeValue(row, "材质", null);
        if (material == null || material.isEmpty() || "/".equals(material)) {
            if (rowComponent != null && rowComponent.getMaterial() != null && !rowComponent.getMaterial().isBlank()) {
                material = rowComponent.getMaterial();
            } else {
                String mergedMat = reportComponentMergeHelper.mergeMaterials(comps);
                if (mergedMat != null && !mergedMat.isEmpty()) {
                    material = mergedMat;
                } else {
                    material = getCustomField(report, "部件材质", "/");
                }
            }
        }
        out.put("材质", material != null ? material : "/");

        // 数量：row.数量 -> row.total（检测内容「总计」，与 DetectionContentAutoFillService 各块行数一致）-> "1"
        String qty = getJsonNodeValue(row, "数量", null);
        if (qty == null || qty.isEmpty() || "/".equals(qty)) {
            qty = getJsonNodeValue(row, "total", null);
        }
        if (qty == null || qty.isEmpty() || "/".equals(qty)) {
            qty = "1";
        }
        out.put("数量", qty);

        // 编号：row.编号 -> row.locationNumber -> rowIndex+1
        String num = getJsonNodeValue(row, "编号", null);
        if (num == null || num.isEmpty() || "/".equals(num)) {
            num = getJsonNodeValue(row, "locationNumber", null);
        }
        if (num == null || num.isEmpty() || "/".equals(num)) {
            num = String.valueOf(rowIndex + 1);
        }
        out.put("编号", num);
        return out;
    }

