    // gpt修改后
    /** 编号类字段压缩展示（纯数字与 W1-R1-1 等形式），与 {@link LocationNumberCompressor} 一致。 */
    private String formatNumberRange(String numberValue) {
        if (numberValue == null || numberValue.isEmpty() || "/".equals(numberValue.trim())) {
            return "/";
        }
        String[] tokens = numberValue.split("[，,\\s;]+");
        List<String> list = new ArrayList<>();
        for (String t : tokens) {
            if (t != null && !t.trim().isEmpty()) {
                list.add(t.trim());
            }
        }
        if (list.isEmpty()) {
            return "/";
        }
        return LocationNumberCompressor.compressJoined(list);
    }

    /**
     * 螺栓里氏硬度报告「部件情况-编号」汇总：
     * 优先使用检测结果表 rows 中的「编号」列（用户录入值），
     * 未取到时回退到部件明细行中的「编号」字段。
     */
    private String resolveBoltNumberRangeForBoltLeebReport(Report report, List<JsonNode> projectDetailRows) {
        List<String> numberTokens = new ArrayList<>();

        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            String num = getJsonNodeValue(row, "编号", "").trim();
                            if (num.isEmpty() || "/".equals(num)) {
                                num = getJsonNodeValue(row, "number", "").trim();
                            }
                            if (!num.isEmpty() && !"/".equals(num)) {
                                numberTokens.add(num);
                            }
                        }
                    }
                } catch (Exception e) {
                    log.warn("Failed to parse bolt number from tableData for report {}: {}", report.getId(), e.getMessage());
                }
            }
        }

        if (numberTokens.isEmpty() && projectDetailRows != null && !projectDetailRows.isEmpty()) {
            for (JsonNode row : projectDetailRows) {
                String num = getJsonNodeValue(row, "编号", "").trim();
                if (!num.isEmpty() && !"/".equals(num)) {
                    numberTokens.add(num);
                }
            }
        }

        if (numberTokens.isEmpty()) {
            return null;
        }
        return formatNumberRange(String.join("，", numberTokens));
    }
    /** tableData 仅含合并后 rows 的 JSON 字符串，供理化对比等 */
    private String mergedTableDataJsonForWord(Report report) {
        if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
            return null;
        }
        String td = report.getReportItems().get(0).getTableData();
        if (td == null || td.trim().isEmpty()) {
            return null;
        }
        try {
            return objectMapper.writeValueAsString(TableDataMergeUtil.tableDataWithMergedRowsOnly(td, objectMapper));
        } catch (Exception e) {
            return td;
        }
    }

    /**
     * 从ReportItem获取检测数据
     */
    private JsonNode getDetectionDataFromReport(Report report) {
        try {
            if (report.getReportItems() == null || report.getReportItems().isEmpty()) {
                log.warn("Report {} has no report items", report.getId());
                return null;
            }
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() == null || firstItem.getTableData().isEmpty()) {
                log.warn("ReportItem {} has empty tableData", firstItem.getId());
                return null;
            }
            com.fasterxml.jackson.databind.node.ObjectNode result = objectMapper.createObjectNode();
            String tableData = firstItem.getTableData();
            if (isUtMultiRowActive()) {
                List<JsonNode> blocks = TableDataMergeUtil.perContentRowBlocks(tableData, objectMapper);
                if (!blocks.isEmpty()) {
                    int rowIdx = currentUtDetectionContentRowIndex();
                    if (rowIdx >= 0 && rowIdx < blocks.size()) {
                        JsonNode block = blocks.get(rowIdx);
                        if (block != null && block.has("rows") && block.get("rows").isArray()) {
                            result.set("rows", block.get("rows"));
                            log.debug("UT multi-row detection data for report {}, block {} rows: {}",
                                    report.getId(), rowIdx, block.get("rows").size());
                            return result;
                        }
                    }
                    result.set("rows", objectMapper.createArrayNode());
                    return result;
                }
            }
            result.set("rows", TableDataMergeUtil.mergedRowsFromTableDataJson(tableData, objectMapper));
            log.debug("Successfully parsed detection data for report {}, merged rows: {}",
                    report.getId(), result.get("rows").size());
            return result;
        } catch (Exception e) {
            log.error("Unexpected error reading detection data for report {}: {}", report.getId(), e.getMessage(), e);
            return null;
        }
    }

    /**
     * 从图片URL提取图片ID
     */
    private Integer extractImageIdFromUrl(String url) {
        try {
            if (url == null || url.isEmpty()) return null;
            String[] parts = url.split("/");
            return Integer.parseInt(parts[parts.length - 1]);
        } catch (Exception e) {
            log.warn("Failed to extract image ID from URL: {}", url);
            return null;
        }
    }

    /**
     * 根据文件名获取图片类型
     */
    private int getPictureType(String fileName) {
        String extension = fileName.substring(fileName.lastIndexOf('.') + 1).toLowerCase();
        switch (extension) {
            case "png": return XWPFDocument.PICTURE_TYPE_PNG;
            case "jpg":
            case "jpeg": return XWPFDocument.PICTURE_TYPE_JPEG;
            case "gif": return XWPFDocument.PICTURE_TYPE_GIF;
            case "bmp": return XWPFDocument.PICTURE_TYPE_BMP;
            default: return XWPFDocument.PICTURE_TYPE_JPEG;
        }
    }

    /**
     * 设置段落固定行间距
     * @param paragraph 段落对象
     * @param lineSpacingPoints 行间距（磅）
     */
    private void setExactLineSpacing(XWPFParagraph paragraph, double lineSpacingPoints) {
        CTPPr ppr = paragraph.getCTP().getPPr();
        if (ppr == null) {
            ppr = paragraph.getCTP().addNewPPr();
        }
        CTSpacing spacing = ppr.isSetSpacing() ? ppr.getSpacing() : ppr.addNewSpacing();
        spacing.setLine(BigInteger.valueOf((long)(lineSpacingPoints * 20)));  // 磅转twips
        spacing.setLineRule(STLineSpacingRule.EXACT);
    }

    /**
     * 设置表格属性(宽度、边框、布局)
     */
    private void setupTableProperties(XWPFTable table, int width) {
        CTTblPr tblPr = table.getCTTbl().getTblPr();
        if (tblPr == null) {
            tblPr = table.getCTTbl().addNewTblPr();
        }
        
        // 设置表格宽度
        CTTblWidth tblWidth = tblPr.isSetTblW() ? tblPr.getTblW() : tblPr.addNewTblW();
        tblWidth.setType(STTblWidth.DXA);
        tblWidth.setW(BigInteger.valueOf(width));
        
        // 设置表格边框
        CTTblBorders borders = tblPr.isSetTblBorders() ? tblPr.getTblBorders() : tblPr.addNewTblBorders();
        setBorder(borders.addNewTop(), STBorder.SINGLE, 6);
        setBorder(borders.addNewBottom(), STBorder.SINGLE, 6);
        setBorder(borders.addNewLeft(), STBorder.SINGLE, 6);
        setBorder(borders.addNewRight(), STBorder.SINGLE, 6);
        setBorder(borders.addNewInsideH(), STBorder.SINGLE, 6);
        setBorder(borders.addNewInsideV(), STBorder.SINGLE, 6);
        
        // 设置固定列宽布局
        CTTblLayoutType layoutType = tblPr.isSetTblLayout() ? tblPr.getTblLayout() : tblPr.addNewTblLayout();
        layoutType.setType(STTblLayoutType.FIXED);
    }

    /**
     * 从JsonNode获取字段值
     */
    private String getJsonValue(JsonNode node, String fieldName, String defaultValue) {
        if (node != null && node.has(fieldName) && !node.get(fieldName).isNull()) {
            String value = node.get(fieldName).asText();
            return value != null && !value.isEmpty() ? value : defaultValue;
        }
        return defaultValue;
    }

    private String getDefectNumberValue(JsonNode defectRow) {
        return getJsonValue(defectRow, "编号", getJsonValue(defectRow, "序号", "/"));
    }

    /**
     * 金相检测 dual-textarea：浸蚀剂；未填写时默认 {@link #MET_DEFAULT_ETCHANT}。
     */
    private String getMetEtchant(Report report) {
        if (report.getDetectionContent() == null) {
            return MET_DEFAULT_ETCHANT;
        }
        try {
            String detectionContentJson = objectMapper.writeValueAsString(report.getDetectionContent());
            JsonNode detectionContentNode = objectMapper.readTree(detectionContentJson);
            if (detectionContentNode.has("etchant") && !detectionContentNode.get("etchant").isNull()) {
                String etchant = detectionContentNode.get("etchant").asText("").trim();
                if (!etchant.isEmpty() && !"/".equals(etchant) && !"／".equals(etchant)) {
                    return etchant;
                }
            }
        } catch (Exception e) {
            log.warn("Failed to parse etchant from detectionContent for report {}: {}", report.getId(), e.getMessage());
        }
        return MET_DEFAULT_ETCHANT;
    }

    /**
     * 从detectionContent获取检测结论（金相检测使用dual-textarea模式）
     */
    private String getDetectionConclusion(Report report) {
        try {
            if (report.getDetectionContent() != null) {
                String detectionContentJson = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode detectionContentNode = objectMapper.readTree(detectionContentJson);
                if (detectionContentNode.has("conclusion")) {
                    String conclusion = detectionContentNode.get("conclusion").asText();
                    return conclusion != null && !conclusion.isEmpty() ? conclusion : "/";
                }
            }
        } catch (Exception e) {
            log.warn("Failed to parse detectionContent for report {}: {}", report.getId(), e.getMessage());
        }
        return "/";
    }


