    /**
     * 中文序号「一、二、三…」（用于目视检测结果位置分组标题，支持 1–99）。
     */
    private static String chineseSectionOrdinalForVis(int n) {
        if (n <= 0) {
            return Integer.toString(n);
        }
        String[] d = {"", "一", "二", "三", "四", "五", "六", "七", "八", "九"};
        if (n <= 10) {
            return d[n];
        }
        if (n < 20) {
            return "十" + d[n - 10];
        }
        if (n < 100) {
            int tens = n / 10;
            int ones = n % 10;
            return d[tens] + "十" + (ones == 0 ? "" : d[ones]);
        }
        return Integer.toString(n);
    }

    /** 解析图片存储路径（支持相对 {@code uploadDir}）。 */
    private Path resolveStoredImagePathForWord(Image image) {
        if (image == null || image.getStoragePath() == null || image.getStoragePath().isBlank()) {
            return null;
        }
        String sp = image.getStoragePath().trim();
        Path p = Paths.get(sp);
        if (Files.exists(p)) {
            return p;
        }
        return Paths.get(uploadDir).resolve(sp).normalize();
    }

    private void addVisCenteredPictureFromFile(XWPFDocument document, Path filePath, String fileName) throws Exception {
        if (filePath == null || !Files.exists(filePath)) {
            return;
        }
        XWPFParagraph paragraph = document.createParagraph();
        paragraph.setAlignment(ParagraphAlignment.CENTER);
        XWPFRun run = paragraph.createRun();
        String embedName = fileName != null ? fileName : filePath.getFileName().toString();
        try (WordEmbedImageUtil.PreparedPicture pic = WordEmbedImageUtil.prepare(filePath, embedName)) {
            run.addPicture(pic.stream(), pic.poiPictureType(), pic.embedFileName(),
                    Units.toEMU(300), Units.toEMU(225));
        }
    }

