        createTableCell(row4.getCell(1), componentSpec, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(2), "部件材质", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String componentMaterial = mergedMaterialOrCustomField(report, comps);
        createTableCell(row4.getCell(3), componentMaterial, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        String testMethodVis = getFieldValue(report, "testMethod", "/");
        if ("/".equals(testMethodVis)) {
            testMethodVis = "目视";
        }
        XWPFTableRow row5 = mainTable.createRow();
        setRowHeight(row5, 454);
        createTableCell(row5.getCell(0), "检测方法", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(1), testMethodVis, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(2), "表面状态", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(3), getCustomField(report, "表面状态", "原始状态"), 2667,
                ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row6 = mainTable.createRow();
        setRowHeight(row6, 454);
