    /**
     * 生成超声波测厚报告
     */
    private void generateUltrasonicThicknessReport(Report report, Project project, int reportIndex, XWPFDocument document)
        throws Exception {
        
        log.debug("Starting to generate Ultrasonic Thickness report for report {}", report.getId());
        
        // 获取关联的部件信息（如果存在）
        List<ProjectComponent> comps = resolveComponentsForReport(report);
        ProjectComponent component = reportComponentMergeHelper.firstOrNull(comps);
        
        // ========== 1. 公司名称 ==========
        XWPFParagraph companyTitle = document.createParagraph();
        companyTitle.setAlignment(ParagraphAlignment.CENTER);
        companyTitle.setSpacingBefore(0);
        companyTitle.setSpacingAfter(0);
        setExactLineSpacing(companyTitle, 20);

        XWPFRun companyRun = companyTitle.createRun();
        companyRun.setFontFamily("黑体");
        companyRun.setFontSize(14);
        companyRun.setText(brandingCompanyName());

        // ========== 2. 报告标题 ==========
        XWPFParagraph reportTitle = document.createParagraph();
        reportTitle.setAlignment(ParagraphAlignment.CENTER);
        reportTitle.setSpacingBefore(0);
        reportTitle.setSpacingAfter(0);
        setExactLineSpacing(reportTitle, 20);

        XWPFRun reportRun = reportTitle.createRun();
        reportRun.setFontFamily("黑体");
        reportRun.setFontSize(14);
        reportRun.setText("超声波测厚报告");

        // ========== 3. 文档编号 ==========
        XWPFParagraph docNumber = document.createParagraph();
        docNumber.setAlignment(ParagraphAlignment.RIGHT);
        docNumber.setSpacingBefore(0);
        docNumber.setSpacingAfter(0);
        docNumber.setSpacingLineRule(LineSpacingRule.EXACT);
        docNumber.setSpacingBetween(1.0);

        XWPFRun docRun = docNumber.createRun();
        docRun.setFontFamily("宋体");
        docRun.setFontSize(10.5);
        docRun.setText(UTM_DOC_NUMBER);

        // ========== 4. 基本信息表格（8行，两列布局） ==========
        XWPFTable mainTable = document.createTable(1, 4);
        setupTableProperties(mainTable, PT_TABLE_WIDTH);

        // 第1行: 项目名称（跨列）
        XWPFTableRow row1 = mainTable.getRow(0);
        setRowHeight(row1, 454);
        createTableCell(row1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
        
        // 第2行: 单项报告编号 | 记录编号
        XWPFTableRow row2 = mainTable.createRow();
        setRowHeight(row2, 454);
        createTableCell(row2.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String recordNumber = generateRecordNumber(report);
        createTableCell(row2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第3行: 设备类别 | 部件名称
        XWPFTableRow row3 = mainTable.createRow();
        setRowHeight(row3, 454);
        createTableCell(row3.getCell(0), "设备类别", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(1), getEquipmentCategoryForReport(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(2), "部件名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(3), getFieldValue(report, "componentName", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第4行: 部件规格 | 部件材质
        XWPFTableRow row4 = mainTable.createRow();
        setRowHeight(row4, 454);
        createTableCell(row4.getCell(0), "部件规格", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String componentSpec = mergedSpecPhiOrReportField(report, comps);
        createTableCell(row4.getCell(1), componentSpec, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(2), "部件材质", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String componentMaterial = (component != null && component.getMaterial() != null && !component.getMaterial().isEmpty()) 
            ? component.getMaterial() 
            : getCustomField(report, "部件材质", "/");
        createTableCell(row4.getCell(3), componentMaterial, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第5行: 仪器型号 | 仪器编号
        XWPFTableRow row5 = mainTable.createRow();
        setRowHeight(row5, 454);
        createTableCell(row5.getCell(0), "仪器型号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(1), getFieldValue(report, "instrumentModel", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(2), "仪器编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(3), getFieldValue(report, "instrumentNumber", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第6行: 探头 | 表面状态
        XWPFTableRow row6 = mainTable.createRow();
        setRowHeight(row6, 454);
        createTableCell(row6.getCell(0), "探头", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(1), getCustomField(report, "探头", "双晶5MФ8"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(2), "表面状态", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(3), "符合要求", 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第7行: 试块 | 检测标准
        XWPFTableRow row7 = mainTable.createRow();
        setRowHeight(row7, 454);
        createTableCell(row7.getCell(0), "试块", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row7.getCell(1), getCustomField(report, "试块", "阶梯试块"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row7.getCell(2), "检测标准", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row7.getCell(3), "NB/T 47013.3-2023", 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第8行: 检测人员 | 检测日期
        XWPFTableRow row8 = mainTable.createRow();
        setRowHeight(row8, inspectorRowHeight(report));
        createTableCell(row8.getCell(0), "检测人员", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row8.getCell(1), getFieldValue(report, "inspector", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row8.getCell(2), "检测日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String testDateStr = report.getTestDate() != null ? 
            report.getTestDate().format(DateTimeFormatter.ofPattern("yyyy-MM-dd")) : "/";
        createTableCell(row8.getCell(3), testDateStr, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // ========== 5. 检测部位 ==========
        XWPFTableRow detectionLocationRow = mainTable.createRow();
        setRowHeight(detectionLocationRow, 1644);
        
        // 获取检测方法名称
        String methodName = report.getTestMethod();
        if (methodName == null || methodName.isEmpty()) {
            if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
                ExperimentType expType = report.getReportItems().get(0).getExperimentType();
                if (expType != null && expType.getName() != null) {
                    methodName = expType.getName();
                }
            }
        }
        if (methodName == null || methodName.isEmpty()) {
            methodName = "/";
        }
        
        // 获取部件名称
        String componentName = getFieldValue(report, "componentName", "/");
        if (componentName == null || componentName.isEmpty()) {
            componentName = "/";
        }
        
        // 从 detectionContent 中提取信息
        String type = "/";
        String locationDesc = "/";
        String locationNumber = "/";
        String total = "/";
        
        // 获取检测结果数据以计算总数
        List<JsonNode> resultRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            resultRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("Failed to parse tableData for UTM report {}: {}", report.getId(), e.getMessage());
                }
            }
        }
        total = String.valueOf(TableDataMergeUtil.effectiveRowCountExcludingTrailingPlaceholder(resultRows));
        
        if (report.getDetectionContent() != null) {
            try {
                String detectionContentJson = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode detectionContentNode = objectMapper.readTree(detectionContentJson);
                
                // 从rows数组提取
                if (detectionContentNode.has("rows") && detectionContentNode.get("rows").isArray()) {
                    JsonNode rows = detectionContentNode.get("rows");
                    if (rows.size() > 0) {
                        JsonNode firstRow = rows.get(0);
                        if (firstRow.has("type")) {
                            type = firstRow.get("type").asText();
                        }
                        if (firstRow.has("locationDesc")) {
                            locationDesc = firstRow.get("locationDesc").asText();
                        }
                        if (firstRow.has("locationNumber")) {
                            locationNumber = firstRow.get("locationNumber").asText();
                        }
                        if (firstRow.has("total")) {
                            total = firstRow.get("total").asText();
                        }
                    }
                }
            } catch (Exception e) {
                log.warn("Failed to parse detectionContent for UTM report {}: {}", report.getId(), e.getMessage());
            }
        }
        
        // 如果值为空或null，设置为 "/"
        if (type == null || type.isEmpty()) type = "/";
        if (locationDesc == null || locationDesc.isEmpty()) locationDesc = "/";
        if (locationNumber == null || locationNumber.isEmpty()) locationNumber = "/";
        if (total == null || total.isEmpty()) total = "/";
        
        // 按字段有无条件显示
        ExperimentType expTypeForNarrUtm = (report.getReportItems() != null && !report.getReportItems().isEmpty())
                ? report.getReportItems().get(0).getExperimentType() : null;
        String _bodyLocPt = detectionContentNarrativeService.getEffectiveWordDetectionLocationNarrative(report, expTypeForNarrUtm,
                methodName, componentName, type, total, locationDesc, locationNumber);
        String detectionLocationText = _bodyLocPt.isEmpty() ? "检测部位：" : "检测部位:\n    " + _bodyLocPt;
        
        createTableCell(detectionLocationRow.getCell(0), detectionLocationText, PT_TABLE_WIDTH,
            ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);

        // ========== 6. 测量数据表格（8列，4组） ==========
        // 获取测量数据
        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            measurementRows.add(row);
                        }
                    }
                    log.debug("UTM report {}: Found {} measurement rows", report.getId(), measurementRows.size());
                } catch (Exception e) {
                    log.error("Failed to parse tableData for UTM report {}: {}", report.getId(), e.getMessage(), e);
                }
            } else {
                log.warn("UTM report {}: ReportItem has empty tableData", report.getId());
            }
        } else {
            log.warn("UTM report {}: Report has no report items", report.getId());
        }

        // 8 列（4 组 × 测点编号、实测厚度）
        final int utmTotalCols = UTM_GROUPS_PER_ROW * UTM_COLS_PER_GROUP;
        XWPFTable measurementTable = document.createTable(1, utmTotalCols);
        setupTableProperties(measurementTable, PT_TABLE_WIDTH);
        final int[] utmColW = distributeWidthsWithWiderNumberColumns(
                PT_TABLE_WIDTH, utmTotalCols, 1.2, 0, 2, 4, 6);

        writeUtmMeasurementHeaderRow(measurementTable.getRow(0), utmColW);

        int mainPageRows = UTM_MAIN_PAGE_DATA_ROWS;
        int totalMeasurements = measurementRows.size();

        for (int i = 0; i < mainPageRows; i++) {
            XWPFTableRow dataRow = measurementTable.createRow();
            setRowHeight(dataRow, UTM_MEASUREMENT_DATA_ROW_HEIGHT_TWIPS);
            writeUtmMeasurementDataRow(dataRow, i, 0, mainPageRows, measurementRows, totalMeasurements, utmColW);
        }

        // ========== 7. 检测结果（与 wordConclusionUtm / getConclusionTextForReport 一致）==========
        XWPFTableRow resultRow = measurementTable.createRow();
        setRowHeight(resultRow, UTM_RESULT_ROW_HEIGHT_TWIPS);
        String conclusionText = getConclusionTextForReport(report);
        createTableCell(resultRow.getCell(0), conclusionText != null ? conclusionText : "", PT_TABLE_WIDTH,
                ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, utmTotalCols);

        // ========== 8. 签批行（与磁粉报告列宽一致：1847/2667/1847/2667、1847/7181） ==========
        XWPFTable signTable = document.createTable(2, 4);
        setupTableProperties(signTable, PT_TABLE_WIDTH);
        XWPFTableRow signRow1 = signTable.getRow(0);
        setRowHeight(signRow1, 454);
        createTableCell(signRow1.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
        createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow1.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
        createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        XWPFTableRow signRow2 = signTable.getRow(1);
        setRowHeight(signRow2, 454);
        createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());
        createTableCell(signRow2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

        // 添加换页符
        document.createParagraph().createRun().addBreak(BreakType.PAGE);

        // ========== 9. 数据附页（续页，超过首页槽位 UTM_MAIN_PAGE_MEASUREMENT_SLOTS 的测点） ==========
        if (totalMeasurements > UTM_MAIN_PAGE_MEASUREMENT_SLOTS) {
            final int appendixRowsPerPage = 22;
            final int groupsPerRow = 4;
            final int appendixMeasurementsPerPage = appendixRowsPerPage * groupsPerRow; // 每页4组 × 22行 = 88个测点
            int remainingMeasurements = totalMeasurements - UTM_MAIN_PAGE_MEASUREMENT_SLOTS;
            int totalPages = (remainingMeasurements + appendixMeasurementsPerPage - 1) / appendixMeasurementsPerPage; // 向上取整
            
            for (int pageIndex = 0; pageIndex < totalPages; pageIndex++) {
                int pageStart = UTM_MAIN_PAGE_MEASUREMENT_SLOTS + pageIndex * appendixMeasurementsPerPage;
                
                
                
                // ========== 附页页眉 ==========
                // 公司名称
                XWPFParagraph companyTitle2 = document.createParagraph();
                companyTitle2.setAlignment(ParagraphAlignment.CENTER);
                companyTitle2.setSpacingBefore(0);
                companyTitle2.setSpacingAfter(0);
                setExactLineSpacing(companyTitle2, 20);
                
                XWPFRun companyRun2 = companyTitle2.createRun();
                companyRun2.setFontFamily("黑体");
                companyRun2.setFontSize(14);
                companyRun2.setText(brandingCompanyName());
                
                // 报告标题（续页）
                XWPFParagraph reportTitle2 = document.createParagraph();
                reportTitle2.setAlignment(ParagraphAlignment.CENTER);
                reportTitle2.setSpacingBefore(0);
                reportTitle2.setSpacingAfter(0);
                setExactLineSpacing(reportTitle2, 20);
                
                XWPFRun reportRun2 = reportTitle2.createRun();
                reportRun2.setFontFamily("黑体");
                reportRun2.setFontSize(14);
                reportRun2.setText("超声波测厚报告（续页）");
                
                // 文档编号
                XWPFParagraph docNumber2 = document.createParagraph();
                docNumber2.setAlignment(ParagraphAlignment.RIGHT);
                docNumber2.setSpacingBefore(0);
                docNumber2.setSpacingAfter(0);
                docNumber2.setSpacingLineRule(LineSpacingRule.EXACT);
                docNumber2.setSpacingBetween(1.0);
                
                XWPFRun docRun2 = docNumber2.createRun();
                docRun2.setFontFamily("宋体");
                docRun2.setFontSize(10.5);
                docRun2.setText(UTM_DOC_NUMBER);
                
                // ========== 附页信息表格 ==========
                XWPFTable appendixTable = document.createTable(1, 4);
                setupTableProperties(appendixTable, PT_TABLE_WIDTH);
                
                // 第一行: 项目名称
                XWPFTableRow headerRow1 = appendixTable.getRow(0);
                setRowHeight(headerRow1, 454);
                createTableCell(headerRow1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
                
                // 第二行: 单项报告编号 | 记录编号
                XWPFTableRow headerRow2 = appendixTable.createRow();
                setRowHeight(headerRow2, 454);
                createTableCell(headerRow2.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                // ========== 测量数据表格（12 列，4 组） ==========
                XWPFTable appendixMeasurementTable = document.createTable(1, utmTotalCols);
                setupTableProperties(appendixMeasurementTable, PT_TABLE_WIDTH);

                writeUtmMeasurementHeaderRow(appendixMeasurementTable.getRow(0), utmColW);

                for (int i = 0; i < appendixRowsPerPage; i++) {
                    XWPFTableRow dataRow = appendixMeasurementTable.createRow();
                    setRowHeight(dataRow, 454);
                    writeUtmMeasurementDataRow(dataRow, i, pageStart, appendixRowsPerPage, measurementRows,
                            totalMeasurements, utmColW);
                }
                
                // ========== 签批行（与磁粉报告列宽一致：1847/2667/1847/2667、1847/7181） ==========
                XWPFTable signTable_2 = document.createTable(2, 4);
                setupTableProperties(signTable_2, PT_TABLE_WIDTH);
                XWPFTableRow signRow1_2 = signTable_2.getRow(0);
                setRowHeight(signRow1_2, 454);
                createTableCell(signRow1_2.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                XWPFTableRow signRow2_2 = signTable_2.getRow(1);
                setRowHeight(signRow2_2, 454);
                createTableCell(signRow2_2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow2_2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                // 添加换页符
                document.createParagraph().createRun().addBreak(BreakType.PAGE);
            }
        }

        // ========== 10. 附图附页（如果有imageAttachments） ==========
        generateImageAppendix(document, report, project, "超声波测厚报告（附页）", UTM_DOC_NUMBER, false);

        log.debug("Completed generating Ultrasonic Thickness report for report {}", report.getId());
    }

    /**
     * 生成管径测量报告（CL/JC26/BG01-2024）：信息表 + 8 列测点表 + 数据续页 + 附图附页。
     */
    private void generatePipeDiameterMeasurementReport(Report report, Project project, int reportIndex, XWPFDocument document)
        throws Exception {

        log.debug("Starting to generate Pipe Diameter Measurement report for report {}", report.getId());

        List<ProjectComponent> comps = resolveComponentsForReport(report);
        ProjectComponent component = reportComponentMergeHelper.firstOrNull(comps);

        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            measurementRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("Failed to parse tableData for PDM report {}: {}", report.getId(), e.getMessage());
                }
            }
        }
        int totalMeasurements = measurementRows.size();
        Double maxMeasured = null;
        for (JsonNode row : measurementRows) {
            Double d = null;
            if (row.has("实测管径（mm）")) {
                JsonNode n = row.get("实测管径（mm）");
                if (n.isNumber()) {
                    d = n.asDouble();
                } else {
                    try {
                        d = Double.parseDouble(n.asText().trim());
                    } catch (NumberFormatException ignored) {
                    }
                }
            } else if (row.has("实测管径")) {
                JsonNode n = row.get("实测管径");
                if (n.isNumber()) {
                    d = n.asDouble();
                } else {
                    try {
                        d = Double.parseDouble(n.asText().trim());
                    } catch (NumberFormatException ignored) {
                    }
                }
            }
            if (d != null && d > 0) {
                if (maxMeasured == null || d > maxMeasured) {
                    maxMeasured = d;
                }
            }
        }
        String maxMeasuredStr = maxMeasured == null ? "/" : String.valueOf(maxMeasured);
        String recordNumber = generateRecordNumber(report);
        String componentSpec = mergedSpecPhiOrReportField(report, comps);
        String componentMaterial = (component != null && component.getMaterial() != null && !component.getMaterial().isEmpty())
                ? component.getMaterial()
                : getCustomField(report, "部件材质", "/");
        String testDateStr = report.getTestDate() != null
                ? report.getTestDate().format(DateTimeFormatter.ofPattern("yyyy-MM-dd")) : "/";

        XWPFParagraph companyTitle = document.createParagraph();
        companyTitle.setAlignment(ParagraphAlignment.CENTER);
        companyTitle.setSpacingBefore(0);
        companyTitle.setSpacingAfter(0);
        setExactLineSpacing(companyTitle, 20);

        XWPFRun companyRun = companyTitle.createRun();
        companyRun.setFontFamily("黑体");
        companyRun.setFontSize(14);
        companyRun.setText(brandingCompanyName());

        XWPFParagraph reportTitle = document.createParagraph();
        reportTitle.setAlignment(ParagraphAlignment.CENTER);
        reportTitle.setSpacingBefore(0);
        reportTitle.setSpacingAfter(0);
        setExactLineSpacing(reportTitle, 20);

        XWPFRun reportRun = reportTitle.createRun();
        reportRun.setFontFamily("黑体");
        reportRun.setFontSize(14);
        reportRun.setText("管径测量报告");

        XWPFParagraph docNumber = document.createParagraph();
        docNumber.setAlignment(ParagraphAlignment.RIGHT);
        docNumber.setSpacingBefore(0);
        docNumber.setSpacingAfter(0);
        docNumber.setSpacingLineRule(LineSpacingRule.EXACT);
        docNumber.setSpacingBetween(1.0);

        XWPFRun docRun = docNumber.createRun();
        docRun.setFontFamily("宋体");
        docRun.setFontSize(10.5);
        docRun.setText(PDM_DOC_NUMBER);

        XWPFTable mainTable = document.createTable(1, 4);
        setupTableProperties(mainTable, PT_TABLE_WIDTH);

        XWPFTableRow row1 = mainTable.getRow(0);
        setRowHeight(row1, 454);
        createTableCell(row1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

        XWPFTableRow row2 = mainTable.createRow();
        setRowHeight(row2, 454);
        createTableCell(row2.getCell(0), "报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row3 = mainTable.createRow();
        setRowHeight(row3, 454);
        createTableCell(row3.getCell(0), "设备类别", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(1), getEquipmentCategoryForReport(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(2), "部件名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(3), getFieldValue(report, "componentName", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row4 = mainTable.createRow();
        setRowHeight(row4, 454);
        createTableCell(row4.getCell(0), "部件规格", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(1), componentSpec, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(2), "部件材质", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(3), componentMaterial, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row5 = mainTable.createRow();
        setRowHeight(row5, 454);
        createTableCell(row5.getCell(0), "仪器型号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(1), getFieldValue(report, "instrumentModel", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(2), "仪器编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(3), getFieldValue(report, "instrumentNumber", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow row6 = mainTable.createRow();
        setRowHeight(row6, inspectorRowHeight(report));
        
        createTableCell(row6.getCell(0), "检测人员", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(1), getFieldValue(report, "inspector", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);       
        createTableCell(row6.getCell(2), "检测日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(3), testDateStr, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

        XWPFTableRow detectionLocationRow = mainTable.createRow();
        setRowHeight(detectionLocationRow, 1644);

        String methodName = report.getTestMethod();
        if (methodName == null || methodName.isEmpty()) {
            if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
                ExperimentType expType = report.getReportItems().get(0).getExperimentType();
                if (expType != null && expType.getName() != null) {
                    methodName = expType.getName();
                }
            }
        }
        if (methodName == null || methodName.isEmpty()) {
            methodName = "/";
        }

        String componentName = getFieldValue(report, "componentName", "/");
        if (componentName == null || componentName.isEmpty()) {
            componentName = "/";
        }

        String type = "/";
        String locationDesc = "/";
        String locationNumber = "/";
        String total = String.valueOf(measurementRows.size());

        if (report.getDetectionContent() != null) {
            try {
                String detectionContentJson = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode detectionContentNode = objectMapper.readTree(detectionContentJson);

                if (detectionContentNode.has("rows") && detectionContentNode.get("rows").isArray()) {
                    JsonNode rows = detectionContentNode.get("rows");
                    if (rows.size() > 0) {
                        JsonNode firstRow = rows.get(0);
                        if (firstRow.has("type")) {
                            type = firstRow.get("type").asText();
                        }
                        if (firstRow.has("locationDesc")) {
                            locationDesc = firstRow.get("locationDesc").asText();
                        }
                        if (firstRow.has("locationNumber")) {
                            locationNumber = firstRow.get("locationNumber").asText();
                        }
                        if (firstRow.has("total")) {
                            total = firstRow.get("total").asText();
                        }
                    }
                }
            } catch (Exception e) {
                log.warn("Failed to parse detectionContent for PDM report {}: {}", report.getId(), e.getMessage());
            }
        }

        if (type == null || type.isEmpty()) {
            type = "/";
        }
        if (locationDesc == null || locationDesc.isEmpty()) {
            locationDesc = "/";
        }
        if (locationNumber == null || locationNumber.isEmpty()) {
            locationNumber = "/";
        }
        if (total == null || total.isEmpty()) {
            total = "/";
        }

        ExperimentType expTypeForNarrPdm = (report.getReportItems() != null && !report.getReportItems().isEmpty())
                ? report.getReportItems().get(0).getExperimentType() : null;
        String _bodyLocPt = detectionContentNarrativeService.getEffectiveWordDetectionLocationNarrative(report, expTypeForNarrPdm,
                methodName, componentName, type, total, locationDesc, locationNumber);
        String detectionLocationText = _bodyLocPt.isEmpty() ? "检测部位：" : "检测部位:\n    " + _bodyLocPt;
        detectionLocationText += "\n\n注：测点 P2-1 表示，左数第 2 排第 1 根管子，以此类推。";

        createTableCell(detectionLocationRow.getCell(0), detectionLocationText, PT_TABLE_WIDTH,
                ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);

        final int[] pdm8ColW = distributeWidthsWithWiderNumberColumns(
                PT_TABLE_WIDTH, 8, NUMBER_COLUMN_WIDTH_MULTIPLIER, 0, 2, 4, 6);

        XWPFTable measurementTable = document.createTable(1, 8);
        setupTableProperties(measurementTable, PT_TABLE_WIDTH);

        XWPFTableRow headerRow = measurementTable.getRow(0);
        setRowHeight(headerRow, 510);
        createTableCell(headerRow.getCell(0), "测点编号", pdm8ColW[0], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(1), "实测管径（mm）", pdm8ColW[1], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(2), "测点编号", pdm8ColW[2], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(3), "实测管径（mm）", pdm8ColW[3], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(4), "测点编号", pdm8ColW[4], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(5), "实测管径（mm）", pdm8ColW[5], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(6), "测点编号", pdm8ColW[6], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(7), "实测管径（mm）", pdm8ColW[7], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        int mainPageRows = 8;
        for (int i = 0; i < mainPageRows; i++) {
            XWPFTableRow dataRow = measurementTable.createRow();
            setRowHeight(dataRow, 454);

            for (int group = 0; group < 4; group++) {
                int measurementIndex = group * mainPageRows + i;
                JsonNode rowData = measurementIndex < totalMeasurements ? measurementRows.get(measurementIndex) : null;

                String pointNumber = "/";
                String diameter = "/";

                if (rowData != null) {
                    if (rowData.has("测点编号")) {
                        pointNumber = rowData.get("测点编号").asText();
                    } else if (rowData.has("编号")) {
                        pointNumber = rowData.get("编号").asText();
                    }

                    if (rowData.has("实测管径（mm）")) {
                        JsonNode t = rowData.get("实测管径（mm）");
                        diameter = t.isNumber() ? String.valueOf(t.asDouble()) : t.asText();
                    } else if (rowData.has("实测管径")) {
                        JsonNode t = rowData.get("实测管径");
                        diameter = t.isNumber() ? String.valueOf(t.asDouble()) : t.asText();
                    }
                }

                createTableCell(dataRow.getCell(group * 2), pointNumber, pdm8ColW[group * 2], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(dataRow.getCell(group * 2 + 1), diameter, pdm8ColW[group * 2 + 1], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            }
        }

        XWPFTableRow resultRow = measurementTable.createRow();
        setRowHeight(resultRow, 1644);
        String conclusionText = getConclusionTextForReport(report);
        createTableCell(resultRow.getCell(0), conclusionText != null ? conclusionText : "", PT_TABLE_WIDTH,
                ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, 8);

        XWPFTable signTable = document.createTable(2, 4);
        setupTableProperties(signTable, PT_TABLE_WIDTH);
        XWPFTableRow signRow1 = signTable.getRow(0);
        setRowHeight(signRow1, 454);
        createTableCell(signRow1.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
        createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow1.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
        createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        XWPFTableRow signRow2 = signTable.getRow(1);
        setRowHeight(signRow2, 454);
        createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());
        createTableCell(signRow2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

        document.createParagraph().createRun().addBreak(BreakType.PAGE);

        if (totalMeasurements > 32) {
            int remainingMeasurements = totalMeasurements - 32;
            int measurementsPerPage = 32;
            int totalPages = (remainingMeasurements + 31) / 32;

            for (int pageIndex = 0; pageIndex < totalPages; pageIndex++) {
                int pageStart = 32 + pageIndex * measurementsPerPage;

                document.createParagraph().createRun().addBreak(BreakType.PAGE);

                XWPFParagraph companyTitle2 = document.createParagraph();
                companyTitle2.setAlignment(ParagraphAlignment.CENTER);
                companyTitle2.setSpacingBefore(0);
                companyTitle2.setSpacingAfter(0);
                setExactLineSpacing(companyTitle2, 20);

                XWPFRun companyRun2 = companyTitle2.createRun();
                companyRun2.setFontFamily("黑体");
                companyRun2.setFontSize(14);
                companyRun2.setText(brandingCompanyName());

                XWPFParagraph reportTitle2 = document.createParagraph();
                reportTitle2.setAlignment(ParagraphAlignment.CENTER);
                reportTitle2.setSpacingBefore(0);
                reportTitle2.setSpacingAfter(0);
                setExactLineSpacing(reportTitle2, 20);

                XWPFRun reportRun2 = reportTitle2.createRun();
                reportRun2.setFontFamily("黑体");
                reportRun2.setFontSize(14);
                reportRun2.setText("管径测量报告（续页）");

                XWPFParagraph docNumber2 = document.createParagraph();
                docNumber2.setAlignment(ParagraphAlignment.RIGHT);
                docNumber2.setSpacingBefore(0);
                docNumber2.setSpacingAfter(0);
                docNumber2.setSpacingLineRule(LineSpacingRule.EXACT);
                docNumber2.setSpacingBetween(1.0);

                XWPFRun docRun2 = docNumber2.createRun();
                docRun2.setFontFamily("宋体");
                docRun2.setFontSize(10.5);
                docRun2.setText(PDM_DOC_NUMBER);

                XWPFTable appendixTable = document.createTable(1, 4);
                setupTableProperties(appendixTable, PT_TABLE_WIDTH);

                XWPFTableRow headerRow1 = appendixTable.getRow(0);
                setRowHeight(headerRow1, 454);
                createTableCell(headerRow1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                XWPFTableRow headerRow2 = appendixTable.createRow();
                setRowHeight(headerRow2, 454);
                createTableCell(headerRow2.getCell(0), "报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                XWPFTable appendixMeasurementTable = document.createTable(1, 8);
                setupTableProperties(appendixMeasurementTable, PT_TABLE_WIDTH);

                XWPFTableRow appendixHeaderRow = appendixMeasurementTable.getRow(0);
                setRowHeight(appendixHeaderRow, 510);
                createTableCell(appendixHeaderRow.getCell(0), "测点编号", pdm8ColW[0], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(1), "实测管径（mm）", pdm8ColW[1], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(2), "测点编号", pdm8ColW[2], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(3), "实测管径（mm）", pdm8ColW[3], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(4), "测点编号", pdm8ColW[4], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(5), "实测管径（mm）", pdm8ColW[5], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(6), "测点编号", pdm8ColW[6], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(7), "实测管径（mm）", pdm8ColW[7], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                for (int i = 0; i < 8; i++) {
                    XWPFTableRow dataRow = appendixMeasurementTable.createRow();
                    setRowHeight(dataRow, 454);

                    for (int group = 0; group < 4; group++) {
                        int measurementIndex = pageStart + group * 8 + i;
                        JsonNode rowData = measurementIndex < totalMeasurements ? measurementRows.get(measurementIndex) : null;

                        String pointNumber = "/";
                        String diameter = "/";

                        if (rowData != null) {
                            if (rowData.has("测点编号")) {
                                pointNumber = rowData.get("测点编号").asText();
                            } else if (rowData.has("编号")) {
                                pointNumber = rowData.get("编号").asText();
                            }

                            if (rowData.has("实测管径（mm）")) {
                                JsonNode t = rowData.get("实测管径（mm）");
                                diameter = t.isNumber() ? String.valueOf(t.asDouble()) : t.asText();
                            } else if (rowData.has("实测管径")) {
                                JsonNode t = rowData.get("实测管径");
                                diameter = t.isNumber() ? String.valueOf(t.asDouble()) : t.asText();
                            }
                        }

                        createTableCell(dataRow.getCell(group * 2), pointNumber, pdm8ColW[group * 2], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                        createTableCell(dataRow.getCell(group * 2 + 1), diameter, pdm8ColW[group * 2 + 1], ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    }
                }

                XWPFTable signTable_2 = document.createTable(2, 4);
                setupTableProperties(signTable_2, PT_TABLE_WIDTH);
                XWPFTableRow signRow1_2 = signTable_2.getRow(0);
                setRowHeight(signRow1_2, 454);
                createTableCell(signRow1_2.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                XWPFTableRow signRow2_2 = signTable_2.getRow(1);
                setRowHeight(signRow2_2, 454);
                createTableCell(signRow2_2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow2_2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                document.createParagraph().createRun().addBreak(BreakType.PAGE);
            }
        }

        generateImageAppendix(document, report, project, "管径测量报告（附页）", PDM_DOC_NUMBER, false);

        log.debug("Completed generating Pipe Diameter Measurement report for report {}", report.getId());
    }

    /**
     * 生成圆度测量报告
     */
    private void generateRoundnessMeasurementReport(Report report, Project project, int reportIndex, XWPFDocument document)
        throws Exception {
        
        log.debug("Starting to generate Roundness Measurement report for report {}", report.getId());
        
        // 获取关联的部件信息（如果存在）
        List<ProjectComponent> comps = resolveComponentsForReport(report);
        ProjectComponent component = reportComponentMergeHelper.firstOrNull(comps);
        
        // ========== 1. 公司名称 ==========
        XWPFParagraph companyTitle = document.createParagraph();
        companyTitle.setAlignment(ParagraphAlignment.CENTER);
        companyTitle.setSpacingBefore(0);
        companyTitle.setSpacingAfter(0);
        setExactLineSpacing(companyTitle, 20);

        XWPFRun companyRun = companyTitle.createRun();
        companyRun.setFontFamily("黑体");
        companyRun.setFontSize(14);
        companyRun.setText(brandingCompanyName());

        // ========== 2. 报告标题 ==========
        XWPFParagraph reportTitle = document.createParagraph();
        reportTitle.setAlignment(ParagraphAlignment.CENTER);
        reportTitle.setSpacingBefore(0);
        reportTitle.setSpacingAfter(0);
        setExactLineSpacing(reportTitle, 20);

        XWPFRun reportRun = reportTitle.createRun();
        reportRun.setFontFamily("黑体");
        reportRun.setFontSize(14);
        reportRun.setText("圆度测量报告");

        // ========== 3. 文档编号 ==========
        XWPFParagraph docNumber = document.createParagraph();
        docNumber.setAlignment(ParagraphAlignment.RIGHT);
        docNumber.setSpacingBefore(0);
        docNumber.setSpacingAfter(0);
        docNumber.setSpacingLineRule(LineSpacingRule.EXACT);
        docNumber.setSpacingBetween(1.0);

        XWPFRun docRun = docNumber.createRun();
        docRun.setFontFamily("宋体");
        docRun.setFontSize(10.5);
        docRun.setText(RDM_DOC_NUMBER);

        // ========== 4. 基本信息表格（6行，两列布局） ==========
        XWPFTable mainTable = document.createTable(1, 4);
        setupTableProperties(mainTable, PT_TABLE_WIDTH);

        // 第1行: 项目名称（跨列）
        XWPFTableRow row1 = mainTable.getRow(0);
        setRowHeight(row1, 454);
        createTableCell(row1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
        
        // 第2行: 单项报告编号 | 记录编号
        XWPFTableRow row2 = mainTable.createRow();
        setRowHeight(row2, 454);
        createTableCell(row2.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String recordNumber = generateRecordNumber(report);
        createTableCell(row2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第3行: 部件名称 | 材质
        XWPFTableRow row3 = mainTable.createRow();
        setRowHeight(row3, 454);
        createTableCell(row3.getCell(0), "部件名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(1), getFieldValue(report, "componentName", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row3.getCell(2), "材质", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String componentMaterial = (component != null && component.getMaterial() != null && !component.getMaterial().isEmpty()) 
            ? component.getMaterial() 
            : getCustomField(report, "部件材质", "/");
        createTableCell(row3.getCell(3), componentMaterial, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第4行: 规格 | 仪器型号
        XWPFTableRow row4 = mainTable.createRow();
        setRowHeight(row4, 454);
        createTableCell(row4.getCell(0), "规格", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String componentSpec = mergedSpecPhiOrReportField(report, comps);
        createTableCell(row4.getCell(1), componentSpec, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(2), "仪器型号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row4.getCell(3), getFieldValue(report, "instrumentModel", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第5行: 仪器编号 | 验收标准
        XWPFTableRow row5 = mainTable.createRow();
        setRowHeight(row5, 454);
        createTableCell(row5.getCell(0), "仪器编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(1), getFieldValue(report, "instrumentNumber", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(2), "验收标准", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row5.getCell(3), getCustomField(report, "验收标准", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 第6行: 检测人员 | 检测日期
        XWPFTableRow row6 = mainTable.createRow();
        setRowHeight(row6, inspectorRowHeight(report));
        createTableCell(row6.getCell(0), "检测人员", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(1), getFieldValue(report, "inspector", "/"), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(row6.getCell(2), "检测日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String testDateStr = report.getTestDate() != null ? 
            report.getTestDate().format(DateTimeFormatter.ofPattern("yyyy-MM-dd")) : "/";
        createTableCell(row6.getCell(3), testDateStr, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // ========== 5. 检测部位 ==========
        XWPFTableRow detectionLocationRow = mainTable.createRow();
        setRowHeight(detectionLocationRow, 1644);
        
        // 获取检测方法名称
        String methodName = report.getTestMethod();
        if (methodName == null || methodName.isEmpty()) {
            if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
                ExperimentType expType = report.getReportItems().get(0).getExperimentType();
                if (expType != null && expType.getName() != null) {
                    methodName = expType.getName();
                }
            }
        }
        if (methodName == null || methodName.isEmpty()) {
            methodName = "/";
        }
        
        // 获取部件名称
        String componentName = getFieldValue(report, "componentName", "/");
        if (componentName == null || componentName.isEmpty()) {
            componentName = "/";
        }
        
        // 从 detectionContent 中提取信息
        String type = "/";
        String locationDesc = "/";
        String locationNumber = "/";
        String total = "/";
        
        // 获取检测结果数据以计算总数
        List<JsonNode> resultRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            resultRows.add(row);
                        }
                    }
                } catch (Exception e) {
                    log.warn("Failed to parse tableData for RDM report {}: {}", report.getId(), e.getMessage());
                }
            }
        }
        total = String.valueOf(TableDataMergeUtil.effectiveRowCountExcludingTrailingPlaceholder(resultRows));
        
        if (report.getDetectionContent() != null) {
            try {
                String detectionContentJson = objectMapper.writeValueAsString(report.getDetectionContent());
                JsonNode detectionContentNode = objectMapper.readTree(detectionContentJson);
                
                // 从rows数组提取
                if (detectionContentNode.has("rows") && detectionContentNode.get("rows").isArray()) {
                    JsonNode rows = detectionContentNode.get("rows");
                    if (rows.size() > 0) {
                        JsonNode firstRow = rows.get(0);
                        if (firstRow.has("type")) {
                            type = firstRow.get("type").asText();
                        }
                        if (firstRow.has("locationDesc")) {
                            locationDesc = firstRow.get("locationDesc").asText();
                        }
                        if (firstRow.has("locationNumber")) {
                            locationNumber = firstRow.get("locationNumber").asText();
                        }
                        if (firstRow.has("total")) {
                            total = firstRow.get("total").asText();
                        }
                    }
                }
            } catch (Exception e) {
                log.warn("Failed to parse detectionContent for RDM report {}: {}", report.getId(), e.getMessage());
            }
        }
        
        // 如果值为空或null，设置为 "/"
        if (type == null || type.isEmpty()) type = "/";
        if (locationDesc == null || locationDesc.isEmpty()) locationDesc = "/";
        if (locationNumber == null || locationNumber.isEmpty()) locationNumber = "/";
        if (total == null || total.isEmpty()) total = "/";
        
        // 按字段有无条件显示
        ExperimentType expTypeForNarrRdm = (report.getReportItems() != null && !report.getReportItems().isEmpty())
                ? report.getReportItems().get(0).getExperimentType() : null;
        String _bodyLocPt = detectionContentNarrativeService.getEffectiveWordDetectionLocationNarrative(report, expTypeForNarrRdm,
                methodName, componentName, type, total, locationDesc, locationNumber);
        String detectionLocationText = _bodyLocPt.isEmpty() ? "检测部位：" : "检测部位:\n    " + _bodyLocPt;
        
        createTableCell(detectionLocationRow.getCell(0), detectionLocationText, PT_TABLE_WIDTH,
            ParagraphAlignment.LEFT, XWPFTableCell.XWPFVertAlign.TOP, 4);

        // ========== 6. 测量数据表格（6列） ==========
        // 获取测量数据
        List<JsonNode> measurementRows = new ArrayList<>();
        if (report.getReportItems() != null && !report.getReportItems().isEmpty()) {
            ReportItem firstItem = report.getReportItems().get(0);
            if (firstItem.getTableData() != null && !firstItem.getTableData().isEmpty()) {
                try {
                    JsonNode mergedRows = TableDataMergeUtil.mergedRowsFromTableDataJson(firstItem.getTableData(), objectMapper);
                    if (mergedRows != null && mergedRows.isArray()) {
                        for (JsonNode row : mergedRows) {
                            measurementRows.add(row);
                        }
                    }
                    log.debug("RDM report {}: Found {} measurement rows", report.getId(), measurementRows.size());
                } catch (Exception e) {
                    log.error("Failed to parse tableData for RDM report {}: {}", report.getId(), e.getMessage(), e);
                }
            } else {
                log.warn("RDM report {}: ReportItem has empty tableData", report.getId());
            }
        } else {
            log.warn("RDM report {}: Report has no report items", report.getId());
        }

        // 创建6列表格
        XWPFTable measurementTable = document.createTable(1, 6);
        setupTableProperties(measurementTable, PT_TABLE_WIDTH);
        
        // 计算列宽：总宽度9028，6列
        int measurementColWidth = 1504; // 9028 / 6 ≈ 1504
        
        // 表头行
        XWPFTableRow headerRow = measurementTable.getRow(0);
        setRowHeight(headerRow, 510);
        createTableCell(headerRow.getCell(0), "弯头编号", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(1), "公称直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(2), "弧面直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(3), "侧面直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(4), "测量圆度值", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(headerRow.getCell(5), "允许圆度值", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        // 主报告页固定8行
        int mainPageRows = 8;
        int totalMeasurements = measurementRows.size();
        
        for (int i = 0; i < mainPageRows; i++) {
            XWPFTableRow dataRow = measurementTable.createRow();
            setRowHeight(dataRow, 454);
            
            JsonNode rowData = i < totalMeasurements ? measurementRows.get(i) : null;
            
            String elbowNumber = "/";
            String nominalDiameter = "/";
            String arcDiameter = "/";
            String sideDiameter = "/";
            String measuredRoundness = "/";
            String allowedRoundness = "/";
            Double measuredValue = null;
            Double allowedValue = null;
            
            if (rowData != null) {
                // 提取弯头编号
                if (rowData.has("弯头编号")) {
                    elbowNumber = rowData.get("弯头编号").asText();
                }
                
                // 提取公称直径
                if (rowData.has("公称直径 (mm)")) {
                    JsonNode d = rowData.get("公称直径 (mm)");
                    nominalDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                } else if (rowData.has("公称直径")) {
                    JsonNode d = rowData.get("公称直径");
                    nominalDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                }
                
                // 提取弧面直径
                if (rowData.has("弧面直径 (mm)")) {
                    JsonNode d = rowData.get("弧面直径 (mm)");
                    arcDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                } else if (rowData.has("弧面直径")) {
                    JsonNode d = rowData.get("弧面直径");
                    arcDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                }
                
                // 提取侧面直径
                if (rowData.has("侧面直径 (mm)")) {
                    JsonNode d = rowData.get("侧面直径 (mm)");
                    sideDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                } else if (rowData.has("侧面直径")) {
                    JsonNode d = rowData.get("侧面直径");
                    sideDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                }
                
                // 提取测量圆度值
                if (rowData.has("测量圆度值")) {
                    JsonNode r = rowData.get("测量圆度值");
                    if (r.isNumber()) {
                        measuredValue = r.asDouble();
                        measuredRoundness = String.valueOf(measuredValue);
                    } else {
                        measuredRoundness = r.asText();
                    }
                }
                
                // 提取允许圆度值
                if (rowData.has("允许圆度值")) {
                    JsonNode r = rowData.get("允许圆度值");
                    if (r.isNumber()) {
                        allowedValue = r.asDouble();
                        allowedRoundness = String.valueOf(allowedValue);
                    } else {
                        allowedRoundness = r.asText();
                    }
                }
            }
            
            createTableCell(dataRow.getCell(0), elbowNumber, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(1), nominalDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(2), arcDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(3), sideDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(4), measuredRoundness, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
            createTableCell(dataRow.getCell(5), allowedRoundness, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        }

        // ========== 7. 检测结果（与 wordConclusionRdm / getConclusionTextForReport 一致）==========
        XWPFTableRow resultRow = measurementTable.createRow();
        setRowHeight(resultRow, 1644+454*3);
        String conclusionText = getConclusionTextForReport(report);
        createTableCell(resultRow.getCell(0), conclusionText != null ? conclusionText : "", PT_TABLE_WIDTH,
            ParagraphAlignment.BOTH, XWPFTableCell.XWPFVertAlign.TOP, 6);

        // ========== 8. 签批行 ==========
        XWPFTable signTable = document.createTable(1, 4);
        setupTableProperties(signTable, PT_TABLE_WIDTH);
        
        XWPFTableRow signRow1 = signTable.getRow(0);
        setRowHeight(signRow1, 454);
        createTableCell(signRow1.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String writeName = signatureLineForReport(report, project, "writer", project.getWriterNdt(), project.getWriterDateNdt());
        createTableCell(signRow1.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        createTableCell(signRow1.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String reviewName = signatureLineForReport(report, project, "reviewer", project.getReviewerNdt(), project.getReviewDateNdt());
        createTableCell(signRow1.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

        XWPFTableRow signRow2 = signTable.createRow();
        setRowHeight(signRow2, 454);
        createTableCell(signRow2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
        String approveName = signatureLineForReport(report, project, "approver", project.getApproverNdt(), project.getApprovalDateNdt());
        createTableCell(signRow2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

        // 添加换页符
        document.createParagraph().createRun().addBreak(BreakType.PAGE);

        // ========== 9. 数据附页（续页，如果测量数据超过8行） ==========
        if (totalMeasurements > 8) {
            int remainingMeasurements = totalMeasurements - 8;
            int measurementsPerPage = 8; // 每页8行
            int totalPages = (remainingMeasurements + 7) / 8; // 向上取整
            
            for (int pageIndex = 0; pageIndex < totalPages; pageIndex++) {
                int pageStart = 8 + pageIndex * measurementsPerPage;
                
                // 分页符
                document.createParagraph().createRun().addBreak(BreakType.PAGE);
                
                // ========== 附页页眉 ==========
                // 公司名称
                XWPFParagraph companyTitle2 = document.createParagraph();
                companyTitle2.setAlignment(ParagraphAlignment.CENTER);
                companyTitle2.setSpacingBefore(0);
                companyTitle2.setSpacingAfter(0);
                setExactLineSpacing(companyTitle2, 20);
                
                XWPFRun companyRun2 = companyTitle2.createRun();
                companyRun2.setFontFamily("黑体");
                companyRun2.setFontSize(14);
                companyRun2.setText(brandingCompanyName());
                
                // 报告标题（续页）
                XWPFParagraph reportTitle2 = document.createParagraph();
                reportTitle2.setAlignment(ParagraphAlignment.CENTER);
                reportTitle2.setSpacingBefore(0);
                reportTitle2.setSpacingAfter(0);
                setExactLineSpacing(reportTitle2, 20);
                
                XWPFRun reportRun2 = reportTitle2.createRun();
                reportRun2.setFontFamily("黑体");
                reportRun2.setFontSize(14);
                reportRun2.setText("圆度测量报告（续页）");
                
                // 文档编号
                XWPFParagraph docNumber2 = document.createParagraph();
                docNumber2.setAlignment(ParagraphAlignment.RIGHT);
                docNumber2.setSpacingBefore(0);
                docNumber2.setSpacingAfter(0);
                docNumber2.setSpacingLineRule(LineSpacingRule.EXACT);
                docNumber2.setSpacingBetween(1.0);
                
                XWPFRun docRun2 = docNumber2.createRun();
                docRun2.setFontFamily("宋体");
                docRun2.setFontSize(10.5);
                docRun2.setText(RDM_DOC_NUMBER);
                
                // ========== 附页信息表格 ==========
                XWPFTable appendixTable = document.createTable(1, 4);
                setupTableProperties(appendixTable, PT_TABLE_WIDTH);
                
                // 第一行: 项目名称
                XWPFTableRow headerRow1 = appendixTable.getRow(0);
                setRowHeight(headerRow1, 454);
                createTableCell(headerRow1.getCell(0), "项目名称", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow1.getCell(1), projectNameCellText(project), 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);
                
                // 第二行: 单项报告编号 | 记录编号
                XWPFTableRow headerRow2 = appendixTable.createRow();
                setRowHeight(headerRow2, 454);
                createTableCell(headerRow2.getCell(0), "单项报告编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(1), brandingReportNumberForDisplay(report), 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(2), "记录编号", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(headerRow2.getCell(3), recordNumber, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                // ========== 测量数据表格（6列） ==========
                XWPFTable appendixMeasurementTable = document.createTable(1, 6);
                setupTableProperties(appendixMeasurementTable, PT_TABLE_WIDTH);
                
                // 表头行
                XWPFTableRow appendixHeaderRow = appendixMeasurementTable.getRow(0);
                setRowHeight(appendixHeaderRow, 510);
                createTableCell(appendixHeaderRow.getCell(0), "弯头编号", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(1), "公称直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(2), "弧面直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(3), "侧面直径 (mm)", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(4), "测量圆度值", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(appendixHeaderRow.getCell(5), "允许圆度值", measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                
                // 添加数据行（固定8行）
                for (int i = 0; i < 8; i++) {
                    XWPFTableRow dataRow = appendixMeasurementTable.createRow();
                    setRowHeight(dataRow, 454);
                    
                    int measurementIndex = pageStart + i;
                    JsonNode rowData = measurementIndex < totalMeasurements ? measurementRows.get(measurementIndex) : null;
                    
                    String elbowNumber = "/";
                    String nominalDiameter = "/";
                    String arcDiameter = "/";
                    String sideDiameter = "/";
                    String measuredRoundness = "/";
                    String allowedRoundness = "/";
                    
                    if (rowData != null) {
                        // 提取弯头编号
                        if (rowData.has("弯头编号")) {
                            elbowNumber = rowData.get("弯头编号").asText();
                        }
                        
                        // 提取公称直径
                        if (rowData.has("公称直径 (mm)")) {
                            JsonNode d = rowData.get("公称直径 (mm)");
                            nominalDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        } else if (rowData.has("公称直径")) {
                            JsonNode d = rowData.get("公称直径");
                            nominalDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        }
                        
                        // 提取弧面直径
                        if (rowData.has("弧面直径 (mm)")) {
                            JsonNode d = rowData.get("弧面直径 (mm)");
                            arcDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        } else if (rowData.has("弧面直径")) {
                            JsonNode d = rowData.get("弧面直径");
                            arcDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        }
                        
                        // 提取侧面直径
                        if (rowData.has("侧面直径 (mm)")) {
                            JsonNode d = rowData.get("侧面直径 (mm)");
                            sideDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        } else if (rowData.has("侧面直径")) {
                            JsonNode d = rowData.get("侧面直径");
                            sideDiameter = d.isNumber() ? String.valueOf(d.asDouble()) : d.asText();
                        }
                        
                        // 提取测量圆度值
                        if (rowData.has("测量圆度值")) {
                            JsonNode r = rowData.get("测量圆度值");
                            measuredRoundness = r.isNumber() ? String.valueOf(r.asDouble()) : r.asText();
                        }
                        
                        // 提取允许圆度值
                        if (rowData.has("允许圆度值")) {
                            JsonNode r = rowData.get("允许圆度值");
                            allowedRoundness = r.isNumber() ? String.valueOf(r.asDouble()) : r.asText();
                        }
                    }
                    
                    createTableCell(dataRow.getCell(0), elbowNumber, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(1), nominalDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(2), arcDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(3), sideDiameter, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(4), measuredRoundness, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                    createTableCell(dataRow.getCell(5), allowedRoundness, measurementColWidth, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                }
                
                // ========== 签批行 ==========
                XWPFTable signTable_2 = document.createTable(1, 4);
                setupTableProperties(signTable_2, PT_TABLE_WIDTH);
                
                XWPFTableRow signRow1_2 = signTable_2.getRow(0);
                setRowHeight(signRow1_2, 454);
                createTableCell(signRow1_2.getCell(0), "编制/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(1), writeName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(2), "审核/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow1_2.getCell(3), reviewName, 2667, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);

                XWPFTableRow signRow2_2 = signTable_2.createRow();
                setRowHeight(signRow2_2, 454);
                createTableCell(signRow2_2.getCell(0), "批准/日期", 1847, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER);
                createTableCell(signRow2_2.getCell(1), approveName, 7181, ParagraphAlignment.CENTER, XWPFTableCell.XWPFVertAlign.CENTER, 3);

                // 添加换页符
                document.createParagraph().createRun().addBreak(BreakType.PAGE);
            }
        }

        // ========== 10. 附图附页（如果有imageAttachments） ==========
        generateImageAppendix(document, report, project, "圆度测量报告（附页）", RDM_DOC_NUMBER, false);

        log.debug("Completed generating Roundness Measurement report for report {}", report.getId());
    }

    /**
     * 生成总报告封皮页
     */
    private void generateCoverPage(XWPFDocument document, Project project) {
        try {
            // ========== 1. 报告编码（紧贴橙色区域上方，左对齐） ==========
            // ========== 在封皮页最开始添加5个空行 ==========
            for (int i = 0; i < 6; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20); // 20磅行间距
            }
            
            // ========== 1. 报告编码（紧贴橙色区域上方，左对齐） ==========
            XWPFParagraph topPara = document.createParagraph();
            topPara.setAlignment(ParagraphAlignment.LEFT); // 明确左对齐
            topPara.setSpacingBefore(0);
            topPara.setSpacingAfter(105); // 0.5行 = 10.5磅 × 0.5 × 20 twips/磅 = 105 twips
            topPara.setSpacingLineRule(LineSpacingRule.EXACT);
            topPara.setSpacingBetween(1.0);
            
            XWPFRun topRun = topPara.createRun();
            topRun.setFontFamily("微软雅黑");
            topRun.setFontSize(12);
            topRun.setText("          报告编码:" + project.getProjectNumber());
            
            // ========== 2. 中间橙色区域：项目名称（充满左右） ==========
            // 使用表格来实现橙色背景，充满页面宽度
            XWPFTable orangeTable = document.createTable(1, 1);
            
            // 封皮页使用0边距，所以表格宽度就是A4页面全宽
            int fullWidth = 11906; // A4页面宽度（twips）
            
            CTTblPr tblPr = orangeTable.getCTTbl().getTblPr();
            if (tblPr == null) {
                tblPr = orangeTable.getCTTbl().addNewTblPr();
            }
            CTTblWidth tblWidth = tblPr.isSetTblW() ? tblPr.getTblW() : tblPr.addNewTblW();
            tblWidth.setType(STTblWidth.DXA);
            tblWidth.setW(BigInteger.valueOf(fullWidth));
            
            // 设置表格对齐方式为左对齐
            CTJcTable jc = tblPr.isSetJc() ? tblPr.getJc() : tblPr.addNewJc();
            jc.setVal(STJcTable.LEFT);
            
            // 设置固定列宽布局
            CTTblLayoutType layoutType = tblPr.isSetTblLayout() ? tblPr.getTblLayout() : tblPr.addNewTblLayout();
            layoutType.setType(STTblLayoutType.FIXED);
            
            // 移除表格边框
            CTTblBorders borders = tblPr.isSetTblBorders() ? tblPr.getTblBorders() : tblPr.addNewTblBorders();
            setBorder(borders.addNewTop(), STBorder.NIL, 0);
            setBorder(borders.addNewBottom(), STBorder.NIL, 0);
            setBorder(borders.addNewLeft(), STBorder.NIL, 0);
            setBorder(borders.addNewRight(), STBorder.NIL, 0);
            setBorder(borders.addNewInsideH(), STBorder.NIL, 0);
            setBorder(borders.addNewInsideV(), STBorder.NIL, 0);
            
            // 设置表格行高（
            XWPFTableRow orangeRow = orangeTable.getRow(0);
            setRowHeight(orangeRow, 6000); // 
            
            XWPFTableCell orangeCell = orangeRow.getCell(0);
            
            // 设置单元格宽度为全宽
            CTTcPr tcPr = orangeCell.getCTTc().isSetTcPr() ? 
                orangeCell.getCTTc().getTcPr() : orangeCell.getCTTc().addNewTcPr();
            CTTblWidth cellWidth = tcPr.isSetTcW() ? tcPr.getTcW() : tcPr.addNewTcW();
            cellWidth.setType(STTblWidth.DXA);
            cellWidth.setW(BigInteger.valueOf(fullWidth));
               
            CTShd shd = tcPr.addNewShd();
            shd.setVal(STShd.CLEAR);     
            shd.setColor("auto");      
            shd.setFill("FE8514");     

            // 设置单元格垂直对齐为居中
            orangeCell.setVerticalAlignment(XWPFTableCell.XWPFVertAlign.CENTER);
            
            // 在单元格中添加项目名称
            XWPFParagraph projectNamePara = orangeCell.getParagraphs().isEmpty() ? 
                orangeCell.addParagraph() : orangeCell.getParagraphs().get(0);
            projectNamePara.setAlignment(ParagraphAlignment.CENTER);
            projectNamePara.setSpacingBefore(0);
            projectNamePara.setSpacingAfter(0);
            
            projectNamePara.setSpacingLineRule(LineSpacingRule.AUTO);
            projectNamePara.setSpacingBetween(1.3);
            
            // 清除段落背景色，确保单元格背景色显示
            // CTPPr paraPPr = projectNamePara.getCTP().isSetPPr() ? 
            //     projectNamePara.getCTP().getPPr() : projectNamePara.getCTP().addNewPPr();
            // if (paraPPr.isSetShd()) {
            //     paraPPr.unsetShd(); // 清除段落背景色
            // }
            
            // 第一行：客户方
            String customer = project.getCustomer();
            String customerText = (customer != null && !customer.isEmpty()) ? customer : "";
            String projectNameText = project.getProjectName();
            
            XWPFRun customerRun = projectNamePara.createRun();
            customerRun.setFontFamily("宋体");
            customerRun.setFontSize(26);
            customerRun.setBold(true);
            customerRun.setColor("FFFFFF");
            customerRun.setText(customerText);
            
            // 添加换行
            customerRun.addBreak();
            
            // 创建项目名称的Run
            XWPFRun projectNameRun = projectNamePara.createRun();
            projectNameRun.setFontFamily("宋体");
            projectNameRun.setFontSize(26);
            projectNameRun.setBold(true);
            projectNameRun.setColor("FFFFFF");
            projectNameRun.setText(projectNameText+"报告");
            
            // ========== 在橙色单元格下方添加灰色行 ==========
            XWPFTableRow grayRow = orangeTable.createRow();
           
            setRowHeight(grayRow, 500);
            
            XWPFTableCell grayCell = grayRow.getCell(0);
            
            // 设置灰色单元格宽度为全宽
            CTTcPr grayTcPr = grayCell.getCTTc().isSetTcPr() ? 
                grayCell.getCTTc().getTcPr() : grayCell.getCTTc().addNewTcPr();
            CTTblWidth grayCellWidth = grayTcPr.isSetTcW() ? grayTcPr.getTcW() : grayTcPr.addNewTcW();
            grayCellWidth.setType(STTblWidth.DXA);
            grayCellWidth.setW(BigInteger.valueOf(fullWidth));
            
            // 设置灰色单元格背景色
            CTShd grayShd = grayTcPr.addNewShd();
            grayShd.setVal(STShd.CLEAR);
            grayShd.setColor("auto");
            grayShd.setFill("d9d9d9"); 
            
            // 设置单元格垂直对齐为居中
            grayCell.setVerticalAlignment(XWPFTableCell.XWPFVertAlign.CENTER);
            
            // 清除段落背景色，确保单元格背景色显示
            // XWPFParagraph grayPara = grayCell.getParagraphs().isEmpty() ? 
            //     grayCell.addParagraph() : grayCell.getParagraphs().get(0);
            // grayPara.setAlignment(ParagraphAlignment.CENTER);
            // grayPara.setSpacingBefore(0);
            // grayPara.setSpacingAfter(0);
            
            // CTPPr grayParaPPr = grayPara.getCTP().isSetPPr() ? 
            //     grayPara.getCTP().getPPr() : grayPara.getCTP().addNewPPr();
            // if (grayParaPPr.isSetShd()) {
            //     grayParaPPr.unsetShd(); // 清除段落背景色
            // }
            
            // 添加一些空行，增加底部区域高度
            for (int i = 0; i < 7; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20);
            }
            
            // ========== 3. 底部区域：公司名称和日期 ==========
            // 公司名称
            XWPFParagraph companyPara = document.createParagraph();
            companyPara.setAlignment(ParagraphAlignment.CENTER);
            companyPara.setSpacingBefore(0);
            companyPara.setSpacingAfter(150);
            setExactLineSpacing(companyPara, 20);
            
            XWPFRun companyRun = companyPara.createRun();
            companyRun.setFontFamily("仿宋");
            companyRun.setFontSize(16);
            companyRun.setBold(true);
            companyRun.setText(brandingCompanyName());
            
            // 日期
            XWPFParagraph datePara = document.createParagraph();
            datePara.setAlignment(ParagraphAlignment.CENTER);
            datePara.setSpacingBefore(0);
            datePara.setSpacingAfter(0);
            setExactLineSpacing(datePara, 20);
            
            XWPFRun dateRun = datePara.createRun();
            dateRun.setFontFamily("仿宋");
            dateRun.setBold(true);
            dateRun.setFontSize(16);
            
            // 格式化日期为中文格式
            String chineseDate = formatChineseDate(project.getStartDate() != null ? 
                project.getStartDate() : LocalDate.now());
            dateRun.setText(chineseDate );
            
            // 
            CTP ctp = datePara.getCTP();
            CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
            // 如果已经存在SectPr，先删除再创建新的
            if (pPr.isSetSectPr()) {
                pPr.unsetSectPr();
            }
            CTSectPr breakSectPr = pPr.addNewSectPr(); // 在段落属性中创建分节符

            setSectPrPageSizeA4(breakSectPr, false);
            setSectPrMarginsCm(breakSectPr, 0, 0, 0, 0);
            CTSectType coverBreakType =
                    breakSectPr.isSetType() ? breakSectPr.getType() : breakSectPr.addNewType();
            coverBreakType.setVal(STSectionMark.NEXT_PAGE);
            // 此 sectPr 作用于「日期行之后」的新节，即声明页所在节（不是日期行之前的封皮页）。
            // 须绑定独立空白页眉/页脚 part，否则生成项目详情页后 Word 易将正文页眉页脚「同前节」串到声明页。
            bindEmptyHeaderFooterToSectPr(document, breakSectPr);

            // 第一节的函数中，不创建任何页眉页脚代码
            
        } catch (Exception e) {
            log.error("Error generating cover page", e);
            // 如果封皮页生成失败，继续生成其他内容
        }
    }

    /**
     * 生成声明页面
     */
    private void generateProjectSummaryPage(XWPFDocument document, Project project) {
        try {
            
            // ========== 1. 标题"声明" ==========
            XWPFParagraph titlePara = document.createParagraph();
            titlePara.setAlignment(ParagraphAlignment.CENTER);
            titlePara.setSpacingBefore(0);
            titlePara.setSpacingAfter(300); // 标题后间距
            titlePara.setSpacingLineRule(LineSpacingRule.EXACT);
            titlePara.setSpacingBetween(1.0);
            
            XWPFRun titleRun = titlePara.createRun();
            titleRun.setFontFamily("宋体");
            titleRun.setBold(true);
            titleRun.setFontSize(18);
            titleRun.setBold(true);
            titleRun.setText("声  明");
            
            // ========== 2. 添加空行作为间距 ==========
            // for (int i = 0; i < 2; i++) {
            //     XWPFParagraph emptyPara = document.createParagraph();
            //     emptyPara.setSpacingBefore(0);
            //     emptyPara.setSpacingAfter(0);
            //     setExactLineSpacing(emptyPara, 20);
            // }
            
            // ========== 3. 5个编号条款 ==========
            String[] clauses = {
                "1. 本技术报告的著作权属润电能源科学技术有限公司，未经我公司的书面许可，任何单位与人员不得部分复制本报告或擅自公开发表。",
                "2. 凡注明了密级的技术报告，任何部门与人员均不得私自对外提供，不得复制。",
                "3. 无润电能源科学技术有限公司报告/检验检测专用章的技术报告，不属我公司的正式技术报告。",
                "4. 对本技术报告有异议者，请于收到报告10日内与润电能源科学技术有限公司联系（电话：0371-88923099）。",
                "5. 润电能源科学技术有限公司投诉电话/传真：0371-88923099。"
            };
            
            for (int i = 0; i < clauses.length; i++) {
                XWPFParagraph clausePara = document.createParagraph();
                clausePara.setAlignment(ParagraphAlignment.LEFT);
                clausePara.setSpacingBefore(0);
                clausePara.setSpacingAfter(100); // 
                // 可选值：1.0=单倍，1.5=1.5倍，2.0=双倍，或使用EXACT配合固定磅值
                clausePara.setSpacingLineRule(LineSpacingRule.AUTO);
                clausePara.setSpacingBetween(1.5); 
                // 设置首行缩进2个字符（14号字体，2个字符 ≈ 560 twips）
                clausePara.setIndentationFirstLine(560);
                
                XWPFRun clauseRun = clausePara.createRun();
                clauseRun.setFontFamily("宋体");
                clauseRun.setFontSize(14);
                clauseRun.setText(clauses[i]);
            }
            //如果1个是 效率是3，钱是2.5  一个效率是2 ，钱是2，  总量是60
            //
            // ========== 4. 添加多个空行，将联系信息推到底部 ==========
            for (int i = 0; i < 10; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20);
            }
            
            // ========== 5. 底部公司联系信息 ==========
            String[] contactInfo = {
                "润电能源科学技术有限公司",
                "地址：河南省郑州市河南自贸试验区郑州片区（郑东）正光北街40号华能河南大厦3楼至6楼",
                "电话：（0371）88923000",
                "传真：（0371）88923150",
                "邮编：450018"
            };
            
            for (String info : contactInfo) {
                XWPFParagraph contactPara = document.createParagraph();
                contactPara.setAlignment(ParagraphAlignment.LEFT);
                contactPara.setSpacingBefore(0);
                contactPara.setSpacingAfter(60); // 联系信息之间的间距
                contactPara.setSpacingLineRule(LineSpacingRule.EXACT);
                contactPara.setSpacingBetween(1.0);
                // 设置左缩进8.72字符（14号字体：8.72 × 14磅 × 20 twips/磅 ≈ 2442 twips）
                // 使用左缩进可以让整个段落（包括第一行）都缩进
                contactPara.setIndentationLeft(2100);
                
                XWPFRun contactRun = contactPara.createRun();
                contactRun.setFontFamily("宋体");
                contactRun.setBold(true);
                contactRun.setFontSize(14);
                contactRun.setText(info);
            }

            // 添加分节符，创建第二节（声明页结束）
            XWPFParagraph breakPara = document.createParagraph();
            CTP ctp = breakPara.getCTP();
            CTPPr pPr = ctp.isSetPPr() ? ctp.getPPr() : ctp.addNewPPr();
            // 如果已经存在SectPr，先删除再创建新的
            if (pPr.isSetSectPr()) {
                pPr.unsetSectPr();
            }
            CTSectPr breakSectPr = pPr.addNewSectPr(); // 在段落属性中创建分节符

            CTSectType declBreakType =
                    breakSectPr.isSetType() ? breakSectPr.getType() : breakSectPr.addNewType();
            declBreakType.setVal(STSectionMark.NEXT_PAGE);

            // 设置第三节的页面属性（A4，默认边距）
            setSectPrPageSizeA4(breakSectPr, false);
            setSectPrMarginsCm(breakSectPr, 2.5, 2.5, 2.5, 2.5);

            // 项目详情及正文节的 sectPr（勿与 document.body.sectPr 混用，否则会全局套页眉页脚）
            SUMMARY_DECLARATION_BREAK_SECT_PR.set(breakSectPr);

            // 注意：不在这里创建页眉页脚，页眉页脚将在 generateProjectInfoPage 中创建
            
        } catch (Exception e) {
            log.error("Error generating project summary page", e);
            // 如果声明页生成失败，继续生成其他内容
        }
    }

    /**
     * 生成项目信息页面
     */
    private void generateProjectInfoPage(XWPFDocument document, Project project) {
        try {

            // 声明末 NEXT_PAGE 段上若创建「带内容」页眉，Word 常仍显示在声明页；此处只清 hdr/ftr 引用。
            // 正式页眉写在详情页首段 CONTINUOUS 分节上（详情～概述～单项～附录前）。
            CTSectPr declarationEndSectPr = SUMMARY_DECLARATION_BREAK_SECT_PR.get();
            if (declarationEndSectPr != null) {
                clearSectionHeaderFooterReferences(declarationEndSectPr);
                // Word 在当前结构下会把声明页计入该节的 PAGE 计数（即使声明页不显示页脚），
                // 为保证详情页显示为 1，这里将节起始页号设为 0：声明页=0（不展示），详情页=1。
                CTPageNumber mainBodyPageNumber =
                        declarationEndSectPr.isSetPgNumType()
                                ? declarationEndSectPr.getPgNumType()
                                : declarationEndSectPr.addNewPgNumType();
                mainBodyPageNumber.setStart(BigInteger.ZERO);
            } else {
                log.warn(
                        "SUMMARY_DECLARATION_BREAK_SECT_PR unset (declaration section break missing?) — "
                                + "cannot strip hdr/ftr from declaration break sectPr.");
            }

            // ========== 4. 添加空行（共三行） ==========
            for (int i = 0; i < 3; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20);
                emptyPara.setIndentationLeft(600);
            }


            // ========== 1. 项目名称（顶部） ==========
            // 第一行：项目名称（粗体）: 客户方（细体）
            XWPFParagraph projectNamePara = document.createParagraph();
            projectNamePara.setAlignment(ParagraphAlignment.LEFT);
            projectNamePara.setSpacingBefore(0);
            // 设置段落后间距为1.5倍行距（15号字体：15 × 1.5 = 22.5磅 = 450 twips）
            projectNamePara.setSpacingAfter(0);
            // 设置1.5倍行距（段内行距）
            projectNamePara.setSpacingLineRule(LineSpacingRule.AUTO);
            projectNamePara.setSpacingBetween(1.5);
            // 整体缩进2个字符（15号字体：2 × 15磅 × 20 twips/磅 = 600 twips）
            projectNamePara.setIndentationLeft(600);

            // 主正文页眉绑定到 body 末节（声明页末 NEXT_PAGE 之后的节），避免段落级 sectPr 把正文切成窄节。
            CTSectPr mainBodySectPr = document.getDocument().getBody().isSetSectPr()
                    ? document.getDocument().getBody().getSectPr()
                    : document.getDocument().getBody().addNewSectPr();
            setSectPrPageSizeA4(mainBodySectPr, false);
            setSectPrMarginsCm(mainBodySectPr, 2.6, 2.6, 2.5, 2.6);
            CTPageNumber pageNumber =
                    mainBodySectPr.isSetPgNumType()
                            ? mainBodySectPr.getPgNumType()
                            : mainBodySectPr.addNewPgNumType();
            pageNumber.setStart(BigInteger.valueOf(1));

            MAIN_BODY_HDR_SECT_PR.set(mainBodySectPr);
            createHeaderFooterForSection(document, mainBodySectPr, project.getProjectNumber());
            
            // "项目名称: 
            XWPFRun labelRun = projectNamePara.createRun();
            labelRun.setFontFamily("宋体");
            labelRun.setFontSize(15);
            labelRun.setBold(true);
            labelRun.setText("项目名称: ");
            
            // 客户方
            String customer = project.getCustomer() != null ? project.getCustomer() : "";
            XWPFRun customerRun = projectNamePara.createRun();
            customerRun.setFontFamily("宋体");
            customerRun.setFontSize(15);
            customerRun.setBold(false);
            customerRun.setText(customer);
            
            // 换行
            customerRun.addBreak();
            
            // 第二行：项目名称（细体，与第一行客户方对齐）
            // 在同一个段落中，通过添加空格来实现对齐（约6个字符的空格）
            XWPFRun projectNameRun2 = projectNamePara.createRun();
            projectNameRun2.setFontFamily("宋体");
            projectNameRun2.setFontSize(15);
            projectNameRun2.setBold(false);
            // 添加空格来对齐
            projectNameRun2.setText("          " + (project.getProjectName() != null ? project.getProjectName() : ""));
            
            // ========== 3. 报告详情字段 =========
            // 报告日期：优先使用无损检测编写日期，如果没有则使用理化检测编写日期
            LocalDate reportDate = project.getWriterDateNdt() != null ? project.getWriterDateNdt() : 
                                  (project.getWriterDateChem() != null ? project.getWriterDateChem() : null);
            String reportDateStr = reportDate != null ? 
                formatChineseDateFull(reportDate): "";
            addInfoField(document, "报告日期: ", reportDateStr);
            // 格式化工作时间：开始日期～结束日期

            String workTime = "";
            if (project.getStartDate() != null && project.getEndDate() != null) 
                {
                String startDate =  formatChineseDateFull(project.getStartDate());
                String endDate =  formatChineseDateFull(project.getEndDate());
                workTime = startDate + "～" + endDate;
            }

            addInfoField(document, "工作时间: ", workTime);
            addInfoField(document, "项目负责: ", project.getResponsiblePerson() != null ? project.getResponsiblePerson() : "");
            addInfoField(document, "工作人员: ", project.getStaff() != null ? project.getStaff() : "");
            addInfoField(document, "客 户 方: ", project.getCustomerContact() != null ? project.getCustomerContact() : "");
            
            // ========== 4. 添加空行 ==========
            for (int i = 0; i < 2; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20);
                // 整体缩进2个字符
                emptyPara.setIndentationLeft(600);
            }
            
            // ========== 5. 审批/签名部分（仅已完成项目展示签名） ==========
            if (project.getStatus() != null && "Completed".equals(project.getStatus())) {
                ProjectPersonnelInfo personnelInfo = getProjectPersonnelInfo(project);
                addInfoFieldWithTwoPersons(document, "  批  准:", personnelInfo.approverNdt, personnelInfo.approverChem, personnelInfo.approvalDate, 22);
                for (int i = 0; i < 2; i++) {
                    XWPFParagraph emptyPara = document.createParagraph();
                    emptyPara.setSpacingBefore(0);
                    emptyPara.setSpacingAfter(0);
                    setExactLineSpacing(emptyPara, 20);
                    emptyPara.setIndentationLeft(600);
                }
                addInfoFieldWithTwoPersons(document, "  审  核:", personnelInfo.reviewerNdt, personnelInfo.reviewerChem, personnelInfo.reviewDate, 22);
                for (int i = 0; i < 2; i++) {
                    XWPFParagraph emptyPara = document.createParagraph();
                    emptyPara.setSpacingBefore(0);
                    emptyPara.setSpacingAfter(0);
                    setExactLineSpacing(emptyPara, 20);
                    emptyPara.setIndentationLeft(600);
                }
                addInfoFieldWithTwoPersons(document, "  编  写:", personnelInfo.writerNdt, personnelInfo.writerChem, personnelInfo.writerDate, 22);
            }
            // ========== 6. 添加空行，将声明推到底部 ==========
            for (int i = 0; i < 3; i++) {
                XWPFParagraph emptyPara = document.createParagraph();
                emptyPara.setSpacingBefore(0);
                emptyPara.setSpacingAfter(0);
                setExactLineSpacing(emptyPara, 20);
                // 整体缩进2个字符
                emptyPara.setIndentationLeft(600);
            }
            
            // ========== 7. 底部声明部分 ==========
            XWPFParagraph declarationPara = document.createParagraph();
            declarationPara.setAlignment(ParagraphAlignment.CENTER);
            declarationPara.setSpacingBefore(0);
            declarationPara.setSpacingAfter(120);
            // 设置1.5倍行距
            declarationPara.setSpacingLineRule(LineSpacingRule.AUTO);
            declarationPara.setSpacingBetween(1.5);
            // 整体缩进2个字符
            declarationPara.setIndentationLeft(400);
            
            XWPFRun declarationRun = declarationPara.createRun();
            declarationRun.setFontFamily("宋体");
            declarationRun.setFontSize(12);
           
            declarationRun.setText("声明:本报告中涉及打印人员姓名均经本人认可授权。");
            
            // ========== 8. "(章)" 居中显示 ==========
            XWPFParagraph sealPara = document.createParagraph();
            sealPara.setAlignment(ParagraphAlignment.CENTER);
            sealPara.setSpacingBefore(0);
            sealPara.setSpacingAfter(0);
            sealPara.setSpacingLineRule(LineSpacingRule.EXACT);
            sealPara.setSpacingBetween(1.0);
            
            XWPFRun sealRun = sealPara.createRun();
            sealRun.setFontFamily("宋体");
            sealRun.setFontSize(12);
            sealRun.setText("(章)");
            
            //添加换页符
            document.createParagraph().createRun().addBreak(BreakType.PAGE);
        } catch (Exception e) {
            log.error("Error generating project info page", e);
            // 如果项目信息页生成失败，继续生成其他内容
        }
    }
    
    /**
     * 生成第一个单项报告摘要界面（概述使用项目报告默认顺序）。
     */
    private void generateReportSummary(XWPFDocument document, Project project) {
        generateReportSummary(document, project, null);
    }

    /**
     * 生成第一个单项报告摘要界面。
     * 若 orderedReports 非 null，概述数据按该顺序收集，与报告编号一致。
     */
    private void generateReportSummary(XWPFDocument document, Project project, List<Report> orderedReports) {
        try {
            String commissionText = buildSummaryCommissionParagraph(project);

            // ========== 1. 标题"声明" ==========
            XWPFParagraph titlePara = document.createParagraph();
            titlePara.setAlignment(ParagraphAlignment.CENTER);
            titlePara.setSpacingBefore(0);
            titlePara.setSpacingAfter(300); // 标题后间距
            titlePara.setSpacingLineRule(LineSpacingRule.EXACT);
            titlePara.setSpacingBetween(1.0);
            
            XWPFRun titleRun = titlePara.createRun();
            titleRun.setFontFamily("宋体");
            titleRun.setBold(true);
            titleRun.setFontSize(18);
            titleRun.setBold(true);
            titleRun.setText("摘 要");
            // ========== 2. 委托信息 ==========
            addIndentedParagraph(document, commissionText);
            //addParagraph(document, commissionText);

            // 按类别+检测类型收集报告数据（若传入概述顺序列表则与之一致）
            CategoryTypeReportData categoryTypeData = orderedReports != null
                    ? collectComponentReportDataByCategoryAndType(project, orderedReports)
                    : collectComponentReportDataByCategoryAndType(project);
            List<SummaryTocEntry> summaryTocPlan = buildSummaryTocOutline(categoryTypeData);

            // ========== 3. 目录 + 概述部分（目录另起一页） ==========
            document.createParagraph().createRun().addBreak(BreakType.PAGE);
            generateSummaryTocPage(document, summaryTocPlan);
            document.createParagraph().createRun().addBreak(BreakType.PAGE);
            // ========== 1. 标题"声明" ==========

            // XWPFParagraph titlePara1 = document.createParagraph();
            // titlePara1.setAlignment(ParagraphAlignment.CENTER);
            // titlePara1.setSpacingBefore(0);
            // titlePara1.setSpacingAfter(300); // 标题后间距
            // titlePara1.setSpacingLineRule(LineSpacingRule.EXACT);
            // titlePara1.setSpacingBetween(1.0);
            
            // XWPFRun titleRun1 = titlePara1.createRun();
            // titleRun1.setFontFamily("宋体");
            // titleRun1.setBold(true);
            // titleRun1.setFontSize(18);
            // titleRun1.setBold(true);
            // titleRun1.setText("概 述");
            
            /* 摘要书签数字 id 从较大值起算，降低与文档其它书签冲突概率 */
            AtomicInteger summaryBookmarkIdGen = new AtomicInteger(100000);
            LinkedList<SummaryTocEntry> summaryTocQueue = new LinkedList<>(summaryTocPlan);

            // 1 概述（标题 + 项目描述）
            generateOverview(document, project, summaryTocQueue, summaryBookmarkIdGen);

            // 2 发现问题及处理情况（原 2 检测主要问题）
            generateMainProblems(document, categoryTypeData, summaryTocQueue, summaryBookmarkIdGen);

            // 3 工作内容（原 1 检测内容）
            generateDetectionContent(document, categoryTypeData, summaryTocQueue, summaryBookmarkIdGen);

            // 4 缺陷通知单（仅标题，占位）
            generateDefectNoticeSection(document, summaryTocQueue, summaryBookmarkIdGen);

            insertUploadedAfterDefectNoticeSection(document, project);
            //添加分页符
            document.createParagraph().createRun().addBreak(BreakType.PAGE);

            // 5 分项报告（仅标题，占位）
            generateSubReportsSection(document, summaryTocQueue, summaryBookmarkIdGen);
            if (!summaryTocQueue.isEmpty()) {
                log.warn("Summary TOC bookmark queue not fully consumed: {} entries left", summaryTocQueue.size());
            }

        } catch (Exception e) {
            log.error("Error generating report summary", e);
            // 如果摘要生成失败，继续生成其他内容
        }
    }

    private void insertUploadedAfterDefectNoticeSection(XWPFDocument document, Project project) throws Exception {
        appendUploadedSummaryAttachment(document, project.getSummaryNotificationSignedRelPath());
    }

    private void appendUploadedThirdPartyFullAtEnd(XWPFDocument document, Project project) throws Exception {
        String relPath = project.getSummaryThirdPartyFullRelPath();
        if (relPath == null || relPath.trim().isEmpty()) {
            return;
        }
        Path attachmentPath = resolveSummaryAttachmentPath(relPath);
        if (!Files.exists(attachmentPath)) {
            throw new IllegalArgumentException("第三方报告完整版不存在，请重新上传 PDF 后再生成");
        }
        String lowerName = attachmentPath.getFileName().toString().toLowerCase();
        if (!lowerName.endsWith(".pdf")) {
            throw new IllegalArgumentException("第三方报告完整版请上传 PDF 版本，以保持原始版式和页眉页脚");
        }
        beginAppendixSectionWithoutHeaderFooter(document);
        SummaryWordAppendUtil.appendPdfPagesAsImages(document, attachmentPath);
        syncBodySectPrForAppendixWithoutHeaderFooter(document);
    }

    private void appendUploadedSummaryAttachment(XWPFDocument document, String relativePath) throws Exception {
        if (relativePath == null || relativePath.trim().isEmpty()) {
            return;
        }
        Path attachmentPath = resolveSummaryAttachmentPath(relativePath);
        if (!Files.exists(attachmentPath)) {
            throw new IllegalArgumentException("总报告附件不存在，请重新上传后再生成");
        }
        String lowerName = attachmentPath.getFileName().toString().toLowerCase();
        if (lowerName.endsWith(".docx")) {
            SummaryWordAppendUtil.appendDocxBody(document, attachmentPath);
            restoreSummaryDocumentSectionDefaults(document);
            return;
        }
        if (lowerName.endsWith(".pdf")) {
            SummaryWordAppendUtil.appendPdfPagesAsImages(document, attachmentPath);
            return;
        }
        throw new IllegalArgumentException("当前仅支持 docx 或 pdf 总报告附件");
    }

    private Path resolveSummaryAttachmentPath(String relativePath) {
        return Paths.get(uploadDir).resolve(relativePath).normalize();
    }

    /**
     * 追加外部 DOCX 后，重新加固总报告末节的默认纸张与页边距，避免被附件残留样式污染。
     */
    private void restoreSummaryDocumentSectionDefaults(XWPFDocument document) {
        setPageSizeA4(document, false);
        setDocumentMarginsCm(document, 2.6, 2.6, 2.5, 2.6);
    }

    /** 多选部件分组键：与前端 aggregateDetectionLogOrder.ts 的 componentGroupKey 保持一致。 */
    private String buildComponentGroupKey(Report report, List<ProjectComponent> components) {
        List<Integer> ids = new ArrayList<>();
        if (components != null) {
            for (ProjectComponent c : components) {
                if (c != null && c.getId() != null) {
                    ids.add(c.getId());
                }
            }
        }
        if (ids.isEmpty() && report.getProjectComponentId() != null) {
            ids.add(report.getProjectComponentId());
        }
        if (ids.isEmpty()) {
            return "none";
        }
        ids.sort(Integer::compareTo);
        return ids.stream().map(String::valueOf).collect(Collectors.joining(","));
    }

    private String normalizeComponentNameForGroupSort(String raw) {
        if (raw == null) {
            return "";
        }
        String t = raw.trim();
        if (t.isEmpty()) {
            return "";
        }
        String s = t;
        for (;;) {
            Matcher m = COMPONENT_NAME_LEADING_NUMBER_SIGN.matcher(s);
            if (!m.find() || m.start() != 0) {
                break;
            }
            s = s.substring(m.end()).trim();
        }
        return s.isEmpty() ? t : s;
    }

    private static String overviewNamePrefix2(String normalizedName) {
        if (normalizedName == null || normalizedName.isEmpty()) {
            return "";
        }
        int end = Math.min(2, normalizedName.length());
        return normalizedName.substring(0, end);
    }

    private Map<Integer, ProjectComponent> loadProjectComponentsByIdMap(Integer projectId) {
        if (projectId == null) {
            return Collections.emptyMap();
        }
        List<ProjectComponent> list = projectComponentRepository.findByProjectId(projectId);
        Map<Integer, ProjectComponent> m = new HashMap<>();
        for (ProjectComponent c : list) {
            if (c.getId() != null) {
                m.put(c.getId(), c);
            }
        }
        return m;
    }

    private List<Integer> parseOverviewComponentGroupIds(String componentGroupKey) {
        if (componentGroupKey == null || componentGroupKey.isEmpty() || "none".equals(componentGroupKey)) {
            return Collections.emptyList();
        }
        List<Integer> out = new ArrayList<>();
        for (String part : componentGroupKey.split(",")) {
            String p = part.trim();
            if (p.isEmpty()) {
                continue;
            }
            try {
                out.add(Integer.parseInt(p));
            } catch (NumberFormatException ignored) {
                // skip malformed segment
            }
        }
        return out;
    }

    /**
     * 同类内部件组排序：规范化名上的 min 前两字、min 全名、min 部件 ID；none 垫底（与 aggregateDetectionLogOrder.compareComponentGroupKeysForOverview 对齐）。
     */
    private int compareOverviewComponentGroupKeys(
            String keyA, String keyB, Map<Integer, ProjectComponent> componentsById) {
        boolean na = "none".equals(keyA);
        boolean nb = "none".equals(keyB);
        if (na && nb) {
            return 0;
        }
        if (na) {
            return 1;
        }
        if (nb) {
            return -1;
        }

        OverviewGroupSortTriple ta = overviewGroupSortTriple(keyA, componentsById);
        OverviewGroupSortTriple tb = overviewGroupSortTriple(keyB, componentsById);

        int c = ZH_CN_COLLATOR.compare(ta.minPrefix2, tb.minPrefix2);
        if (c != 0) {
            return c;
        }
        c = ZH_CN_COLLATOR.compare(ta.minFullName, tb.minFullName);
        if (c != 0) {
            return c;
        }
        return Integer.compare(ta.minComponentId, tb.minComponentId);
    }

    private OverviewGroupSortTriple overviewGroupSortTriple(
            String componentGroupKey, Map<Integer, ProjectComponent> componentsById) {
        List<Integer> ids = parseOverviewComponentGroupIds(componentGroupKey);
        String minPrefix = "";
        String minFull = "";
        int minId = Integer.MAX_VALUE;
        boolean first = true;
        for (Integer id : ids) {
            minId = Math.min(minId, id);
            ProjectComponent pc = componentsById.get(id);
            String norm = normalizeComponentNameForGroupSort(pc != null ? pc.getComponentName() : null);
            String p2 = overviewNamePrefix2(norm);
            if (first) {
                minPrefix = p2;
                minFull = norm;
                first = false;
            } else {
                if (ZH_CN_COLLATOR.compare(p2, minPrefix) < 0) {
                    minPrefix = p2;
                }
                if (ZH_CN_COLLATOR.compare(norm, minFull) < 0) {
                    minFull = norm;
                }
            }
        }
        if (minId == Integer.MAX_VALUE) {
            minId = 0;
        }
        return new OverviewGroupSortTriple(minPrefix, minFull, minId);
    }

    private static final class OverviewGroupSortTriple {
        final String minPrefix2;
        final String minFullName;
        final int minComponentId;

        OverviewGroupSortTriple(String minPrefix2, String minFullName, int minComponentId) {
            this.minPrefix2 = minPrefix2;
            this.minFullName = minFullName;
            this.minComponentId = minComponentId;
        }
    }

    private List<Report> applyAggregateDetectionLogOrder(
            Project project,
            List<Report> defaultOrderedReports,
            List<OrderedReportContext> defaultOrderedContexts) {
        if (defaultOrderedReports.isEmpty()) {
            return defaultOrderedReports;
        }
        String savedOrderJson = project.getAggregateDetectionLogOrder();
        if (savedOrderJson == null || savedOrderJson.trim().isEmpty()) {
            return defaultOrderedReports;
        }
        try {
            JsonNode root = objectMapper.readTree(savedOrderJson);
            JsonNode componentKeysNode = root.path("componentKeys");
            JsonNode reportIdsByComponentNode = root.path("reportIdsByComponent");
            if (!componentKeysNode.isArray() || !reportIdsByComponentNode.isObject()) {
                return defaultOrderedReports;
            }

            Map<Integer, ProjectComponent> componentsByIdForOrder =
                    loadProjectComponentsByIdMap(project.getId());

            Map<String, List<OrderedReportContext>> defaultsByComponent = new LinkedHashMap<>();
            for (OrderedReportContext ctx : defaultOrderedContexts) {
                defaultsByComponent.computeIfAbsent(ctx.componentGroupKey, k -> new ArrayList<>()).add(ctx);
            }

            List<String> mergedComponentKeys = new ArrayList<>();
            Set<String> seenKeys = new LinkedHashSet<>();
            for (JsonNode keyNode : componentKeysNode) {
                if (!keyNode.isTextual()) continue;
                String key = keyNode.asText();
                if (defaultsByComponent.containsKey(key) && seenKeys.add(key)) {
                    mergedComponentKeys.add(key);
                }
            }
            List<String> appendKeysNotInSaved = new ArrayList<>();
            for (String key : defaultsByComponent.keySet()) {
                if (!seenKeys.contains(key)) {
                    appendKeysNotInSaved.add(key);
                }
            }
            appendKeysNotInSaved.sort(
                    (a, b) -> compareOverviewComponentGroupKeys(a, b, componentsByIdForOrder));
            for (String key : appendKeysNotInSaved) {
                mergedComponentKeys.add(key);
                seenKeys.add(key);
            }

            List<String> customTypeOrder = parseExperimentTypeOrderFromProject(project);

            List<Report> result = new ArrayList<>();
            Set<Integer> consumedReportIds = new LinkedHashSet<>();
            for (String componentKey : mergedComponentKeys) {
                List<OrderedReportContext> defaultList = defaultsByComponent.get(componentKey);
                if (defaultList == null || defaultList.isEmpty()) {
                    continue;
                }

                Map<Integer, OrderedReportContext> byId = new HashMap<>();
                List<OrderedReportContext> nullIdList = new ArrayList<>();
                for (OrderedReportContext ctx : defaultList) {
                    Integer rid = ctx.report.getId();
                    if (rid == null) {
                        nullIdList.add(ctx);
                    } else {
                        byId.put(rid, ctx);
                    }
                }

                JsonNode savedIdsNode = reportIdsByComponentNode.path(componentKey);
                List<Integer> mergedIds = new ArrayList<>();
                if (savedIdsNode.isArray()) {
                    for (JsonNode idNode : savedIdsNode) {
                        if (!idNode.canConvertToInt()) continue;
                        int rid = idNode.asInt();
                        if (byId.containsKey(rid) && !mergedIds.contains(rid)) {
                            mergedIds.add(rid);
                        }
                    }
                }
                for (OrderedReportContext ctx : defaultList) {
                    Integer rid = ctx.report.getId();
                    if (rid != null && !mergedIds.contains(rid)) {
                        mergedIds.add(rid);
                    }
                }

                mergedIds.sort((rid1, rid2) -> {
                    OrderedReportContext c1 = byId.get(rid1);
                    OrderedReportContext c2 = byId.get(rid2);
                    if (c1 == null && c2 == null) {
                        return 0;
                    }
                    if (c1 == null) {
                        return 1;
                    }
                    if (c2 == null) {
                        return -1;
                    }
                    int t = Integer.compare(
                            getExperimentTypeOrderIndex(c1.experimentTypeName, customTypeOrder),
                            getExperimentTypeOrderIndex(c2.experimentTypeName, customTypeOrder));
                    if (t != 0) {
                        return t;
                    }
                    t = Comparator.nullsLast(String::compareTo).compare(
                            c1.report.getReportNumber(), c2.report.getReportNumber());
                    if (t != 0) {
                        return t;
                    }
                    return Comparator.nullsLast(Integer::compareTo)
                            .compare(c1.report.getId(), c2.report.getId());
                });

                for (Integer rid : mergedIds) {
                    OrderedReportContext ctx = byId.get(rid);
                    if (ctx != null) {
                        result.add(ctx.report);
                        consumedReportIds.add(rid);
                    }
                }
                for (OrderedReportContext ctx : nullIdList) {
                    result.add(ctx.report);
                }
            }

            if (result.isEmpty()) {
                return defaultOrderedReports;
            }
            for (Report report : defaultOrderedReports) {
                Integer rid = report.getId();
                if ((rid != null && !consumedReportIds.contains(rid)) || !result.contains(report)) {
                    result.add(report);
                }
            }
            return result;
        } catch (Exception ex) {
            log.warn("Failed to parse aggregateDetectionLogOrder for project {}: {}", project.getId(), ex.getMessage());
            return defaultOrderedReports;
        }
    }

    /**
     * 按统一规则返回报告顺序（摘要/单项/总日志/编号共用）：
     * 1) 类别：CATEGORY_ORDER + 自定义类拼音序（与前端 sortCategoriesForOverview 一致）
     * 2) 部件组：同类内按规范化部件名的 min 前两字、min 全名、min 部件 ID（none 垫底），可被 aggregateDetectionLogOrder.componentKeys 覆盖
     * 3) 组内报告：检测类型顺序 + 报告编号 + ID 稳定排序，可被 reportIdsByComponent 覆盖
     */
    private List<Report> getReportsInOverviewOrder(Project project) {
        if (project.getReports() == null || project.getReports().isEmpty()) {
            return new ArrayList<>();
        }
        Map<Integer, ProjectComponent> componentsByIdForOrder = loadProjectComponentsByIdMap(project.getId());
        Map<String, LinkedHashMap<String, List<OrderedReportContext>>> categoryToComponentToReports = new LinkedHashMap<>();
        int sourceIndex = 0;
        for (Report report : project.getReports()) {
            try {
                List<ProjectComponent> components = resolveComponentsForReport(report);
                ProjectComponent component = components.isEmpty() ? null : components.get(0);
                String componentName = null;
                if (component != null) {
                    componentName = component.getComponentName();
                }
                if (componentName == null || componentName.trim().isEmpty()) {
                    componentName = report.getComponentName();
                }
                if (componentName == null || componentName.trim().isEmpty()) {
                    componentName = "{需要填写部件名称}";
                }
                String category = (component != null && component.getCategory() != null && !component.getCategory().trim().isEmpty())
                        ? component.getCategory().trim() : "其他";
                ExperimentType experimentType = resolveExperimentTypeForReport(report);
                String experimentTypeName = experimentType != null ? experimentType.getName() : report.getTestMethod();
                String componentGroupKey = buildComponentGroupKey(report, components);

                OrderedReportContext ctx = new OrderedReportContext();
                ctx.report = report;
                ctx.componentGroupKey = componentGroupKey;
                ctx.experimentTypeName = experimentTypeName;
                ctx.sourceIndex = sourceIndex++;

                categoryToComponentToReports
                        .computeIfAbsent(category, k -> new LinkedHashMap<>())
                        .computeIfAbsent(componentGroupKey, k -> new ArrayList<>())
                        .add(ctx);
            } catch (Exception e) {
                log.warn("Error grouping report {} for overview order: {}", report.getId(), e.getMessage());
            }
        }

        List<String> customTypeOrder = parseExperimentTypeOrderFromProject(project);
        Comparator<OrderedReportContext> reportComparator = Comparator
                .comparingInt((OrderedReportContext c) -> getExperimentTypeOrderIndex(c.experimentTypeName, customTypeOrder))
                .thenComparing(c -> c.report.getReportNumber(), Comparator.nullsLast(Comparator.naturalOrder()))
                .thenComparing(c -> c.report.getId(), Comparator.nullsLast(Comparator.naturalOrder()))
                .thenComparingInt(c -> c.sourceIndex);

        List<OrderedReportContext> orderedContexts = new ArrayList<>();
        List<String> categoryOrder = sortCategoriesForOverview(categoryToComponentToReports.keySet());
        for (String category : categoryOrder) {
            LinkedHashMap<String, List<OrderedReportContext>> compToReports = categoryToComponentToReports.get(category);
            if (compToReports == null) continue;
            List<Map.Entry<String, List<OrderedReportContext>>> sortedComponentEntries =
                    new ArrayList<>(compToReports.entrySet());
            sortedComponentEntries.sort(
                    (e1, e2) -> compareOverviewComponentGroupKeys(
                            e1.getKey(), e2.getKey(), componentsByIdForOrder));
            for (Map.Entry<String, List<OrderedReportContext>> entry : sortedComponentEntries) {
                List<OrderedReportContext> list = new ArrayList<>(entry.getValue());
                list.sort(reportComparator);
                orderedContexts.addAll(list);
            }
        }

        List<Report> defaultOrderedReports = orderedContexts.stream()
                .map(ctx -> ctx.report)
                .collect(Collectors.toList());
        return applyAggregateDetectionLogOrder(project, defaultOrderedReports, orderedContexts);
    }

    /**
     * 按概述顺序（与 getReportsInOverviewOrder 一致）扫描各条报告并持久化编号：
     */
    private void syncReportNumbersToOverviewOrder(Project project, List<Report> orderedReports) {
        if (orderedReports == null || orderedReports.isEmpty()) {
            return;
        }
        assignOverviewReportNumbersInMemory(project, orderedReports);
        reportRepository.saveAll(orderedReports);
    }

    /** 与 {@link #syncReportNumbersToOverviewOrder} 相同规则，仅改内存不写库（概述预览用）。 */
    private void assignOverviewReportNumbersInMemory(Project project, List<Report> orderedReports) {
        if (orderedReports == null || orderedReports.isEmpty()) {
            return;
        }
        String pn = project.getProjectNumber() != null ? project.getProjectNumber().trim() : "";

        boolean needRunDian = false;
        boolean needThirdParty = false;
        for (Report r : orderedReports) {
            if (usesThirdPartyBranding(project, r)) {
                needThirdParty = true;
            } else {
                needRunDian = true;
            }
        }
        if (needRunDian && pn.isEmpty() && !needThirdParty) {
            return;
        }

        String effectiveTpBase = ThirdPartyPlaceholders.effectiveThirdPartyProjectNumberBase(
                project.getThirdPartyProjectNumber());

        int runDianSeq = 1;
        int thirdPartySeq = 1;
        boolean huatuPerType = ThirdPartyReportNumbering.usesPerTypeNumbering(project.getThirdPartyName());
        Map<String, Integer> thirdPartyTypeSeq = huatuPerType ? new HashMap<>() : null;
        for (Report report : orderedReports) {
            if (usesThirdPartyBranding(project, report)) {
                if (huatuPerType) {
                    String typeCode = resolveExperimentTypeCodeForReport(report);
                    int seq = thirdPartyTypeSeq.merge(typeCode, 1, Integer::sum);
                    report.setReportNumber(ThirdPartyReportNumbering.formatHuatuNumber(
                            effectiveTpBase, typeCode, seq));
                } else {
                    report.setReportNumber(ThirdPartyReportNumbering.formatLegacyNumber(
                            effectiveTpBase, thirdPartySeq++));
                }
            } else {
                if (pn.isEmpty()) {
                    continue;
                }
                report.setReportNumber(pn + "-" + String.format("%03d", runDianSeq++));
            }
        }
    }

    private String buildSummaryCommissionParagraph(Project project) {
        String workPeriod = "";
        if (project.getStartDate() != null) {
            String startDateStr = formatDateForSummary(project.getStartDate());
            if (project.getEndDate() != null) {
                workPeriod = startDateStr + "～" + formatDateForSummary(project.getEndDate());
            } else {
                workPeriod = startDateStr;
            }
        } else {
            workPeriod = "{需要填写开始日期}";
        }
        String customerName = project.getCustomerName();
        if (customerName == null || customerName.trim().isEmpty()) {
            customerName = "{需要填写客户方名称}";
        }
        String projectName = project.getProjectName();
        if (projectName == null || projectName.trim().isEmpty()) {
            projectName = "{需要填写项目名称}";
        }
        return "受" + customerName + "委托，依据本次检修工作项目表，参照华润电力控股有限公司企业标准Q/CRP 1108.05.01-2025《火力发电厂金属技术监督规程》和DL/T 438-2023《火力发电厂金属技术监督规程》，润电能源科学技术有限公司于"
                + workPeriod + "开展" + projectName + "，详细检测情况见单项检测报告。";
    }

    /**
     * 概述数据准备：顺序、编号、收集。{@code persistReportNumbers=true} 与总报告 Word 生成一致并写库。
     */
    private CategoryTypeReportData prepareOverviewCategoryTypeData(Project project, boolean persistReportNumbers) {
        ensureProjectReportsLoadedForWord(project);
        List<Report> orderedReports = getReportsInOverviewOrder(project);
        if (persistReportNumbers) {
            syncReportNumbersToOverviewOrder(project, orderedReports);
        } else {
            assignOverviewReportNumbersInMemory(project, orderedReports);
        }
        return collectComponentReportDataByCategoryAndType(project, orderedReports);
    }

    private static boolean overviewHasAnyDefect(CategoryTypeReportData data) {
        return data.categoryToComponentToReports.values().stream()
                .flatMap(m -> m.values().stream())
                .flatMap(List::stream)
                .anyMatch(r -> r.hasDefect);
    }

    /** 与 {@link #generateMainProblems} 条目同源 */
    private List<OverviewChapterCategory> buildOverviewChapter2Categories(CategoryTypeReportData data) {
        List<OverviewChapterCategory> result = new ArrayList<>();
        if (!overviewHasAnyDefect(data)) {
            return result;
        }
        Map<String, Map<String, List<ReportInfo>>> catToComp = data.categoryToComponentToReports;
        int categoryIndex = 0;
        for (String category : catToComp.keySet()) {
            Map<String, List<ReportInfo>> compToReports = catToComp.get(category);
            if (compToReports == null) {
                continue;
            }
            if (compToReports.values().stream().flatMap(List::stream).noneMatch(r -> r.hasDefect)) {
                continue;
            }
            categoryIndex++;
            OverviewChapterCategory cat = new OverviewChapterCategory(category, categoryIndex);
            int componentIndex = 0;
            for (Map.Entry<String, List<ReportInfo>> entry : compToReports.entrySet()) {
                String componentName = entry.getKey();
                List<ReportInfo> defectReports = entry.getValue().stream()
                        .filter(r -> r.hasDefect).collect(Collectors.toList());
                if (defectReports.isEmpty()) {
                    continue;
                }
                componentIndex++;
                OverviewChapterComponent comp = new OverviewChapterComponent(componentName, componentIndex);
                int reportIndex = 0;
                for (ReportInfo ri : defectReports) {
                    reportIndex++;
                    comp.items.add(new OverviewChapterItem(
                            "2." + categoryIndex + "." + componentIndex + "." + reportIndex,
                            formatOverviewChapter2ProblemText(ri, componentName)));
                }
                cat.components.add(comp);
            }
            result.add(cat);
        }
        return result;
    }

    /** 与 {@link #generateDetectionContent} 条目同源 */
    private List<OverviewChapterCategory> buildOverviewChapter3Categories(CategoryTypeReportData data) {
        List<OverviewChapterCategory> result = new ArrayList<>();
        Map<String, Map<String, List<ReportInfo>>> catToComp = data.categoryToComponentToReports;
        int categoryIndex = 0;
        for (String category : catToComp.keySet()) {
            Map<String, List<ReportInfo>> compToReports = catToComp.get(category);
            if (compToReports == null || compToReports.isEmpty()) {
                continue;
            }
            categoryIndex++;
            OverviewChapterCategory cat = new OverviewChapterCategory(category, categoryIndex);
            int componentIndex = 0;
            for (Map.Entry<String, List<ReportInfo>> compEntry : compToReports.entrySet()) {
                String componentName = compEntry.getKey();
                List<ReportInfo> reports = compEntry.getValue();
                if (reports == null || reports.isEmpty()) {
                    continue;
                }
                componentIndex++;
                OverviewChapterComponent comp = new OverviewChapterComponent(componentName, componentIndex);
                int reportIndex = 0;
                for (ReportInfo ri : reports) {
                    reportIndex++;
                    comp.items.add(new OverviewChapterItem(
                            "3." + categoryIndex + "." + componentIndex + "." + reportIndex,
                            formatOverviewChapter3WorkLine(ri)));
                }
                cat.components.add(comp);
            }
            result.add(cat);
        }
        return result;
    }

    private OverviewSummaryContent buildOverviewSummaryContent(Project project, boolean persistReportNumbers) {
        CategoryTypeReportData data = prepareOverviewCategoryTypeData(project, persistReportNumbers);
        return new OverviewSummaryContent(
                buildSummaryCommissionParagraph(project),
                project.getDescription() != null ? project.getDescription().trim() : "",
                overviewHasAnyDefect(data),
                buildOverviewChapter2Categories(data),
                buildOverviewChapter3Categories(data));
    }

    private ProjectOverviewPreviewDTO toOverviewPreviewDto(OverviewSummaryContent content) {
        ProjectOverviewPreviewDTO dto = new ProjectOverviewPreviewDTO();
        dto.setAbstractParagraph(content.abstractParagraph());
        dto.setSection1Body(content.section1Body());
        dto.setShowChapter2(content.showChapter2());

        Map<String, OverviewPreviewCategoryDTO> merged = new java.util.LinkedHashMap<>();
        for (OverviewChapterCategory cat : content.chapter2Categories()) {
            OverviewPreviewCategoryDTO catDto = merged.computeIfAbsent(cat.category, k -> {
                OverviewPreviewCategoryDTO c = new OverviewPreviewCategoryDTO();
                c.setCategory(k);
                return c;
            });
            catDto.setChapter2CategoryIndex(cat.categoryIndex);
            catDto.setCategoryIndex(cat.categoryIndex);
            for (OverviewChapterComponent comp : cat.components) {
                OverviewPreviewComponentDTO compDto = new OverviewPreviewComponentDTO();
                compDto.setComponentName(comp.componentName);
                compDto.setComponentIndex(comp.componentIndex);
                for (OverviewChapterItem item : comp.items) {
                    OverviewPreviewItemDTO itemDto = new OverviewPreviewItemDTO();
                    itemDto.setNumber(item.number);
                    itemDto.setText(item.text);
                    compDto.getItems().add(itemDto);
                }
                catDto.getChapter2Components().add(compDto);
            }
        }
        for (OverviewChapterCategory cat : content.chapter3Categories()) {
            OverviewPreviewCategoryDTO catDto = merged.computeIfAbsent(cat.category, k -> {
                OverviewPreviewCategoryDTO c = new OverviewPreviewCategoryDTO();
                c.setCategory(k);
                return c;
            });
            catDto.setChapter3CategoryIndex(cat.categoryIndex);
            if (catDto.getChapter2CategoryIndex() == 0) {
                catDto.setCategoryIndex(cat.categoryIndex);
            }
            for (OverviewChapterComponent comp : cat.components) {
                OverviewPreviewComponentDTO compDto = new OverviewPreviewComponentDTO();
                compDto.setComponentName(comp.componentName);
                compDto.setComponentIndex(comp.componentIndex);
                for (OverviewChapterItem item : comp.items) {
                    OverviewPreviewItemDTO itemDto = new OverviewPreviewItemDTO();
                    itemDto.setNumber(item.number);
                    itemDto.setText(item.text);
                    compDto.getItems().add(itemDto);
                }
                catDto.getChapter3Components().add(compDto);
            }
        }
        java.util.LinkedHashSet<String> categoryOrder = new java.util.LinkedHashSet<>();
        for (OverviewChapterCategory c : content.chapter2Categories()) {
            categoryOrder.add(c.category);
        }
        for (OverviewChapterCategory c : content.chapter3Categories()) {
            categoryOrder.add(c.category);
        }
        List<OverviewPreviewCategoryDTO> ordered = new ArrayList<>();
        for (String catName : categoryOrder) {
            OverviewPreviewCategoryDTO catDto = merged.get(catName);
            if (catDto != null) {
                ordered.add(catDto);
            }
        }
        dto.setCategories(ordered);
        return dto;
    }

    @Override
    public ProjectOverviewPreviewDTO buildProjectOverviewPreview(Project project) {
        Objects.requireNonNull(project, "项目对象不能为null");
        if (project.getReports() == null || project.getReports().isEmpty()) {
            throw new IllegalArgumentException("项目没有可生成的报告");
        }
        return toOverviewPreviewDto(buildOverviewSummaryContent(project, false));
    }

    private String formatOverviewChapter2ProblemText(ReportInfo ri, String componentName) {
        String compName = (ri.componentName != null && !ri.componentName.isEmpty()) ? ri.componentName : componentName;
        if (ri.overviewDefectLineResolved != null && !ri.overviewDefectLineResolved.isBlank()) {
            return ri.overviewDefectLineResolved.trim();
        }
        return ri.experimentTypeName + "中发现" + compName + "存在缺陷，详情请见单项报告"
                + ri.reportNumber + "。";
    }

    private String formatOverviewChapter3WorkLine(ReportInfo ri) {
        if (ri.overviewWorkContentLineOverride != null && !ri.overviewWorkContentLineOverride.isBlank()) {
            return applyCurrentReportNumberToOverviewWorkLine(
                    ri.overviewWorkContentLineOverride.trim(),
                    ri.reportNumber != null ? ri.reportNumber : "");
        }
        String narrative = ri.detectionContentNarrative;
        String detailText = (narrative != null && !narrative.trim().isEmpty())
                ? narrative.trim()
                : detectionContentNarrativeService.buildDetectionDetailText(
                ri.methodName != null ? ri.methodName : ri.experimentTypeName,
                ri.componentName, ri.type, ri.total, ri.locationDesc, ri.locationNumber,
                true, ri.experimentTypeName, ri.experimentTypeCode);
        String reportRefTail = OVERVIEW_WORK_REPORT_REF_MARKER + ri.reportNumber + "。";
        return stripOverviewWorkFigurePhrases(detailText.isEmpty()
                ? ri.experimentTypeName + reportRefTail
                : detailText + reportRefTail);
    }

