        SummaryTocEntry e = tocQueue.poll();
        if (e != null) {
            addBoldTitleParagraph(document, "1 概述", 1, e.bookmark, bookmarkIdGen);
        } else {
            log.warn("generateOverview: missing summary TOC entry");
            addBoldTitleParagraph(document, "1 概述", 1);
        }
        String description = project != null && project.getDescription() != null
                ? project.getDescription().trim() : "";
        if (!description.isEmpty()) {
            addIndentedParagraph(document, description);
        } else {
            addParagraph(document, "");
        }
